	s.Push(1)
	s.Push(2)
	if s.Len() != 2 { t.Errorf("expected len 2, got %d", s.Len()) }
	v, ok := s.Pop()
	if !ok || v != 2 { t.Errorf("expected 2, got %d", v) }
	v, ok = s.Peek()
	if !ok || v != 1 { t.Errorf("expected peek 1, got %d", v) }
	s.Pop()
	_, ok = s.Pop()
	if ok { t.Error("expected false on empty pop") }
