function luhnCheck(num) {
  var str = String(num).replace(/\D/g, '');
  var sum = 0, alt = false;
  for (var i = str.length - 1; i >= 0; i--) {
    var n = parseInt(str[i], 10);
    if (alt) { n *= 2; if (n > 9) n -= 9; }
    sum += n;
    alt = !alt;
  }
  return sum % 10 === 0;
}

