    if (dir && fs.existsSync(dir)) fs.rmSync(dir, { recursive: true, force: true });
  });

  it('findByRuleId reads the rule: tag convention', () => {
    lib.register({
      name: 'safe-sort',
      code: 'function f(a) { return [...a].sort(); }',
      language: 'javascript',
      tags: ['immutable', 'rule:state-mutation/sort'],
    });
