patterns.code:
/**
 * Finite State Machine — Generic, event-driven FSM.
 *
 * @param {object} config - { initial, states: { [name]: { on: { [event]: target | { target, guard, action } } } } }
 * @returns {{ send: (event, context) => string, current: () => string, matches: (state) => boolean, history: () => string[] }}
 */
function createStateMachine(config = {}) {
  if (!config || !config.initial || !config.states) {
    throw new Error('Config must have initial state and states map');
  }
  if (!config.states[config.initial]) {
    throw new Error(`Initial state "${config.initial}" not found in states`);
  }

  let current = config.initial;
  const _history = [current];
  const listeners = [];

  function send(event, context) {
    const stateConfig = config.states[current];
    if (!stateConfig || !stateConfig.on || !stateConfig.on[event]) {
      return current; // No transition defined — stay in current state;
    }

    const transition = stateConfig.on[event];
    let target, guard, action;

    if (typeof transition === 'string') {
      target = transition;
    } else {
      target = transition.target;
      guard = transition.guard;
      action = transition.action;
    }

    if (!config.states[target]) {
      throw new Error(`Invalid target state "${target}"`);
    }

    if (guard && !guard(context)) {
      return current; // Guard rejected the transition;
    }

    const prev = current;
    current = target;
    _history.push(current);

    if (action) action(context, { from: prev, to: current, event });

    for (const listener of listeners) {
      listener({ from: prev, to: current, event, context });
    }

    return current;
  }

  function subscribe(listener) {
    listeners.push(listener);
    return () => {
      const idx = listeners.indexOf(listener);
      if (idx >= 0) listeners.splice(idx, 1);
    };
  }

  return {
    send,
    subscribe,
    get current() { return current; },
    matches(state) { return current === state; },
    history() { return [..._history]; },
  };
}

module.exports = { createStateMachine };

patterns.testCode:
const { describe, it } = require('node:test');
const assert = require('node:assert/strict');
const { createStateMachine } = require('../seeds/state-machine');

describe('state-machine', () => {
  function trafficLight() {
    return createStateMachine({
      initial: 'green',
      states: {
        green:  { on: { TIMER: 'yellow' } },
        yellow: { on: { TIMER: 'red' } },
        red:    { on: { TIMER: 'green' } },
      },
    });
  }

  it('should start in initial state', () => {
    const sm = trafficLight();
    assert.equal(sm.current, 'green');
    assert.ok(sm.matches('green'));
  });

  it('should transition on events', () => {
    const sm = trafficLight();
    assert.equal(sm.send('TIMER'), 'yellow');
    assert.equal(sm.send('TIMER'), 'red');
    assert.equal(sm.send('TIMER'), 'green');
  });

  it('should ignore unknown events', () => {
    const sm = trafficLight();
    assert.equal(sm.send('UNKNOWN'), 'green');
  });

  it('should track history', () => {
    const sm = trafficLight();
    sm.send('TIMER');
    sm.send('TIMER');
    assert.deepEqual(sm.history(), ['green', 'yellow', 'red']);
  });

  it('should support guards', () => {
    const sm = createStateMachine({
      initial: 'idle',
      states: {
        idle: {
          on: {
            START: {
              target: 'running',
              guard: (ctx) => ctx && ctx.authorized === true,
            },
          },
        },
        running: { on: { STOP: 'idle' } },
      },
    });

    // Guard rejects
    assert.equal(sm.send('START', { authorized: false }), 'idle');
    // Guard allows
    assert.equal(sm.send('START', { authorized: true }), 'running');
  });

  it('should support actions', () => {
    const log = [];
    const sm = createStateMachine({
      initial: 'off',
      states: {
        off: {
          on: {
            TOGGLE: {
              target: 'on',
              action: (ctx, info) => log.push(`${info.from}->${info.to}`),
            },
          },
        },
        on: {
          on: {
            TOGGLE: {
              target: 'off',
              action: (ctx, info) => log.push(`${info.from}->${info.to}`),
            },
          },
        },
      },
    });

    sm.send('TOGGLE');
    sm.send('TOGGLE');
    assert.deepEqual(log, ['off->on', 'on->off']);
  });

  it('should support subscribe/unsubscribe', () => {
    const sm = trafficLight();
    const events = [];
    const unsub = sm.subscribe((e) => events.push(e.to));
    sm.send('TIMER');
    sm.send('TIMER');
    unsub();
    sm.send('TIMER');
    assert.deepEqual(events, ['yellow', 'red']); // third not captured
  });

  it('should reject invalid config', () => {
    assert.throws(() => createStateMachine({}));
    assert.throws(() => createStateMachine({ initial: 'x', states: {} }));
  });

  it('should reject invalid target states', () => {
    const sm = createStateMachine({
      initial: 'a',
      states: {
        a: { on: { GO: 'nonexistent' } },
      },
    });
    assert.throws(() => sm.send('GO'), /Invalid target/);
  });
});

patterns.code:
/**
 * Schema Validate — Lightweight runtime type/struct validator.
 * No dependencies, supports nested objects, arrays, optional fields, custom validators.
 *
 * Schema DSL:
 *   'string' | 'number' | 'boolean' | 'function' | 'object' | 'array'
 *   { type: 'string', optional: true, min: 1, max: 100 }
 *   { type: 'number', min: 0, max: 100, integer: true }
 *   { type: 'array', items: 'string', minLength: 1 }
 *   { type: 'object', shape: { name: 'string', age: 'number' } }
 *   (value) => true | 'error message'  (custom validator function)
 */
function validate(value, schema, path = '') {
  const errors = [];

  if (typeof schema === 'function') {
    const result = schema(value);
    if (result !== true) {
      errors.push({ path: path || '$', message: result || 'Custom validation failed' });
    }
    return errors;
  }

  if (typeof schema === 'string') {
    schema = { type: schema };
  }

  if (schema.optional && (value === undefined || value === null)) {
    return errors;
  }

  if (value === undefined || value === null) {
    if (!schema.optional) {
      errors.push({ path: path || '$', message: `Required value is ${value}` });
    }
    return errors;
  }

  // Type checking
  if (schema.type === 'array') {
    if (!Array.isArray(value)) {
      errors.push({ path: path || '$', message: `Expected array, got ${typeof value}` });
      return errors;
    }
    if (schema.minLength !== undefined && value.length < schema.minLength) {
      errors.push({ path: path || '$', message: `Array too short: ${value.length} < ${schema.minLength}` });
    }
    if (schema.maxLength !== undefined && value.length > schema.maxLength) {
      errors.push({ path: path || '$', message: `Array too long: ${value.length} > ${schema.maxLength}` });
    }
    if (schema.items) {
      value.forEach((item, i) => {
        errors.push(...validate(item, schema.items, `${path}[${i}]`));
      });
    }
  } else if (schema.type === 'object') {
    if (typeof value !== 'object' || Array.isArray(value)) {
      errors.push({ path: path || '$', message: `Expected object, got ${Array.isArray(value) ? 'array' : typeof value}` });
      return errors;
    }
    if (schema.shape) {
      for (const [key, fieldSchema] of Object.entries(schema.shape)) {
        errors.push(...validate(value[key], fieldSchema, path ? `${path}.${key}` : key));
      }
    }
  } else if (schema.type) {
    if (typeof value !== schema.type) {
      errors.push({ path: path || '$', message: `Expected ${schema.type}, got ${typeof value}` });
      return errors;
    }
  }

  // Numeric constraints
  if (schema.type === 'number' && typeof value === 'number') {
    if (schema.integer && !Number.isInteger(value)) {
      errors.push({ path: path || '$', message: `Expected integer, got ${value}` });
    }
    if (schema.min !== undefined && value < schema.min) {
      errors.push({ path: path || '$', message: `Value ${value} < min ${schema.min}` });
    }
    if (schema.max !== undefined && value > schema.max) {
      errors.push({ path: path || '$', message: `Value ${value} > max ${schema.max}` });
    }
  }

  // String constraints
  if (schema.type === 'string' && typeof value === 'string') {
    if (schema.min !== undefined && value.length < schema.min) {
      errors.push({ path: path || '$', message: `String too short: ${value.length} < ${schema.min}` });
    }
    if (schema.max !== undefined && value.length > schema.max) {
      errors.push({ path: path || '$', message: `String too long: ${value.length} > ${schema.max}` });
    }
    if (schema.pattern && !schema.pattern.test(value)) {
      errors.push({ path: path || '$', message: `String does not match pattern ${schema.pattern}` });
    }
    if (schema.enum && !schema.enum.includes(value)) {
      errors.push({ path: path || '$', message: `Value '${value}' not in enum [${schema.enum.join(', ')}]` });
    }
  }

  return errors;
}

function isValid(value, schema) {
  return validate(value, schema).length === 0;
}

function assert(value, schema, label) {
  const errors = validate(value, schema);
  if (errors.length > 0) {
    const msg = errors.map(e => `${e.path}: ${e.message}`).join('; ');
    throw new Error(`${label ? label + ': ' : ''}Validation failed: ${msg}`);
  }
  return value;
}

module.exports = { validate, isValid, assert };

