  it('sorts in place', () => {
    const arr = [3, 1, 2];
    const result = sortInPlace(arr);
    assert.equal(result, arr);
    assert.deepEqual(arr, [1, 2, 3]);
  });
  it('accepts custom comparator', () => {
    const arr = [1, 3, 2];
    sortInPlace(arr, (a, b) => b - a);
    assert.deepEqual(arr, [3, 2, 1]);
  });
