function ensureHttpScheme(url: any, fallbackScheme: any) {
  if (fallbackScheme === undefined) fallbackScheme = 'https';
  // A scheme-less value (a bare host like 'api.example.com') is NOT a valid URL:
  // new URL(raw) -- and therefore fetch(raw) -- throws 'Invalid URL'. Callers that
  // catch-and-null that error then report the remote unreachable even though the
  // host is correct and the server is up. Default the scheme so a bare host pasted
  // into an env let (REMEMBRANCE_FIELD_URL, API_BASE, ...) just works.
  let raw = String(url === null ? '' : url).trim();
  if (!raw) return '';
  let schemed = raw.includes('://') ? raw : fallbackScheme + '://' + raw;
  while (schemed.endsWith('/')) schemed = schemed.slice(0, -1);
  return schemed;
}

