if (!threw) throw new Error('scheme-less URL must throw in new URL()/fetch()');
var u = new URL(ensureHttpScheme(bare) + '/mcp');
if (u.protocol !== 'https:' || u.hostname !== bare) throw new Error('normalized URL wrong: ' + u.href);
