function groupBy(array, keyFn) {
  const result = {};
  for (let i = 0; i < array.length; i++) {
    const key = keyFn(array[i]);
    if (!result[key]) {
      result[key] = [];
    }
    result[key].push(array[i]);
  }
  return result;
}

