/**
 * Observable — reactive value with subscriptions
 * createObservable(initialValue) → { get, set, subscribe, unsubscribe }
 */
function createObservable(initialValue) {
  let value = initialValue;
  const listeners = new Map();
  let nextId = 0;

  function get() {
    return value;
  }

  function set(newValue) {
    const oldValue = value;
    value = newValue;
    for (const [, listener] of listeners) {
      listener(newValue, oldValue);
    }
  }

  function subscribe(listener) {
    const id = nextId++;
    listeners.set(id, listener);
    return id;
  }

  function unsubscribe(id) {
    return listeners.delete(id);
  }

  return { get, set, subscribe, unsubscribe };
}

module.exports = { createObservable };

// Back-to-top — scroll-to-top with throttled visibility detection
// Appears after scrolling past threshold, smooth scrolls to top

function createBackToTop(threshold = 300, throttleMs = 150) {
  let visible = false;
  let lastCall = 0;

  function checkVisibility() {
    const now = Date.now();
    if (now - lastCall < throttleMs) return visible;
    lastCall = now;
    visible = (typeof window !== 'undefined') && window.scrollY > threshold;
    return visible;
  }

  function scrollToTop() {
    if (typeof window !== 'undefined') {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  }

  return { checkVisibility, scrollToTop, get visible() { return visible; } };
}

module.exports = { createBackToTop };

// Guarded API helpers — abort-safe, single-flight request pattern
// Wraps fetch to enforce guarded access (no raw fetch in components)

function createApiClient(fetchFn) {
  async function apiGet(url, signal) {
    const res = await fetchFn(url, { signal });
    if (!res.ok) {
      const body = await res.json().catch(() => null);
      throw new Error((body && body.error) || `GET ${url} failed (${res.status})`);
    }
    return res.json();
  }

  async function apiPost(url, data, signal) {
    const res = await fetchFn(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data),
      signal,
    });
    if (!res.ok) {
      const body = await res.json().catch(() => null);
      throw new Error((body && body.error) || `POST ${url} failed (${res.status})`);
    }
    return res.json();
  }

  return { apiGet, apiPost };
}

module.exports = { createApiClient };

/**
 * Generates an array of numbers from start (inclusive) to end (exclusive).
 * @param {number} start - The start of the range.
 * @param {number} end - The end of the range (exclusive).
 * @param {number} [step=1] - The step between values.
 * @returns {number[]} An array of numbers.
 */
function range(start, end, step) {
  if (step === 0) {
    throw new RangeError('step must not be zero');
  }
  const s = step !== undefined ? step : (start <= end ? 1 : -1);
  const result = [];
  if (s > 0) {
    for (let i = start; i < end; i += s) {
      result.push(i);
    }
  } else {
    for (let i = start; i > end; i += s) {
      result.push(i);
    }
  }
  return result;
}

module.exports = range;

/**
 * compose - Composes functions right to left.
 * compose(f, g, h)(x) === f(g(h(x)))
 * @param {...Function} fns - Functions to compose
 * @returns {Function} Composed function
 */
function compose(...fns) {
  if (fns.length === 0) return (x) => x;
  return function (...args) {
    let result = fns[fns.length - 1].apply(this, args);
    for (let i = fns.length - 2; i >= 0; i--) {
      result = fns[i](result);
    }
    return result;
  };
}

module.exports = { compose };

/**
 * Set Operations — union, intersection, difference, symmetricDifference for arrays
 */
function union(a, b) {
  return [...new Set([...a, ...b])];
}

function intersection(a, b) {
  const setB = new Set(b);
  return [...new Set(a.filter(item => setB.has(item)))];
}

function difference(a, b) {
  const setB = new Set(b);
  return [...new Set(a.filter(item => !setB.has(item)))];
}

function symmetricDifference(a, b) {
  const setA = new Set(a);
  const setB = new Set(b);
  const result = [];
  for (const item of setA) {
    if (!setB.has(item)) result.push(item);
  }
  for (const item of setB) {
    if (!setA.has(item)) result.push(item);
  }
  return result;
}

module.exports = { union, intersection, difference, symmetricDifference };

/**
 * countOccurrences - Counts the number of non-overlapping occurrences of a substring in a string.
 * @param {string} str - The string to search in.
 * @param {string} substr - The substring to count.
 * @returns {number} The number of occurrences.
 */
function countOccurrences(str, substr) {
  if (typeof str !== 'string' || typeof substr !== 'string') return 0;
  if (substr.length === 0) return 0;
  let count = 0;
  let pos = 0;
  while (true) {
    const idx = str.indexOf(substr, pos);
    if (idx === -1) break;
    count++;
    pos = idx + substr.length;
  }
  return count;
}

module.exports = countOccurrences;

/**
 * lcs - Find the longest common subsequence of two strings.
 * @param {string} str1 - First string.
 * @param {string} str2 - Second string.
 * @returns {string} The longest common subsequence.
 */
function lcs(str1, str2) {
  const m = str1.length;
  const n = str2.length;

  // Build the DP table
  const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));

  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      if (str1[i - 1] === str2[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
      }
    }
  }

  // Backtrack to find the actual subsequence
  let result = '';
  let i = m;
  let j = n;

  while (i > 0 && j > 0) {
    if (str1[i - 1] === str2[j - 1]) {
      result = str1[i - 1] + result;
      i--;
      j--;
    } else if (dp[i - 1][j] > dp[i][j - 1]) {
      i--;
    } else {
      j--;
    }
  }

  return result;
}

module.exports = lcs;

/**
 * truncate - Truncates a string to a maximum length, appending a suffix if truncated.
 * @param {string} str - The string to truncate.
 * @param {number} maxLen - The maximum length of the output string (including suffix).
 * @param {string} [suffix='...'] - The suffix to append when truncated.
 * @returns {string} The truncated string.
 */
function truncate(str, maxLen, suffix = '...') {
  if (typeof str !== 'string') return '';
  if (str.length <= maxLen) return str;
  const end = maxLen - suffix.length;
  if (end < 0) return suffix.slice(0, maxLen);
  return str.slice(0, end) + suffix;
}

module.exports = truncate;

/**
 * Clamps a number within an inclusive range.
 * @param {number} value - The number to clamp.
 * @param {number} min - The lower bound.
 * @param {number} max - The upper bound.
 * @returns {number} The clamped value.
 */
function clamp(value, min, max) {
  if (min > max) {
    throw new RangeError('min must be less than or equal to max');
  }
  return Math.min(Math.max(value, min), max);
}

module.exports = clamp;

/**
 * Checks whether a value is empty.
 * Returns true for null, undefined, empty string, empty array, and empty object.
 * @param {*} val - The value to check.
 * @returns {boolean} True if the value is empty.
 */
function isEmpty(val) {
  if (val === null || val === undefined) {
    return true;
  }
  if (typeof val === 'string' || Array.isArray(val)) {
    return val.length === 0;
  }
  if (typeof val === 'object') {
    return Object.keys(val).length === 0;
  }
  return false;
}

module.exports = isEmpty;

/**
 * isPalindrome - Checks if a string is a palindrome (case-insensitive, ignoring non-alphanumeric chars).
 * @param {string} str - The string to check.
 * @returns {boolean} True if the string is a palindrome.
 */
function isPalindrome(str) {
  if (typeof str !== 'string') return false;
  const cleaned = str.toLowerCase().replace(/[^a-z0-9]/g, '');
  if (cleaned.length === 0) return true;
  const reversed = cleaned.split('').reverse().join('');
  return cleaned === reversed;
}

module.exports = isPalindrome;

/**
 * maskString - Masks a string, leaving only the last N characters visible.
 * @param {string} str - The string to mask.
 * @param {number} [visibleChars=4] - Number of characters to leave visible at the end.
 * @param {string} [maskChar='*'] - The character to use for masking.
 * @returns {string} The masked string.
 */
function maskString(str, visibleChars = 4, maskChar = '*') {
  if (typeof str !== 'string') return '';
  if (str.length <= visibleChars) return str;
  const masked = maskChar.charAt(0).repeat(str.length - visibleChars);
  return masked + str.slice(-visibleChars);
}

module.exports = maskString;

/**
 * retry - Retries an async function on failure up to maxAttempts times.
 * @param {Function} fn - Async function to retry
 * @param {number} [maxAttempts=3] - Maximum number of attempts
 * @param {number} [delayMs=100] - Delay between retries in milliseconds
 * @returns {Promise<*>} Result of fn on success
 */
function retry(fn, maxAttempts = 3, delayMs = 100) {
  return new Promise((resolve, reject) => {
    let attempts = 0;

    function attempt() {
      attempts++;
      Promise.resolve()
        .then(() => fn())
        .then(resolve)
        .catch((err) => {
          if (attempts >= maxAttempts) {
            reject(err);
          } else {
            setTimeout(attempt, delayMs);
          }
        });
    }

    attempt();
  });
}

module.exports = { retry };

/**
 * Returns the median value of an array of numbers.
 * For even-length arrays, returns the average of the two middle values.
 * @param {number[]} array - The array of numbers.
 * @returns {number} The median value.
 */
function median(array) {
  if (array.length === 0) {
    return NaN;
  }
  const sorted = array.slice().sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  if (sorted.length % 2 === 0) {
    return (sorted[mid - 1] + sorted[mid]) / 2;
  }
  return sorted[mid];
}

module.exports = median;

/**
 * Returns the arithmetic mean (average) of an array of numbers.
 * @param {number[]} array - The array of numbers.
 * @returns {number} The average value.
 */
function mean(array) {
  if (array.length === 0) {
    return NaN;
  }
  return array.reduce((acc, val) => acc + val, 0) / array.length;
}

module.exports = mean;

/**
 * padEnd - Pads a string from the end to a specified length.
 * @param {string} str - The string to pad.
 * @param {number} len - The desired total length.
 * @param {string} [char=' '] - The character to pad with (first char used if longer).
 * @returns {string} The padded string.
 */
function padEnd(str, len, char = ' ') {
  if (typeof str !== 'string') return '';
  if (str.length >= len) return str;
  const padChar = char.charAt(0) || ' ';
  const needed = len - str.length;
  return str + padChar.repeat(needed);
}

module.exports = padEnd;

/**
 * wordCount - Counts the number of words in a string.
 * @param {string} str - The string to count words in.
 * @returns {number} The number of words.
 */
function wordCount(str) {
  if (typeof str !== 'string') return 0;
  const trimmed = str.trim();
  if (trimmed.length === 0) return 0;
  return trimmed.split(/\s+/).length;
}

module.exports = wordCount;

/**
 * insertionSort - Sort an array using the insertion sort algorithm.
 * @param {number[]} arr - The array to sort.
 * @returns {number[]} A new sorted array.
 */
function insertionSort(arr) {
  const result = arr.slice();

  for (let i = 1; i < result.length; i++) {
    const current = result[i];
    let j = i - 1;

    while (j >= 0 && result[j] > current) {
      result[j + 1] = result[j];
      j--;
    }

    result[j + 1] = current;
  }

  return result;
}

module.exports = insertionSort;

/**
 * slugify - Converts a string into a URL-safe slug.
 * @param {string} str - The string to slugify.
 * @returns {string} A URL-safe slug.
 */
function slugify(str) {
  if (typeof str !== 'string') return '';
  return str
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, '')
    .replace(/[\s_]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');
}

module.exports = slugify;

/**
 * capitalize - Capitalizes the first letter of a string.
 * @param {string} str - The string to capitalize.
 * @returns {string} The string with the first letter uppercase.
 */
function capitalize(str) {
  if (typeof str !== 'string' || str.length === 0) return '';
  return str.charAt(0).toUpperCase() + str.slice(1);
}

module.exports = capitalize;

/**
 * bubbleSort - Sort an array using the bubble sort algorithm.
 * @param {number[]} arr - The array to sort.
 * @returns {number[]} A new sorted array.
 */
function bubbleSort(arr) {
  const result = arr.slice();
  let swapped;

  do {
    swapped = false;
    for (let i = 0; i < result.length - 1; i++) {
      if (result[i] > result[i + 1]) {
        const temp = result[i];
        result[i] = result[i + 1];
        result[i + 1] = temp;
        swapped = true;
      }
    }
  } while (swapped);

  return result;
}

module.exports = bubbleSort;

/**
 * after - Creates a function that only executes after being called n times.
 * Before n calls, returns undefined.
 * @param {number} n - Number of calls before fn executes
 * @param {Function} fn - Function to invoke after n calls
 * @returns {Function} Wrapped function
 */
function after(n, fn) {
  let count = 0;

  return function (...args) {
    count++;
    if (count >= n) {
      return fn.apply(this, args);
    }
    return undefined;
  };
}

module.exports = { after };

/**
 * memoizeWithTTL - Memoizes a function with a time-to-live cache.
 * Cached results expire after ttl milliseconds.
 * @param {Function} fn - Function to memoize
 * @param {number} ttl - Time-to-live for cache entries in milliseconds
 * @returns {Function} Memoized function
 */
function memoizeWithTTL(fn, ttl) {
  const cache = new Map();

  return function (...args) {
    const key = JSON.stringify(args);
    const now = Date.now();

    if (cache.has(key)) {
      const entry = cache.get(key);
      if (now - entry.timestamp < ttl) {
        return entry.value;
      }
      cache.delete(key);
    }

    const value = fn.apply(this, args);
    cache.set(key, { value, timestamp: now });
    return value;
  };
}

module.exports = { memoizeWithTTL };

/**
 * Returns a shuffled copy of the array using the Fisher-Yates algorithm.
 * Does not mutate the original array.
 * @param {Array} array - The array to shuffle.
 * @returns {Array} A new shuffled array.
 */
function shuffle(array) {
  const result = array.slice();
  for (let i = result.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const temp = result[i];
    result[i] = result[j];
    result[j] = temp;
  }
  return result;
}

module.exports = shuffle;

/**
 * Zips two arrays into an array of pairs.
 * The result length equals the shorter array.
 * @param {Array} arr1 - The first array.
 * @param {Array} arr2 - The second array.
 * @returns {Array[]} An array of [a, b] pairs.
 */
function zip(arr1, arr2) {
  const len = Math.min(arr1.length, arr2.length);
  const result = [];
  for (let i = 0; i < len; i++) {
    result.push([arr1[i], arr2[i]]);
  }
  return result;
}

module.exports = zip;

/**
 * kebabToCamel - Converts a kebab-case string to camelCase.
 * @param {string} str - The kebab-case string to convert.
 * @returns {string} The camelCase version of the input string.
 */
function kebabToCamel(str) {
  if (typeof str !== 'string') return '';
  return str.replace(/-([a-z])/g, (_, char) => char.toUpperCase());
}

module.exports = kebabToCamel;

/**
 * reverseString - Reverses a string.
 * @param {string} str - The string to reverse.
 * @returns {string} The reversed string.
 */
function reverseString(str) {
  if (typeof str !== 'string') return '';
  return str.split('').reverse().join('');
}

module.exports = reverseString;

/**
 * titleCase - Converts a string so that each word starts with an uppercase letter.
 * @param {string} str - The string to title-case.
 * @returns {string} The title-cased string.
 */
function titleCase(str) {
  if (typeof str !== 'string') return '';
  return str.replace(/\b\w/g, (char) => char.toUpperCase());
}

module.exports = titleCase;

/**
 * Splits an array into chunks of a given size.
 * @param {Array} array - The array to chunk.
 * @param {number} size - The size of each chunk.
 * @returns {Array[]} An array of chunked subarrays.
 */
function chunk(array, size) {
  if (!Number.isInteger(size) || size < 1) {
    throw new RangeError('size must be a positive integer');
  }
  const result = [];
  for (let i = 0; i < array.length; i += size) {
    result.push(array.slice(i, i + size));
  }
  return result;
}

module.exports = chunk;

/**
 * unescapeHtml - Unescapes HTML entities back to their original characters.
 * @param {string} str - The HTML-escaped string to unescape.
 * @returns {string} The unescaped string.
 */
function unescapeHtml(str) {
  if (typeof str !== 'string') return '';
  const map = {
    '&amp;': '&',
    '&lt;': '<',
    '&gt;': '>',
    '&quot;': '"',
    '&#39;': "'"
  };
  return str.replace(/&amp;|&lt;|&gt;|&quot;|&#39;/g, (entity) => map[entity]);
}

module.exports = unescapeHtml;

/**
 * createRateLimiter - Creates a rate limiter that allows maxCalls within windowMs.
 * @param {number} maxCalls - Maximum number of calls allowed in the window
 * @param {number} windowMs - Time window in milliseconds
 * @returns {{ tryCall: Function }} Object with tryCall() that returns true/false
 */
function createRateLimiter(maxCalls, windowMs) {
  const timestamps = [];

  return {
    tryCall() {
      const now = Date.now();
      // Remove timestamps outside the window
      while (timestamps.length > 0 && now - timestamps[0] >= windowMs) {
        timestamps.shift();
      }

      if (timestamps.length < maxCalls) {
        timestamps.push(now);
        return true;
      }
      return false;
    }
  };
}

module.exports = { createRateLimiter };

/**
 * timeoutPromise - Wraps a promise with a timeout. Rejects if the promise
 * does not settle within the given milliseconds.
 * @param {Promise} promise - The promise to wrap
 * @param {number} ms - Timeout in milliseconds
 * @returns {Promise<*>} Resolves with promise value or rejects on timeout
 */
function timeoutPromise(promise, ms) {
  return new Promise((resolve, reject) => {
    let settled = false;

    const timer = setTimeout(() => {
      if (!settled) {
        settled = true;
        reject(new Error(`Timed out after ${ms}ms`));
      }
    }, ms);

    Promise.resolve(promise)
      .then((val) => {
        if (!settled) {
          settled = true;
          clearTimeout(timer);
          resolve(val);
        }
      })
      .catch((err) => {
        if (!settled) {
          settled = true;
          clearTimeout(timer);
          reject(err);
        }
      });
  });
}

module.exports = { timeoutPromise };

/**
 * before - Creates a function that only executes for the first n calls.
 * After n calls, returns the last successful result.
 * @param {number} n - Maximum number of times fn will execute
 * @param {Function} fn - Function to invoke
 * @returns {Function} Wrapped function
 */
function before(n, fn) {
  let count = 0;
  let lastResult;

  return function (...args) {
    count++;
    if (count <= n) {
      lastResult = fn.apply(this, args);
    }
    return lastResult;
  };
}

module.exports = { before };

/**
 * curry - Returns a curried version of the given function.
 * Curried function can be called with any number of arguments
 * and returns a new function until all arguments are collected.
 * @param {Function} fn - Function to curry
 * @returns {Function} Curried function
 */
function curry(fn) {
  const arity = fn.length;

  function curried(...args) {
    if (args.length >= arity) {
      return fn.apply(this, args);
    }
    return function (...moreArgs) {
      return curried.apply(this, args.concat(moreArgs));
    };
  }

  return curried;
}

module.exports = { curry };

/**
 * once - Creates a function that runs only on the first call.
 * Subsequent calls return the result of the first invocation.
 * @param {Function} fn - Function to call once
 * @returns {Function} Wrapped function
 */
function once(fn) {
  let called = false;
  let result;

  return function (...args) {
    if (!called) {
      called = true;
      result = fn.apply(this, args);
    }
    return result;
  };
}

module.exports = { once };

/**
 * Authentication & Authorization Module
 *
 * Token-based auth with role-based access control for the Oracle dashboard
 * and MCP server. Uses ONLY Node.js built-in crypto — no external dependencies.
 *
 * Storage: SQLite (node:sqlite DatabaseSync) when available, falls back to
 * in-memory Map for testing or environments without SQLite.
 *
 * Roles:
 *   admin       — full access (manage users, modify patterns, view everything)
 *   contributor — submit/register patterns, search, view
 *   viewer      — search and view only
 */

const crypto = require('crypto');

// ─── Constants ───

const ROLES = Object.freeze({
  ADMIN: 'admin',
  CONTRIBUTOR: 'contributor',
  VIEWER: 'viewer',
});

const VALID_ROLES = new Set([ROLES.ADMIN, ROLES.CONTRIBUTOR, ROLES.VIEWER]);

const SCRYPT_KEYLEN = 64;
const SALT_BYTES = 16;
const TOKEN_BYTES = 32;

const DEFAULT_ADMIN_USERNAME = 'admin';

/** Admin password from env, or auto-generated if unset. */
function _getDefaultAdminPassword() {
  if (process.env.ORACLE_ADMIN_PASSWORD) return process.env.ORACLE_ADMIN_PASSWORD;
  // Generate a random password so we never ship with a known default
  return crypto.randomBytes(16).toString('hex');
}

/** Paths that don't require authentication. */
const publicPaths = ['/api/health', '/health', '/favicon.ico'];

// ─── Permission helpers ───

function canRead(user) {
  return user != null && VALID_ROLES.has(user.role);
}

function canWrite(user) {
  return user != null && (user.role === ROLES.ADMIN || user.role === ROLES.CONTRIBUTOR);
}

function canManageUsers(user) {
  return user != null && user.role === ROLES.ADMIN;
}

// ─── Crypto helpers ───

function generateId() {
  return crypto.randomBytes(16).toString('hex');
}

function generateToken() {
  return crypto.randomBytes(TOKEN_BYTES).toString('hex');
}

function generateSalt() {
  return crypto.randomBytes(SALT_BYTES).toString('hex');
}

function hashPassword(password, salt) {
  const derived = crypto.scryptSync(password, salt, SCRYPT_KEYLEN);
  return derived.toString('hex');
}

function verifyPassword(password, salt, storedHash) {
  const derived = crypto.scryptSync(password, salt, SCRYPT_KEYLEN);
  const candidateHash = derived.toString('hex');
  // Constant-time comparison to prevent timing attacks
  if (candidateHash.length !== storedHash.length) return false;
  try {
    return crypto.timingSafeEqual(
      Buffer.from(candidateHash, 'hex'),
      Buffer.from(storedHash, 'hex')
    );
  } catch (_) {
    // Buffer length mismatch (e.g. corrupted storedHash with non-hex chars)
    return false;
  }
}

// ─── AuthManager ───

class AuthManager {
  /**
   * @param {object} [sqliteStore] — SQLiteStore instance (or any object exposing
   *   a `.db` property that is a DatabaseSync). When omitted, all user data lives
   *   in an in-memory Map and tokens in a Map — suitable for tests.
   */
  constructor(sqliteStore) {
    /** token -> { userId, createdAt } */
    this._tokens = new Map();
    this._TOKEN_MAX_AGE_MS = 24 * 60 * 60 * 1000; // 24 hours
    this._TOKEN_MAX_COUNT = 10000; // hard cap to prevent unbounded growth
    this._backend = 'memory';

    if (sqliteStore && sqliteStore.db) {
      this._db = sqliteStore.db;
      this._backend = 'sqlite';
      this._initSchema();
    } else {
      /** In-memory users store: id -> user object (with password_hash, salt) */
      this._users = new Map();
      /** Secondary index: username -> id */
      this._byUsername = new Map();
      /** Secondary index: apiKey -> id */
      this._byApiKey = new Map();
    }

    this._ensureDefaultAdmin();
  }

  // ─── Schema (SQLite) ───

  _initSchema() {
    this._db.exec(`
      CREATE TABLE IF NOT EXISTS users (
        id TEXT PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        salt TEXT NOT NULL,
        role TEXT DEFAULT 'contributor',
        api_key TEXT UNIQUE NOT NULL,
        created_at TEXT NOT NULL,
        updated_at TEXT NOT NULL
      );
    `);
  }

  // ─── Default admin bootstrap ───

  _ensureDefaultAdmin() {
    const users = this.listUsers();
    if (users.length === 0) {
      const password = _getDefaultAdminPassword();
      const admin = this.createUser(DEFAULT_ADMIN_USERNAME, password, ROLES.ADMIN);
      if (process.env.ORACLE_DEBUG) {
        const maskedKey = admin.apiKey ? admin.apiKey.slice(0, 4) + '…' + admin.apiKey.slice(-4) : '(none)';
        if (process.env.ORACLE_ADMIN_PASSWORD) {
          console.log(`[auth] Default admin created (password from ORACLE_ADMIN_PASSWORD). API key: ${maskedKey}`);
        } else {
          console.log(`[auth] Default admin created with generated password (use ORACLE_ADMIN_PASSWORD env var to set a fixed one).`);
          console.log(`[auth] API key: ${maskedKey}`);
        }
      }
    }
  }

  // ─── CRUD ───

  /**
   * Create a new user.
   * @param {string} username
   * @param {string} password
   * @param {string} [role='contributor']
   * @returns {{ id, username, role, apiKey }}
   */
  createUser(username, password, role = ROLES.CONTRIBUTOR) {
    if (!username || typeof username !== 'string') {
      throw new Error('Username is required');
    }
    if (!password || typeof password !== 'string') {
      throw new Error('Password is required');
    }
    if (!VALID_ROLES.has(role)) {
      throw new Error(`Invalid role: ${role}. Must be one of: ${[...VALID_ROLES].join(', ')}`);
    }

    const id = generateId();
    const salt = generateSalt();
    const passwordHash = hashPassword(password, salt);
    const apiKey = generateToken();
    const now = new Date().toISOString();

    if (this._backend === 'sqlite') {
      try {
        this._db.prepare(`
          INSERT INTO users (id, username, password_hash, salt, role, api_key, created_at, updated_at)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        `).run(id, username, passwordHash, salt, role, apiKey, now, now);
      } catch (err) {
        if (err.message && err.message.includes('UNIQUE constraint')) {
          throw new Error(`Username '${username}' already exists`);
        }
        throw err;
      }
    } else {
      // In-memory
      if (this._byUsername.has(username)) {
        throw new Error(`Username '${username}' already exists`);
      }
      this._users.set(id, {
        id, username, password_hash: passwordHash, salt, role, api_key: apiKey,
        created_at: now, updated_at: now,
      });
      this._byUsername.set(username, id);
      this._byApiKey.set(apiKey, id);
    }

    return { id, username, role, apiKey };
  }

  /**
   * Authenticate by username + password. Returns a token and user info, or null.
   * @returns {{ token, user: { id, username, role, apiKey } } | null}
   */
  authenticate(username, password) {
    const row = this._getUserRowByUsername(username);
    if (!row) return null;

    if (!verifyPassword(password, row.salt, row.password_hash)) {
      return null;
    }

    const token = generateToken();
    this._tokens.set(token, { userId: row.id, createdAt: Date.now() });

    // Evict expired tokens to prevent unbounded growth
    this._evictExpiredTokens();

    return {
      token,
      user: {
        id: row.id,
        username: row.username,
        role: row.role,
        apiKey: row.api_key,
      },
    };
  }

  /**
   * Validate a bearer token. Returns user object or null.
   * @returns {{ id, username, role, apiKey } | null}
   */
  validateToken(token) {
    if (!token) return null;
    const entry = this._tokens.get(token);
    if (!entry) return null;
    // Handle both old format (string userId) and new format ({ userId, createdAt })
    const userId = typeof entry === 'string' ? entry : entry.userId;
    const createdAt = typeof entry === 'object' ? entry.createdAt : 0;
    // Expire tokens older than max age
    if (createdAt && Date.now() - createdAt > this._TOKEN_MAX_AGE_MS) {
      this._tokens.delete(token);
      return null;
    }
    return this.getUser(userId);
  }

  /**
   * Validate an API key. Returns user object or null.
   * @returns {{ id, username, role, apiKey } | null}
   */
  validateApiKey(apiKey) {
    if (!apiKey) return null;

    if (this._backend === 'sqlite') {
      const row = this._db.prepare('SELECT * FROM users WHERE api_key = ?').get(apiKey);
      return row ? this._sanitize(row) : null;
    }

    const userId = this._byApiKey.get(apiKey);
    if (!userId) return null;
    return this.getUser(userId);
  }

  /**
   * Get a user by id. Returns sanitized user object (no password) or null.
   * @returns {{ id, username, role, apiKey } | null}
   */
  getUser(id) {
    if (!id) return null;

    if (this._backend === 'sqlite') {
      const row = this._db.prepare('SELECT * FROM users WHERE id = ?').get(id);
      return row ? this._sanitize(row) : null;
    }

    const row = this._users.get(id);
    return row ? this._sanitize(row) : null;
  }

  /**
   * List all users (without passwords).
   * @returns {Array<{ id, username, role, apiKey, createdAt, updatedAt }>}
   */
  listUsers() {
    if (this._backend === 'sqlite') {
      const rows = this._db.prepare('SELECT * FROM users ORDER BY created_at ASC').all();
      return rows.map(r => this._sanitize(r));
    }

    return [...this._users.values()].map(r => this._sanitize(r));
  }

  /**
   * Update a user's role.
   * @returns {{ id, username, role, apiKey } | null}
   */
  updateRole(id, newRole) {
    if (!VALID_ROLES.has(newRole)) {
      throw new Error(`Invalid role: ${newRole}. Must be one of: ${[...VALID_ROLES].join(', ')}`);
    }

    if (this._backend === 'sqlite') {
      const row = this._db.prepare('SELECT * FROM users WHERE id = ?').get(id);
      if (!row) return null;
      const now = new Date().toISOString();
      this._db.prepare('UPDATE users SET role = ?, updated_at = ? WHERE id = ?').run(newRole, now, id);
      return this.getUser(id);
    }

    const row = this._users.get(id);
    if (!row) return null;
    row.role = newRole;
    row.updated_at = new Date().toISOString();
    return this._sanitize(row);
  }

  /**
   * Revoke the current API key and generate a new one.
   * Invalidates the old key immediately.
   * @returns {{ id, username, role, apiKey } | null}
   */
  revokeApiKey(id) {
    const newKey = generateToken();
    const now = new Date().toISOString();

    if (this._backend === 'sqlite') {
      const row = this._db.prepare('SELECT * FROM users WHERE id = ?').get(id);
      if (!row) return null;
      this._db.prepare('UPDATE users SET api_key = ?, updated_at = ? WHERE id = ?').run(newKey, now, id);
      return this.getUser(id);
    }

    const row = this._users.get(id);
    if (!row) return null;
    // Remove old key from secondary index
    this._byApiKey.delete(row.api_key);
    row.api_key = newKey;
    row.updated_at = now;
    this._byApiKey.set(newKey, id);
    return this._sanitize(row);
  }

  /**
   * Delete a user and invalidate all their tokens.
   * @returns {boolean} true if deleted, false if not found
   */
  deleteUser(id) {
    if (this._backend === 'sqlite') {
      const row = this._db.prepare('SELECT * FROM users WHERE id = ?').get(id);
      if (!row) return false;
      this._db.prepare('DELETE FROM users WHERE id = ?').run(id);
      // Purge any active tokens for this user
      this._purgeTokensForUser(id);
      return true;
    }

    const row = this._users.get(id);
    if (!row) return false;
    this._byUsername.delete(row.username);
    this._byApiKey.delete(row.api_key);
    this._users.delete(id);
    this._purgeTokensForUser(id);
    return true;
  }

  /**
   * Remove all active tokens for a given user id.
   */
  _purgeTokensForUser(userId) {
    for (const [token, entry] of this._tokens.entries()) {
      const uid = typeof entry === 'string' ? entry : entry.userId;
      if (uid === userId) {
        this._tokens.delete(token);
      }
    }
  }

  /**
   * Evict expired tokens and enforce hard cap on token count.
   * Prevents unbounded memory growth from accumulated tokens.
   */
  _evictExpiredTokens() {
    const now = Date.now();
    for (const [token, entry] of this._tokens.entries()) {
      const createdAt = typeof entry === 'object' ? entry.createdAt : 0;
      if (createdAt && now - createdAt > this._TOKEN_MAX_AGE_MS) {
        this._tokens.delete(token);
      }
    }
    // Hard cap: if still over limit, remove oldest tokens
    if (this._tokens.size > this._TOKEN_MAX_COUNT) {
      const sorted = [...this._tokens.entries()]
        .sort((a, b) => {
          const aTime = typeof a[1] === 'object' ? a[1].createdAt : 0;
          const bTime = typeof b[1] === 'object' ? b[1].createdAt : 0;
          return aTime - bTime;
        });
      const toRemove = sorted.slice(0, this._tokens.size - this._TOKEN_MAX_COUNT);
      for (const [token] of toRemove) {
        this._tokens.delete(token);
      }
    }
  }

  // ─── Internal helpers ───

  _getUserRowByUsername(username) {
    if (this._backend === 'sqlite') {
      return this._db.prepare('SELECT * FROM users WHERE username = ?').get(username) || null;
    }
    const id = this._byUsername.get(username);
    if (!id) return null;
    return this._users.get(id) || null;
  }

  /**
   * Strip sensitive fields (password_hash, salt) from a user row.
   */
  _sanitize(row) {
    return {
      id: row.id,
      username: row.username,
      role: row.role,
      apiKey: row.api_key,
      createdAt: row.created_at,
      updatedAt: row.updated_at,
    };
  }
}

// ─── HTTP Middleware ───

/**
 * Returns an Express/http-compatible middleware function that extracts auth
 * credentials from the request and populates `req.user`.
 *
 * Auth is extracted from the Authorization header ONLY:
 *   - "Bearer <token>" or "ApiKey <key>"
 *
 * Query-parameter auth (?token=, ?apiKey=) is intentionally NOT supported
 * because tokens in URLs leak via server logs, Referer headers, and browser
 * history.
 *
 * If the path is in `publicPaths`, the request is allowed through even
 * without credentials (req.user will be null).
 *
 * @param {AuthManager} authManager
 * @returns {function(req, res, next)}
 */
function authMiddleware(authManager) {
  return function middleware(req, res, next) {
    // Allow public paths through without auth
    const urlPath = (req.url || '').split('?')[0];
    if (publicPaths.includes(urlPath)) {
      req.user = null;
      return next();
    }

    let user = null;

    // Check Authorization header only (no query-parameter fallback)
    const authHeader = req.headers && req.headers['authorization'];
    if (authHeader) {
      const trimmed = authHeader.trim();
      const spaceIdx = trimmed.indexOf(' ');
      if (spaceIdx > 0) {
        const scheme = trimmed.slice(0, spaceIdx);
        const credential = trimmed.slice(spaceIdx + 1).trim();

        const schemeLower = scheme.toLowerCase();
        if (schemeLower === 'bearer') {
          user = authManager.validateToken(credential);
        } else if (schemeLower === 'apikey') {
          user = authManager.validateApiKey(credential);
        }
      }
    }

    if (user) {
      req.user = user;
      return next();
    }

    // No valid auth found — 401
    res.statusCode = 401;
    const body = JSON.stringify({ error: 'Unauthorized', message: 'Valid authentication required. Use Authorization header with Bearer or ApiKey scheme.' });
    res.setHeader('Content-Type', 'application/json');
    res.end(body);
  };
}

/**
 * Minimal query string parser (no external deps).
 * Handles ?key=value&key2=value2
 */
function parseQuery(url) {
  const idx = url.indexOf('?');
  if (idx === -1) return {};
  const qs = url.slice(idx + 1);
  const params = Object.create(null); // prevent prototype pollution
  const FORBIDDEN_KEYS = new Set(['__proto__', 'constructor', 'prototype']);
  for (const pair of qs.split('&')) {
    const eqIdx = pair.indexOf('=');
    let key, value;
    if (eqIdx === -1) {
      key = decodeURIComponent(pair);
      value = '';
    } else {
      key = decodeURIComponent(pair.slice(0, eqIdx));
      value = decodeURIComponent(pair.slice(eqIdx + 1));
    }
    if (!FORBIDDEN_KEYS.has(key)) {
      params[key] = value;
    }
  }
  return params;
}

// ─── Exports ───

module.exports = {
  AuthManager,
  authMiddleware,
  ROLES,
  canWrite,
  canManageUsers,
  canRead,
  publicPaths,
};

