function collectJsFiles(root) {
  const out = [];
  const stack = [root];
  while (stack.length > 0) {
    const dir = stack.pop();
    let entries;
    try { entries = fs.readdirSync(dir, { withFileTypes: true }); }
    catch { continue; }
    for (const entry of entries) {
      if (entry.name.startsWith('.')) continue;
      const p = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        if (EXCLUDE_DIRS.has(entry.name)) continue;
        stack.push(p);
      } else if (entry.isFile()) {
        const ext = path.extname(entry.name).toLowerCase();
        if (ext === '.js' || ext === '.ts' || ext === '.mjs' || ext === '.cjs') {
          out.push(p);
        }
      }
    }
  }
  return out;
}

function h(tag, props, children) {
  const el = document.createElement(tag);
  if (props) {
    for (const [k, v] of Object.entries(props)) {
      if (v == null) continue;
      if (k === 'className') el.className = v;
      else if (k === 'style' && typeof v === 'object') Object.assign(el.style, v);
      else el.setAttribute(k, v);
    }
  }
  if (children) {
    for (const child of children) {
      if (child == null || child === false) continue;
      if (typeof child === 'string' || typeof child === 'number') {
        el.appendChild(document.createTextNode(String(child)));
      } else {
        el.appendChild(child);
      }
    }
  }
  return el;
}

function encodeSignature(props) {
  const c = props.charge > 0 ? '+' : props.charge < 0 ? '-' : '0';
  const v = Math.min(MAX_VALENCE, Math.max(0, Math.round(props.valence || 0)));
  const m = (props.mass || 'light')[0];
  const s = (props.spin || 'even')[0];
  const p = (props.phase || 'solid')[0];
  const r = (props.reactivity || 'inert')[0];
  const e = Math.min(9, Math.max(0, Math.round((props.electronegativity || 0) * 9)));
  const g = Math.min(MAX_GROUP, Math.max(1, Math.round(props.group || 1)));
  const d = Math.min(MAX_PERIOD, Math.max(1, Math.round(props.period || 1)));
  return `C${c}V${v}M${m}S${s}P${p}R${r}E${e}G${g}D${d}`;
}

function computeReactivity(code, tokens) {
  const externalCalls = countMatches(code, [
    /fetch\b/g, /axios\b/g, /\.request\b/g,
    /child_process/g, /exec\b/g, /spawn\b/g,
    /\.connect\b/g, /\.listen\b/g, /\.on\b.*=>/g,
  ]);
  const ioOps = countMatches(code, [
    /fs\.\w/g, /readFile|writeFile/g,
    /stdin|stdout|stderr/g, /process\.env/g,
  ]);
  const total = externalCalls + ioOps;
  if (total === 0) return 'inert';
  if (total <= 2) return 'low';
  if (total <= 5) return 'medium';
  return 'high';
}

function computeHarmPotential(code, tokens) {
  const dangerous = countMatches(code, [
    /eval\s*\(/g, /exec\s*\(/g, /child_process/g, /rm\s+-rf/g,
    /DROP\s+TABLE/gi, /DELETE\s+FROM/gi, /\.destroy\b/g,
    /process\.exit/g, /process\.kill/g,
  ]);
  const io = countMatches(code, [
    /fs\.write/g, /fs\.unlink/g, /\.send\b/g, /\.emit\b/g,
    /\.delete\b/g, /\.remove\b/g,
  ]);
  if (dangerous > 0) return 'dangerous';
  if (io > 3) return 'moderate';
  if (io > 0) return 'minimal';
  return 'none';
}

function signalToCharge(value) {
  if (typeof value !== 'number' || !isFinite(value)) return 0;
  if (value >= 0.8) return 1;   // strong → expanding
  if (value <= 0.4) return -1;  // weak → contracting
  return 0;                      // moderate → transforming
}

function computeHealingBudget(field) {
  const targets = field.findHealingTargets();
  if (targets.length === 0) return { budget: 0, reason: 'No zones need healing' };

  const urgency = 1 - field.globalCoherency; // 0 = perfect, 1 = terrible
  const scale = targets.length;

  // Budget: at least 1, at most 5, scaled by urgency × target count
  const budget = Math.max(1, Math.min(5, Math.ceil(urgency * scale)));

  return {
    budget,
    reason: `${targets.length} zones below threshold, urgency ${(urgency * 100).toFixed(0)}%, healing top ${budget}`,
  };
}

function resolveStringConcat(tokens, start) {
  const first = unquoteString(tokens[start]);
  if (first === null) return null;

  let result = first;
  let j = start + 1;

  while (j < tokens.length) {
    // Expect a '+' operator
    if (tokens[j].type !== 'operator' || tokens[j].value !== '+') break;
    // Expect another string literal
    const next = unquoteString(tokens[j + 1]);
    if (next === null) break;
    result += next;
    j += 2;
  }

  // Only report if we actually concatenated (consumed at least one '+')
  if (j === start + 1) return null;
  return { resolved: result, endIndex: j - 1 };
}

function normalizeWeights(w) {
  const c = Number(w.coherency);
  const y = Number(w.cyclomatic);
  const sum = (Number.isFinite(c) ? c : 0) + (Number.isFinite(y) ? y : 0);
  if (sum <= 0) return { ...DEFAULT_WEIGHTS };
  return { coherency: c / sum, cyclomatic: y / sum };
}

function runHealthCheck(manifest, record) {
  const started = Date.now();

  // HTTP health check
  if (manifest.api?.port && manifest.api?.healthPath) {
    const host = record?.host || manifest.api.host || 'localhost';
    const port = record?.port || manifest.api.port;
    const pathStr = manifest.api.healthPath;
    try {
      const http = require('http');
      return new Promise((resolve) => {
        const req = http.get({ host, port, path: pathStr, timeout: 2000 }, (res) => {
          const ok = res.statusCode && res.statusCode < 500;
          resolve({ alive: !!ok, latencyMs: Date.now() - started, statusCode: res.statusCode });
          res.resume();
        });
        req.on('error', (e) => resolve({ alive: false, latencyMs: Date.now() - started, error: e.code || e.message }));
        req.on('timeout', () => { req.destroy(); resolve({ alive: false, latencyMs: Date.now() - started, error: 'timeout' }); });
      });
    } catch (e) {
      return Promise.resolve({ alive: false, error: e.message });
    }
  }

  // CLI health check — shell out, cap at timeout
  const check = manifest.healthCheck;
  if (!check || !check.command) {
    return Promise.resolve({ alive: false, error: 'no health check declared' });
  }
  try {
    execFileSync('sh', ['-c', check.command], {
      cwd: manifest.repoRoot,
      stdio: 'ignore',
      timeout: check.timeoutMs || 5000,
    });
    return Promise.resolve({ alive: true, latencyMs: Date.now() - started });
  } catch (e) {
    return Promise.resolve({ alive: false, latencyMs: Date.now() - started, error: e.code || e.message });
  }
}

function auditLines(file) {
  try {
    const out = execFileSync('node', ['src/cli.js', 'audit', 'check', '--file', file, '--json'],
      { encoding: 'utf-8', timeout: 60000, stdio: ['ignore', 'pipe', 'ignore'] });
    const r = JSON.parse(out);
    const f = r.files?.[0];
    if (!f) return [];
    return (f.findings || []).map(x => x.line).sort((a, b) => a - b);
  } catch { return []; }
}

function loadAllPatterns() {
  const files = fs.readdirSync(SUBSTRATE_DIR).filter(f => SUBSTRATE_GLOB.test(f));
  const patterns = [];
  for (const f of files) {
    let data;
    try { data = JSON.parse(fs.readFileSync(path.join(SUBSTRATE_DIR, f), 'utf-8')); }
    catch (e) { console.warn(`Skipping ${f}: ${e.message}`); continue; }
    const type = data.meta?.pattern_type || f.replace(/^code_|_substrate\.json$/g, '');
    for (const p of data.patterns || []) {
      if (Array.isArray(p.waveform) && p.waveform.length === TARGET_LEN) {
        patterns.push({ name: p.name, type, waveform: p.waveform });
      }
    }
  }
  return patterns;
}

function buildRecommendations(topFactors, signals) {
  const recs = [];
  for (const f of topFactors) {
    switch (f.name) {
      case 'cyclomatic':
        recs.push(`Reduce cyclomatic complexity (${signals.cyclomatic}) by extracting helpers, flattening conditionals, or using early returns. McCabe recommends ≤ 10.`);
        break;
      case 'coherency':
        recs.push(`Total coherency is ${signals.totalCoherency}. Run \`oracle audit check --file <path>\` and address the top findings.`);
        break;
      case 'maxDepth':
        recs.push(`Nesting depth ${signals.maxDepth} exceeds ${MAX_DEPTH_CAP}. Extract inner blocks into named functions to flatten the control flow.`);
        break;
      case 'completeness':
        recs.push(`Add error handling and input validation — the analyzer detected missing edge-case coverage.`);
        break;
      case 'fractalAlignment':
        recs.push(`Refactor towards a canonical pattern. Run \`oracle search\` for similar proven patterns and consider \`oracle resolve\`.`);
        break;
      default:
        // Unknown factor name — no specific recommendation, skip.
        break;
    }
  }
  if (recs.length === 0) {
    recs.push('No high-severity factors detected. Routine maintenance only.');
  }
  return recs;
}

function makeRng(seed) {
  let state = seed >>> 0;
  if (state === 0) state = 1;
  return function () {
    state = (state + 0x6D2B79F5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function loadArchitectureManifest(manifestPath) {
  if (!fs.existsSync(manifestPath)) return null;
  try {
    const raw = fs.readFileSync(manifestPath, 'utf-8');
    const parsed = JSON.parse(raw);
    if (!parsed || !Array.isArray(parsed.tiers)) return null;
    return parsed;
  } catch {
    return null;
  }
}

function buildDescription(props) {
  const chargeName = props.charge > 0 ? 'expanding' : props.charge < 0 ? 'contracting' : 'transforming';
  const groupName = GROUPS[props.group] || 'general';
  const massName = props.mass;
  const spinName = props.spin === 'even' ? 'pure/reversible' : 'side-effecting';
  const phaseName = props.phase === 'solid' ? 'cached' : props.phase === 'liquid' ? 'mutable' : 'computed';
  return `A ${massName}-weight ${chargeName} ${groupName} function that is ${spinName}, ${phaseName}, with valence ${props.valence} and ${props.reactivity} reactivity`;
}

function computeAlignment(code, tokens) {
  const healing = countMatches(code, [
    /optimize\b/gi, /heal\b/gi, /repair\b/gi, /fix\b/gi,
    /improve\b/gi, /refine\b/gi, /clean\b/gi, /validate\b/gi,
    /coherenc/gi, /align\b/gi,
  ]);
  const degrading = countMatches(code, [
    /corrupt\b/gi, /break\b/gi, /destroy\b/gi, /pollut/gi,
    /leak\b/gi, /overflow\b/gi, /inject\b/gi,
  ]);
  if (healing > degrading + 2) return 'healing';
  if (degrading > healing + 1) return 'degrading';
  return 'neutral';
}

