function isSetupName(name) {
  if (!name || typeof name !== 'string') return false;
  // Strip leading underscores so `_startAutoFlush` is recognized as a
  // start-style setup function. Also strip the common anonymous-fn
  // convention of `bound #name`.
  const lower = name.replace(/^_+/, '').toLowerCase();
  return SETUP_NAME_PREFIXES.some(p => lower === p || lower.startsWith(p));
}

function averageProperties(p1, p2) {
  const mOrder = { light: 0, medium: 1, heavy: 2 };
  const mReverse = ['light', 'medium', 'heavy'];
  const rOrder = { inert: 0, low: 1, medium: 2, high: 3 };
  const rReverse = ['inert', 'low', 'medium', 'high'];

  return {
    charge: Math.round((p1.charge + p2.charge) / 2),
    valence: Math.round((p1.valence + p2.valence) / 2),
    mass: mReverse[Math.round(((mOrder[p1.mass] || 0) + (mOrder[p2.mass] || 0)) / 2)],
    spin: p1.spin === p2.spin ? p1.spin : 'even',
    phase: p1.phase === p2.phase ? p1.phase : 'liquid',
    reactivity: rReverse[Math.round(((rOrder[p1.reactivity] || 0) + (rOrder[p2.reactivity] || 0)) / 2)],
    electronegativity: Math.round(((p1.electronegativity || 0) + (p2.electronegativity || 0)) / 2 * 100) / 100,
    group: Math.round((p1.group + p2.group) / 2),
    period: Math.round((p1.period + p2.period) / 2),
  };
}

function computeIntention(code, tokens) {
  // Code intention is structural — benevolent code helps, malevolent code harms
  const benevolent = countMatches(code, [
    /help\b/gi, /assist\b/gi, /enable\b/gi, /protect\b/gi,
    /guard\b/gi, /safe\b/gi, /sanitize\b/gi, /verify\b/gi,
  ]);
  const malevolent = countMatches(code, [
    /exploit\b/gi, /attack\b/gi, /inject\b/gi, /bypass\b/gi,
    /escalat\b/gi, /brute\s*force/gi, /payload\b/gi,
  ]);
  if (benevolent > malevolent + 1) return 'benevolent';
  if (malevolent > benevolent) return 'malevolent';
  return 'neutral';
}

function analyzeCodebaseCharge() {
  const functions = [];

  try {
    const { introspect } = require('../atomic/self-introspect');
    const { PeriodicTable } = require('../atomic/periodic-table');
    const table = new PeriodicTable();
    const result = introspect(table, { includeVoid: true });

    for (const el of result.registered) {
      const element = table.getElement(el.signature);
      if (element && element.properties) {
        functions.push({
          name: el.name,
          charge: element.properties.charge || 0,
          alignment: element.properties.alignment || 'neutral',
          harmPotential: element.properties.harmPotential || 'none',
        });
      }
    }
  } catch { /* introspection unavailable */ }

  const netCharge = functions.reduce((s, f) => s + f.charge, 0);
  const balance = Math.abs(netCharge) <= 2 ? 'balanced' : netCharge > 0 ? 'expanding' : 'contracting';

  return { functions, netCharge, balance };
}

function synthesizeTestStubs(code, filePath) {
  const functions = extractExportedFunctions(code);
  if (functions.length === 0) return null;

  const path = require('path');
