function nearestNeighborScore(code, patterns) {
  const wave = codeToWaveform(code);
  if (!wave) return { score: 0, match: null };
  let best = { score: -Infinity, match: null };
  for (const p of patterns) {
    const c = pearson(wave, p.waveform);
    if (c > best.score) best = { score: c, match: p };
  }
  return best;
}

function extractFactors(ctx) {
  const matched = [];
  for (const entry of FACTOR_TABLE) {
    const hit = entry.detect(ctx);
    if (!hit) continue;
    matched.push({
      name: entry.name,
      severity: round4(hit.severity),
      message: hit.message,
      recommendation: entry.recommend(ctx),
    });
  }
  return matched.slice().sort((a, b) => b.severity - a.severity);
}

function extractCalledIdentifiers(tokens) {
  const calls = [];
  for (let i = 0; i < tokens.length; i++) {
    const t = tokens[i];
    if (t.type !== 'identifier') continue;
    if (tokens[i + 1]?.value !== '(') continue;
    // Skip member-access calls like `obj.foo(`
    if (tokens[i - 1]?.value === '.') continue;
    // Skip `new Foo(` — the constructor name might not be in scope
    // by simple lexical check, but if it's a fabrication we want to
    // catch it. Keep it.
    calls.push({ name: t.value, line: t.line, column: t.column });
  }
  return calls;
}

function readLines(file) {
  if (!fs.existsSync(file)) return [];
  const out = [];
  const content = fs.readFileSync(file, 'utf-8');
  for (const line of content.split('\n')) {
    if (!line.trim()) continue;
    try { out.push(JSON.parse(line)); }
    catch { /* skip malformed */ }
  }
  return out;
}

