/**
 * Client Database — id generation, password hashing, and row mappers.
 */

import { createHmac, randomBytes } from "crypto";
import type { ClientRecord, ClientFilters, LeadPurchase } from "./types";

export function generateClientId(): string {
  const ts = Date.now().toString(36);
  const rand = Math.random().toString(36).slice(2, 8);
  return `client_${ts}_${rand}`;
}

export function generatePurchaseId(): string {
  const ts = Date.now().toString(36);
  const rand = Math.random().toString(36).slice(2, 8);
  return `purchase_${ts}_${rand}`;
}

export function hashPassword(password: string): string {
  const salt = randomBytes(16).toString("hex");
  const hash = createHmac("sha256", salt).update(password).digest("hex");
  return `${salt}:${hash}`;
}

export function verifyPassword(password: string, stored: string): boolean {
  const [salt, hash] = stored.split(":");
  if (!salt || !hash) return false;
  const computed = createHmac("sha256", salt).update(password).digest("hex");
  if (computed.length !== hash.length) return false;
  let mismatch = 0;
  for (let i = 0; i < computed.length; i++) {
    mismatch |= computed.charCodeAt(i) ^ hash.charCodeAt(i);
  }
  return mismatch === 0;
}

export function rowToClient(row: Record<string, unknown>): ClientRecord {
  return {
    clientId: row.client_id as string,
    companyName: row.company_name as string,
    contactName: row.contact_name as string,
    email: row.email as string,
    phone: row.phone as string,
    passwordHash: row.password_hash as string,
    status: row.status as ClientRecord["status"],
    pricingTier: row.pricing_tier as string,
    pricePerLead: Number(row.price_per_lead),
    exclusivePrice: Number(row.exclusive_price),
    stateLicenses: row.state_licenses as string,
    coverageTypes: row.coverage_types as string,
    dailyCap: Number(row.daily_cap),
    monthlyCap: Number(row.monthly_cap),
    minScore: Number(row.min_score),
    balance: Number(row.balance),
    createdAt: row.created_at as string,
    updatedAt: row.updated_at as string,
  };
}

export function rowToFilters(row: Record<string, unknown>): ClientFilters {
  return {
    clientId: row.client_id as string,
    states: row.states as string,
    coverageTypes: row.coverage_types as string,
    veteranOnly: row.veteran_only === 1 || row.veteran_only === true,
    minScore: Number(row.min_score),
    maxLeadAge: Number(row.max_lead_age),
    distributionMode: row.distribution_mode as ClientFilters["distributionMode"],
  };
}

export function rowToPurchase(row: Record<string, unknown>): LeadPurchase {
  return {
    purchaseId: row.purchase_id as string,
    leadId: row.lead_id as string,
    clientId: row.client_id as string,
    pricePaid: Number(row.price_paid),
    purchasedAt: row.purchased_at as string,
    status: row.status as LeadPurchase["status"],
    exclusive: row.exclusive === 1 || row.exclusive === true,
    returnReason: (row.return_reason as string) || "",
    returnDeadline: (row.return_deadline as string) || "",
  };
}

/**
 * Creates a new object with the specified keys omitted from the source object.
 * @param {Object} obj - The source object.
 * @param {string[]} keys - The keys to omit.
 * @returns {Object} A new object without the omitted keys.
 */
function omit(obj, keys) {
  const keysToOmit = new Set(keys);
  const result = {};
  const allKeys = Object.keys(obj);
  for (let i = 0; i < allKeys.length; i++) {
    const key = allKeys[i];
    if (!keysToOmit.has(key)) {
      result[key] = obj[key];
    }
  }
  return result;
}

module.exports = omit;

/**
 * Creates a new object with only the specified keys from the source object.
 * @param {Object} obj - The source object.
 * @param {string[]} keys - The keys to pick.
 * @returns {Object} A new object containing only the picked keys.
 */
function pick(obj, keys) {
  const result = {};
  for (let i = 0; i < keys.length; i++) {
    const key = keys[i];
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      result[key] = obj[key];
    }
  }
  return result;
}

module.exports = pick;

/**
 * useUtmTracking — Capture and persist UTM parameters across the session.
 *
 * Captures utm_source, utm_medium, utm_campaign, utm_term, utm_content
 * from the URL on first load, persists them in sessionStorage so they
 * survive navigation within the site. Exposes them for form submission.
 *
 * Also captures referrer and landing page for attribution.
 */
import { useEffect, useState } from "react";

export interface UtmParams {
  utmSource: string | null;
  utmMedium: string | null;
  utmCampaign: string | null;
  utmTerm: string | null;
  utmContent: string | null;
  referrer: string | null;
  landingPage: string | null;
}

const STORAGE_KEY = "dc_utm";

const UTM_KEYS = [
  ["utm_source", "utmSource"],
  ["utm_medium", "utmMedium"],
  ["utm_campaign", "utmCampaign"],
  ["utm_term", "utmTerm"],
  ["utm_content", "utmContent"],
] as const;

function captureFromUrl(): UtmParams {
  const params = new URLSearchParams(window.location.search);
  const utm: UtmParams = {
    utmSource: null,
    utmMedium: null,
    utmCampaign: null,
    utmTerm: null,
    utmContent: null,
    referrer: document.referrer || null,
    landingPage: window.location.href,
  };

  for (const [urlKey, stateKey] of UTM_KEYS) {
    const value = params.get(urlKey);
    if (value) {
      utm[stateKey] = value;
    }
  }

  return utm;
}

function loadFromStorage(): UtmParams | null {
  try {
    const stored = sessionStorage.getItem(STORAGE_KEY);
    return stored ? JSON.parse(stored) : null;
  } catch {
    return null;
  }
}

function saveToStorage(utm: UtmParams): void {
  try {
    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(utm));
  } catch {
    // Storage unavailable — silent fail
  }
}

export function useUtmTracking(): UtmParams {
  const [utm, setUtm] = useState<UtmParams>({
    utmSource: null,
    utmMedium: null,
    utmCampaign: null,
    utmTerm: null,
    utmContent: null,
    referrer: null,
    landingPage: null,
  });

  useEffect(() => {
    // Priority: URL params (fresh click) > sessionStorage (persisted)
    const fromUrl = captureFromUrl();
    const hasUrlUtm = UTM_KEYS.some(([_, key]) => fromUrl[key] !== null);

    if (hasUrlUtm) {
      // Fresh click with UTM params — save and use
      saveToStorage(fromUrl);
      setUtm(fromUrl);
    } else {
      // No UTM in URL — check session storage
      const stored = loadFromStorage();
      if (stored) {
        setUtm(stored);
      } else {
        // First visit with no UTM — save referrer/landing page
        saveToStorage(fromUrl);
        setUtm(fromUrl);
      }
    }
  }, []);

  return utm;
}

/**
 * CSRF Protection
 *
 * Double-submit cookie pattern:
 *  1. Server sets a random token in an httpOnly, sameSite=strict cookie
 *  2. API endpoint /api/csrf returns the token for the client to read
 *  3. Client sends the token as X-CSRF-Token header on mutating requests
 *  4. Server validates header matches cookie value
 *
 * This works with Next.js App Router + React client components.
 */

import { NextRequest, NextResponse } from "next/server";
import { randomBytes } from "crypto";

const CSRF_COOKIE_NAME = "__csrf";
const CSRF_HEADER_NAME = "x-csrf-token";
const TOKEN_LENGTH = 32; // 256 bits of entropy

/** Generate a cryptographically secure CSRF token */
export function generateCsrfToken(): string {
  return randomBytes(TOKEN_LENGTH).toString("hex");
}

/** Read the CSRF token from the request cookie */
export function getCsrfTokenFromCookie(req: NextRequest): string | null {
  return req.cookies.get(CSRF_COOKIE_NAME)?.value ?? null;
}

/** Read the CSRF token from the request header */
export function getCsrfTokenFromHeader(req: NextRequest): string | null {
  return req.headers.get(CSRF_HEADER_NAME);
}

/**
 * Validate that the CSRF header matches the cookie.
 * Returns true if valid, false if mismatch or missing.
 */
export function validateCsrfToken(req: NextRequest): boolean {
  const cookieToken = getCsrfTokenFromCookie(req);
  const headerToken = getCsrfTokenFromHeader(req);

  if (!cookieToken || !headerToken) return false;
  if (cookieToken.length !== headerToken.length) return false;

  // Constant-time comparison to prevent timing attacks
  let mismatch = 0;
  for (let i = 0; i < cookieToken.length; i++) {
    mismatch |= cookieToken.charCodeAt(i) ^ headerToken.charCodeAt(i);
  }
  return mismatch === 0;
}

/**
 * Set the CSRF cookie on a response.
 * Call this from the /api/csrf endpoint or middleware.
 */
export function setCsrfCookie(response: NextResponse, token: string): void {
  response.cookies.set(CSRF_COOKIE_NAME, token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    sameSite: "strict",
    path: "/",
    maxAge: 60 * 60, // 1 hour
  });
}

/**
 * Living Remembrance Engine — TS facade over the canonical field.
 *
 * Math: p(t) = |⟨Ψ_healed | Ψ(t)⟩|² (squared cosine), with retro-causal pull
 * r_eff(t) = r₀·(1 + α·(1 − p(t))^4), δ_void free-coherence donation, and
 * cascade γ. Coherence is hard-capped at 0.999 to satisfy Void contract C-56.
 *
 * This engine is independent of the JS LivingRemembranceEngine that the
 * field-coupling helper drives. Callers wanting unified-field participation
 * should also contribute() each ritual step — see the rituals in this folder.
 */

const { codeToWaveform } = require('../src/core/code-to-waveform') as {
  codeToWaveform: (text: string) => Float64Array;
};

export interface RemembranceState {
  coherence: number;        // p(t) — the living overlap, squared
  globalEntropy: number;
  cascadeFactor: number;
  timestamp: number;
}

export interface UpdateResult {
  coherence: number;
  p: number;
  r_eff: number;
  delta_void: number;
  gamma_cascade: number;
  globalEntropy: number;
  cascadeFactor: number;
  recommendation: 'promote' | 'refine';
  timestamp: number;
}

const COHERENCE_CAP = 0.999;       // Void contract C-56
const CASCADE_CAP = 5.0;           // Void contract C-55

export class LivingRemembranceEngine {
  private r0 = 0.05;
  private alpha = 15.0;
  private delta0 = 0.03;
  private beta = 8.0;
  private epsilon = 1e-8;

  private healedVector: number[] | null = null;
  private state: RemembranceState;

  constructor() {
    this.state = {
      coherence: 0.65,
      globalEntropy: 0.45,
      cascadeFactor: 1.0,
      timestamp: Date.now(),
    };
  }

  async loadHealedAnchor(anchorVector: number[] | Float32Array | Float64Array) {
    this.healedVector = Array.from(anchorVector);
  }

  getState(): RemembranceState {
    return { ...this.state };
  }

  private computeCoherence(currentVector: number[]): number {
    if (!this.healedVector) return 0.65;
    const len = Math.min(currentVector.length, this.healedVector.length);
    let dot = 0, na = 0, nb = 0;
    for (let i = 0; i < len; i++) {
      const a = currentVector[i];
      const b = this.healedVector[i];
      dot += a * b;
      na += a * a;
      nb += b * b;
    }
    const overlap = dot / (Math.sqrt(na) * Math.sqrt(nb) + this.epsilon);
    return overlap * overlap;
  }

  update(currentVector: number[], cost: number = 1.0): UpdateResult {
    const p = this.computeCoherence(currentVector);
    const r_eff = this.r0 * (1 + this.alpha * Math.pow(1 - p, 4));
    const delta_void = this.delta0 * (1 - p);
    const gamma = Math.exp(this.beta * this.state.cascadeFactor);

    const newCoherence = Math.min(COHERENCE_CAP, p + r_eff * 0.1 + delta_void * 0.15);
    this.state.coherence = newCoherence;
    this.state.globalEntropy = cost / (newCoherence + 1e-6);
    this.state.cascadeFactor = Math.min(CASCADE_CAP, this.state.cascadeFactor + 0.05 * newCoherence);
    this.state.timestamp = Date.now();

    return {
      coherence: newCoherence,
      p,
      r_eff,
      delta_void,
      gamma_cascade: gamma,
      globalEntropy: this.state.globalEntropy,
      cascadeFactor: this.state.cascadeFactor,
      recommendation: newCoherence > 0.92 ? 'promote' : 'refine',
      timestamp: this.state.timestamp,
    };
  }

  async applyToTask(taskDescription: string, currentOutput: unknown): Promise<UpdateResult> {
    const text = `${taskDescription} ${JSON.stringify(currentOutput)}`;
    const vector = Array.from(codeToWaveform(text));
    return this.update(vector);
  }
}

/**
 * Date of Birth validation — minimum age enforcement.
 * Validates DOB string (YYYY-MM-DD) and ensures the person is at least 18 years old.
 */
export function validateDob(dob: string): boolean {
  if (typeof dob !== "string") return false;
  const match = dob.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return false;

  const year = parseInt(match[1], 10);
  const month = parseInt(match[2], 10);
  const day = parseInt(match[3], 10);

  // Basic range checks
  if (month < 1 || month > 12) return false;
  if (day < 1 || day > 31) return false;
  if (year < 1900 || year > new Date().getFullYear()) return false;

  // Validate the date is real (e.g. no Feb 30)
  const date = new Date(year, month - 1, day);
  if (
    date.getFullYear() !== year ||
    date.getMonth() !== month - 1 ||
    date.getDate() !== day
  ) {
    return false;
  }

  return isAtLeast18(date);
}

export function isAtLeast18(birthDate: Date): boolean {
  const today = new Date();
  const eighteenYearsAgo = new Date(
    today.getFullYear() - 18,
    today.getMonth(),
    today.getDate(),
  );
  return birthDate <= eighteenYearsAgo;
}

