function verifySymbol(symbol, context) {
  if (!symbol || typeof symbol !== 'string') {
    return { symbol: String(symbol), status: 'missing', source: null, evidence: 'invalid input' };
  }

  // Tier 1: built-in allowlist
  if (BUILTINS.has(symbol)) {
    return { symbol, status: 'builtin', source: 'js/node allowlist', evidence: null };
  }

  // Tier 2: session-touched identifiers
  if (context.knownIdentifiers && context.knownIdentifiers.has(symbol)) {
    return { symbol, status: 'seen', source: 'session ledger', evidence: 'previously read this session' };
  }

  // Tier 3: oracle pattern library
  if (context.oracle && typeof context.oracle.search === 'function') {
    try {
      const hits = context.oracle.search(symbol, { limit: 3 });
      if (Array.isArray(hits) && hits.length > 0) {
        // Require a strong match — the top hit's name must equal the
        // symbol (case-sensitive) OR contain it as a prefix. Weaker
        // text-similarity matches would let fabrications slip through.
        const top = hits[0];
        const name = top.name || top.description || '';
        if (name === symbol || name.startsWith(symbol) || (top.tags || []).includes(symbol)) {
          return {
            symbol,
            status: 'pattern',
            source: 'oracle pattern library',
            evidence: { patternName: name, coherency: top.coherency, id: top.id },
          };
        }
      }
    } catch { /* degrade gracefully */ }
  }

  // Tier 4: filesystem scan — look for a definition in the repo's src tree
  if (context.repoRoot) {
    const dirs = context.srcDirs || ['src'];
    for (const dir of dirs) {
      const abs = path.join(context.repoRoot, dir);
      if (!fs.existsSync(abs)) continue;
      const hit = scanForDefinition(abs, symbol, 200);
      if (hit) {
        return {
          symbol,
          status: 'found',
          source: 'repo scan',
          evidence: { file: path.relative(context.repoRoot, hit.file), line: hit.line },
        };
      }
    }
  }

  return { symbol, status: 'missing', source: null, evidence: 'no ground truth found' };
}

/**
 * Session cookie helpers — the canonical shape every logout route uses.
 *
 * The three session families (admin, portal, client) each have their own
 * cookie name and sameSite policy (admin + portal are "strict", client is
 * "lax" because the client portal accepts cross-site flows). The clearing
 * mechanics are otherwise identical, so they live here.
 */
import { NextResponse } from "next/server";

export type SessionSameSite = "strict" | "lax";

/**
 * Build a JSON response that clears a session cookie. Use from any logout
 * route: `return clearSessionResponse(COOKIE_NAME, "strict")`.
 */
export function clearSessionResponse(
  cookieName: string,
  sameSite: SessionSameSite,
): NextResponse {
  const response = NextResponse.json({ success: true });
  response.cookies.set(cookieName, "", {
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    sameSite,
    path: "/",
    maxAge: 0,
  });
  return response;
}

/**
 * Clear several session cookies in one response. The portal and client cookie
 * families are minted together (register + login set BOTH), so logout must
 * clear BOTH — otherwise signing out from the dashboard leaves the client
 * session (which authorizes the purchasing /api/client/* surface) alive, and
 * vice-versa from the marketplace. Clearing a cookie the browser doesn't hold
 * is a harmless no-op, so every logout route can safely clear the full set.
 */
export function clearSessionsResponse(
  specs: Array<{ name: string; sameSite: SessionSameSite }>,
): NextResponse {
  const response = NextResponse.json({ success: true });
  for (const { name, sameSite } of specs) {
    response.cookies.set(name, "", {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite,
      path: "/",
      maxAge: 0,
    });
  }
  return response;
}

/**
 * Cookie options for a session that lasts until the browser is fully closed,
 * then requires a fresh login. We deliberately omit `maxAge`/`expires` so the
 * browser treats it as a session cookie. The signed token's own `exp` still
 * bounds the absolute server-side lifetime (verified on every request), so a
 * never-closed browser can't hold a session open forever.
 */
export function sessionCookieOptions(sameSite: SessionSameSite) {
  return {
    httpOnly: true,
    secure: process.env.NODE_ENV === "production",
    sameSite,
    path: "/",
  };
}

export async function PATCH(req: NextRequest) {
  const cookie = req.cookies.get(PORTAL_SESSION_COOKIE)?.value;
  if (!cookie) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const session = verifyPortalSessionToken(cookie);
  if (!session) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

  const body = await req.json();
  const { messageId } = body;

  if (!messageId) {
    return NextResponse.json({ error: "messageId is required." }, { status: 400 });
  }

  const result = await markMessageRead(messageId, session.id);
  if (!result.ok) {
    return NextResponse.json({ error: result.error }, { status: 500 });
  }

  return NextResponse.json({ success: true });
}

