const { describe, it } = require('node:test');
const assert = require('node:assert/strict');

// ─── @oracle-pattern-definitions marker ───

describe('@oracle-pattern-definitions marker', () => {
  const { covenantCheck, deepSecurityScan } = require('../src/core/covenant');
  const { scoreSecurity } = require('../src/core/reflection-scorers');

  const patternDefCode = `
    /* @oracle-pattern-definitions */
    const PATTERNS = [
      { pattern: /eval\\s*\\(/, reason: 'eval detected' },
      { pattern: /innerHTML\\s*=/, reason: 'XSS risk' },
    ];
    module.exports = { PATTERNS };
  `;

  it('skips harm pattern matching for files with the marker', () => {
    const result = covenantCheck(patternDefCode);
    assert.equal(result.sealed, true, 'pattern definition files should always seal');
  });

  it('returns 0.95 security score for pattern definition files', () => {
    const score = scoreSecurity(patternDefCode, { language: 'javascript', trusted: true });
    assert.equal(score, 0.95);
  });

  it('skips deep security scan for pattern definition files', () => {
    const result = deepSecurityScan(patternDefCode, { language: 'javascript', trusted: true });
    assert.equal(result.deepFindings.length, 0, 'no deep findings for pattern defs');
  });

  it('still catches violations in files WITHOUT the marker', () => {
    const badCode = 'const x = eval("dangerous");';
    const result = scoreSecurity(badCode, { language: 'javascript' });
    assert.ok(result < 0.95, 'should penalize eval in normal files');
  });
});

// ─── @oracle-infrastructure marker ───

describe('@oracle-infrastructure marker', () => {
  const { covenantCheck } = require('../src/core/covenant');
  const { scoreSecurity } = require('../src/core/reflection-scorers');

  it('skips covenant harm matching for infrastructure files', () => {
    const infraCode = `
      /* @oracle-infrastructure */
      function render(data) {
        element.innerHTML = data;
      }
    `;
    const result = covenantCheck(infraCode, { trusted: true });
    assert.equal(result.sealed, true, 'infrastructure files should pass covenant');
  });

  it('passes covenant and scores high security for infra files', () => {
    const infraCode = `
      /* @oracle-infrastructure */
      function render(data) {
        element.innerHTML = data;
      }
    `;
    const score = scoreSecurity(infraCode, { language: 'javascript', trusted: true });
    assert.ok(score >= 0.9, `infrastructure files should pass security, got ${score}`);
  });

  it('still gives hard zero for non-infra files with violations', () => {
    const badCode = `
      function render(data) {
        element.innerHTML = data;
      }
    `;
    const score = scoreSecurity(badCode, { language: 'javascript' });
    assert.equal(score, 0, 'non-infra files with violations should score 0');
  });
});

// ─── @oracle-dense-code and simplicity floor ───

describe('Simplicity scoring improvements', () => {
  const { scoreSimplicity } = require('../src/core/reflection-scorers');

  it('applies reduced penalties for @oracle-dense-code files', () => {
    const denseCode = '/* @oracle-dense-code */\n' + 'function f() {\n' +
      '  if (a) {\n    if (b) {\n      if (c) {\n        if (d) {\n          if (e) {\n            if (f) {\n              x();\n            }\n          }\n        }\n      }\n    }\n  }\n}\n';
    const normalCode = denseCode.replace('/* @oracle-dense-code */\n', '');

    const denseScore = scoreSimplicity(denseCode);
    const normalScore = scoreSimplicity(normalCode);
    assert.ok(denseScore > normalScore, 'dense-code marker should reduce penalties');
  });

  it('enforces a floor of 0.15 for simplicity', () => {
    // Create extremely deeply nested code
    let code = 'function x() {\n';
    for (let i = 0; i < 30; i++) code += '  '.repeat(i + 1) + 'if (a) {\n';
    for (let i = 29; i >= 0; i--) code += '  '.repeat(i + 1) + '}\n';
    code += '}\n';
    // Add many long lines
    for (let i = 0; i < 50; i++) code += 'a'.repeat(200) + '\n';

    const score = scoreSimplicity(code);
    assert.ok(score >= 0.15, `simplicity floor should be 0.15, got ${score}`);
  });
});

// ─── fullCoherency gap fix ───

describe('fullCoherency gap fix', () => {
  const { reflectionLoop } = require('../src/core/reflection-loop');

  it('fullCoherency should not be artificially capped during reflection', () => {
    const code = 'function add(a, b) { return a + b; }';
    const result = reflectionLoop(code, { language: 'javascript', maxLoops: 0 });
    // Before fix: fullCoherency was ~0.80 max due to unknown testProof/history
    // After fix: should be >= 0.90 for clean code
    assert.ok(result.fullCoherency >= 0.9,
      `fullCoherency should be >= 0.9 for clean code, got ${result.fullCoherency}`);
  });
});

// ─── crossFileAnalysis ───

describe('crossFileAnalysis', () => {
  const { crossFileAnalysis } = require('../src/reflector/scoring-analysis-aggregate');
  const { writeFileSync, mkdirSync, rmSync } = require('fs');
  const { join } = require('path');
  const tmpDir = join(__dirname, '.tmp-cross-file');

  // Setup temp files
  function setup() {
    try { rmSync(tmpDir, { recursive: true }); } catch {}
    mkdirSync(tmpDir, { recursive: true });

    // File A: has function 'helper' with body X
    writeFileSync(join(tmpDir, 'a.js'), `
      function helper(x) { return x * 2; }
      function unique_a() { return 1; }
    `);

    // File B: has function 'helper' with similar body
    writeFileSync(join(tmpDir, 'b.js'), `
      function helper(x) { return x * 2; }
      function unique_b() { return 2; }
    `);

    // File C: has function 'helper' with DIFFERENT body
    writeFileSync(join(tmpDir, 'c.js'), `
      function helper(list) {
        const result = [];
        for (const item of list) result.push(item.name);
        return result;
      }
    `);
  }

  function cleanup() {
    try { rmSync(tmpDir, { recursive: true }); } catch {}
  }

  it('detects duplicate functions with similar bodies', () => {
    setup();
    try {
      const result = crossFileAnalysis(tmpDir, [
        { path: 'a.js' }, { path: 'b.js' }, { path: 'c.js' },
      ]);
      const helperDups = result.findings.filter(f =>
        f.type === 'duplicate-function' && f.message.includes('helper')
      );
      // Should find helper duplicated in a.js and b.js (similar bodies)
      // But NOT group c.js's helper (different body)
      assert.ok(helperDups.length >= 1, 'should detect helper duplication');
      assert.ok(result.totalFindings >= 1);
    } finally {
      cleanup();
    }
  });

  it('uses Object.create(null) to avoid prototype key collisions', () => {
    setup();
    // Add a file with a function named 'constructor'
    writeFileSync(join(tmpDir, 'd.js'), `
      function constructor() { return {}; }
    `);
    try {
      // Should not throw
      const result = crossFileAnalysis(tmpDir, [
        { path: 'a.js' }, { path: 'd.js' },
      ]);
      assert.ok(typeof result.totalFindings === 'number');
    } finally {
      cleanup();
    }
  });
});

// ─── Architectural search injection ───

describe('Architectural search improvements', () => {
  const { parseIntent, injectArchitecturalResults, ARCHITECTURAL_PATTERNS } = require('../src/core/search-intelligence');

  it('detects architecture intent in structural queries', () => {
    const intent = parseIntent('split large module into sub-modules');
    const archIntents = intent.intents.filter(i => i.name === 'architecture');
    assert.ok(archIntents.length > 0, 'should detect architecture intent');
    assert.ok(archIntents[0].structural, 'architecture intent should be structural');
  });

  it('detects design pattern intent', () => {
    const intent = parseIntent('factory pattern for creating objects');
    const designIntents = intent.intents.filter(i => i.name === 'designPattern');
    assert.ok(designIntents.length > 0, 'should detect designPattern intent');
  });

  it('injects architectural patterns for structural queries', () => {
    const intent = parseIntent('refactor module into smaller pieces');
    const results = injectArchitecturalResults([], intent, 10);
    assert.ok(results.length > 0, 'should inject architectural patterns');
    assert.ok(results[0].source === 'builtin-architecture');
  });

  it('does not inject for non-structural queries', () => {
    const intent = parseIntent('debounce function');
    const results = injectArchitecturalResults([], intent, 10);
    assert.equal(results.length, 0, 'should not inject for non-structural queries');
  });

  it('has 5 built-in architectural patterns', () => {
    assert.equal(ARCHITECTURAL_PATTERNS.length, 5);
    const names = ARCHITECTURAL_PATTERNS.map(p => p.name);
    assert.ok(names.includes('Barrel Re-Export'));
    assert.ok(names.includes('Facade Pattern'));
    assert.ok(names.includes('Strategy Pattern'));
  });
});

patterns.code:
/**
 * Valor Coherency Primitives — the math layer.
 *
 * Port of the oracle's coherency + resonance primitives into the cathedral.
 * Pure functions, no I/O, no framework. Same math used by src/unified/coherency.js,
 * src/atomic/temporal-projection.js, and Void-Data-Compressor/resonance_detector.py.
 *
 * The law under all of these: coherency is the geometric mean of independent
 * signals in [0, 1]. Weakest signal dominates — can't fake quality by maxing
 * one dimension. This is the Remembrance Weakest Link property.
 */

export const EPSILON = 1e-9;

/**
 * Geometric mean across [0, 1] signals.
 *
 * Returns a score in [0, 1] where a single zero zeros the whole score.
 * This is the weakest-link property: no dimension can be faked by maxing others.
 * The same operation is used in oracle/unified/coherency.js SERF layer.
 */
export function geometricMean(values: readonly number[]): number {
  if (values.length === 0) return 0;
  let logSum = 0;
  for (const v of values) {
    const clamped = clamp01(v);
    if (clamped <= EPSILON) return 0;
    logSum += Math.log(clamped);
  }
  return Math.exp(logSum / values.length);
}

/** Clamp a value into [0, 1]. */
export function clamp01(v: number): number {
  if (!Number.isFinite(v)) return 0;
  if (v <= 0) return 0;
  if (v >= 1) return 1;
  return v;
}

/**
 * Pearson correlation of two equal-length waveforms.
 * Returns r in [-1, 1]. Falls back to 0 on zero variance / mismatched length.
 */
export function pearson(a: readonly number[], b: readonly number[]): number {
  if (a.length !== b.length || a.length === 0) return 0;
  const n = a.length;
  let sa = 0;
  let sb = 0;
  for (let i = 0; i < n; i++) {
    sa += a[i];
    sb += b[i];
  }
  const ma = sa / n;
  const mb = sb / n;
  let num = 0;
  let da = 0;
  let db = 0;
  for (let i = 0; i < n; i++) {
    const x = a[i] - ma;
    const y = b[i] - mb;
    num += x * y;
    da += x * x;
    db += y * y;
  }
  const denom = Math.sqrt(da * db);
  if (denom <= EPSILON) return 0;
  const r = num / denom;
  if (!Number.isFinite(r)) return 0;
  return Math.max(-1, Math.min(1, r));
}

/**
 * Resample a waveform to targetLen via linear interpolation.
 * Waveforms become comparable regardless of their native sampling rate —
 * same trick the void compressor uses before lstsq fit.
 */
export function resample(wave: readonly number[], targetLen: number): number[] {
  if (wave.length === 0 || targetLen <= 0) return new Array(targetLen).fill(0);
  if (wave.length === targetLen) return [...wave];
  const out = new Array<number>(targetLen);
  const scale = (wave.length - 1) / (targetLen - 1 || 1);
  for (let i = 0; i < targetLen; i++) {
    const x = i * scale;
    const lo = Math.floor(x);
    const hi = Math.min(wave.length - 1, lo + 1);
    const frac = x - lo;
    out[i] = wave[lo] * (1 - frac) + wave[hi] * frac;
  }
  return out;
}

/**
 * Min-max normalize a waveform into [0, 1]. Constant waveforms collapse to 0.5.
 * Mirrors ResonanceDetector._compute_signature so correlations are scale-invariant.
 */
export function normalize(wave: readonly number[]): number[] {
  if (wave.length === 0) return [];
  let min = Infinity;
  let max = -Infinity;
  for (const v of wave) {
    if (v < min) min = v;
    if (v > max) max = v;
  }
  const range = max - min;
  if (range <= EPSILON) return wave.map(() => 0.5);
  return wave.map((v) => (v - min) / range);
}

/**
 * Cascade: correlate a query waveform against a library of named substrates.
 * Returns per-substrate correlation + coherency (mean |r| of top-5 matches).
 * Direct port of ResonanceDetector.fast_cascade's inner loop.
 */
export interface CascadeMatch {
  readonly name: string;
  readonly r: number;
  readonly kind: 'harmonic' | 'anti-phase' | 'weak' | 'noise';
}

export interface CascadeResult {
  readonly coherency: number;
  readonly matches: readonly CascadeMatch[];
}

export function cascade(
  query: readonly number[],
  substrates: ReadonlyMap<string, readonly number[]>,
): CascadeResult {
  const targetLen = 128;
  const qNorm = normalize(resample(query, targetLen));
  const matches: CascadeMatch[] = [];
  for (const [name, sub] of substrates) {
    const sNorm = normalize(resample(sub, targetLen));
    const r = pearson(qNorm, sNorm);
    const abs = Math.abs(r);
    const kind: CascadeMatch['kind'] =
      r >= 0.5 ? 'harmonic' :
      r <= -0.5 ? 'anti-phase' :
      abs >= 0.3 ? 'weak' :
      'noise';
    matches.push({ name, r, kind });
  }
  // Return a sorted copy — never mutate the locally-built matches array,
  // so the returned .matches property can be reasoned about independently.
  const sorted = [...matches].sort((a, b) => Math.abs(b.r) - Math.abs(a.r));
  const top = sorted.slice(0, 5);
  const coherency = top.length > 0
    ? top.reduce((s, m) => s + Math.abs(m.r), 0) / top.length
    : 0;
  return { coherency, matches: sorted };
}

/**
 * Remembrance coherency thresholds (ported from src/core/remembrance-lexicon.js).
 * One canonical table across the ecosystem so cathedral, oracle, and void
 * agree on what "stable" or "transcendent" means.
 */
export const COHERENCY_THRESHOLDS = {
  REJECTION: 0.00,
  GATE: 0.60,
  PULL: 0.68,
  FOUNDATION: 0.70,
  STABILITY: 0.75,
  OPTIMIZATION: 0.80,
  SYNERGY: 0.85,
  INTELLIGENCE: 0.90,
  TRANSCENDENCE: 0.95,
  UNITY: 0.98,
} as const;

export type CoherencyTier =
  | 'rejection'
  | 'gate'
  | 'pull'
  | 'foundation'
  | 'stability'
  | 'optimization'
  | 'synergy'
  | 'intelligence'
  | 'transcendence'
  | 'unity';

/** Map a coherency score to its threshold tier (highest bucket it clears). */
export function tierFor(score: number): CoherencyTier {
  const t = COHERENCY_THRESHOLDS;
  if (score >= t.UNITY) return 'unity';
  if (score >= t.TRANSCENDENCE) return 'transcendence';
  if (score >= t.INTELLIGENCE) return 'intelligence';
  if (score >= t.SYNERGY) return 'synergy';
  if (score >= t.OPTIMIZATION) return 'optimization';
  if (score >= t.STABILITY) return 'stability';
  if (score >= t.FOUNDATION) return 'foundation';
  if (score >= t.PULL) return 'pull';
  if (score >= t.GATE) return 'gate';
  return 'rejection';
}

/**
 * Void Pattern Library — server-side helpers.
 *
 * The cathedral's "pattern library" is the curated archetype set in
 * lead-substrates.ts (the same `group/name` shape the void substrate uses at
 * 80k-pattern scale, scaled down to veteran-life-insurance leads). Every
 * admitted lead is stamped at intake with its dominant archetype + coherency
 * and recorded in the lead ledger.
 *
 * These helpers read that ledger back so the admin can browse the library and
 * pull the leads that resonate with each archetype — deliberately WITHOUT
 * touching the DB-paginated /api/admin/leads path, because the archetype stamp
 * lives in the ledger, not the leads table. The ledger already carries the
 * sellable contact fields (name/email/phone/state/coverage), so it is a
 * sufficient source for the pattern views on its own.
 */

import { LEAD_ARCHETYPES, archetypeGroup } from "./lead-substrates";
import {
  listLedgerMonths,
  readLedgerMonth,
  type LedgerEntry,
} from "./lead-ledger";

export interface ArchetypeDescriptor {
  /** Fully-qualified name, e.g. "valor/protective-veteran". */
  name: string;
  group: "valor" | "fraud" | "bot" | "unknown";
  /** The 16-dimension archetype signature (shape, not magnitudes). */
  vector: readonly number[];
}

/** The static archetype library, in declaration order. */
export function listArchetypes(): ArchetypeDescriptor[] {
  const out: ArchetypeDescriptor[] = [];
  for (const [name, vector] of LEAD_ARCHETYPES) {
    out.push({ name, group: archetypeGroup(name), vector });
  }
  return out;
}

/** A lead as recorded in the ledger, normalized for the admin pattern views. */
export interface LedgerLeadRow {
  leadId: string;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  state: string;
  coverageInterest: string;
  veteranStatus: string;
  militaryBranch: string;
  archetype: string;
  group: string;
  coherency: number;
  tier: string;
  verdict: string;
  observedAt: string;
}

function toRow(e: LedgerEntry): LedgerLeadRow {
  return {
    leadId: e.leadId,
    firstName: e.lead.firstName,
    lastName: e.lead.lastName,
    email: e.lead.email,
    phone: e.lead.phone,
    state: e.lead.state,
    coverageInterest: e.lead.coverageInterest,
    veteranStatus: e.lead.veteranStatus,
    militaryBranch: e.lead.militaryBranch,
    archetype: e.coherency.dominantArchetype,
    group: e.coherency.dominantGroup,
    coherency: e.coherency.score,
    tier: e.coherency.tier,
    verdict: e.covenant.verdict,
    observedAt: e.observedAt,
  };
}

export interface LoadLedgerOptions {
  /** How many of the most recent months to scan (default 6). */
  maxMonths?: number;
  /** Hard cap on rows returned (default 5000). */
  maxEntries?: number;
}

/**
 * Aggregate ledger entries across recent months, newest-first, deduped by
 * leadId (keeping the most recent stamp for each lead — so a re-scored lead
 * reflects its latest archetype). Bounded by maxMonths and maxEntries so a
 * large ledger can't blow up a serverless invocation.
 */
export async function loadLedgerLeads(opts: LoadLedgerOptions = {}): Promise<LedgerLeadRow[]> {
  const maxMonths = opts.maxMonths ?? 6;
  const maxEntries = opts.maxEntries ?? 5000;

  const months = await listLedgerMonths();
  // Sort descending by YYYY-MM and take the most recent window.
  const recent = [...months]
    .sort((a, b) => b.month.localeCompare(a.month))
    .slice(0, maxMonths);

  const seen = new Set<string>();
  const rows: LedgerLeadRow[] = [];

  for (const m of recent) {
    if (rows.length >= maxEntries) break;
    const text = await readLedgerMonth(m.month);
    if (!text) continue;
    // JSONL is append-order (oldest first); walk it backwards so the newest
    // stamp wins on dedupe.
    const lines = text.split("\n");
    for (let i = lines.length - 1; i >= 0; i--) {
      if (rows.length >= maxEntries) break;
      const line = lines[i].trim();
      if (!line) continue;
      let entry: LedgerEntry;
      try {
        entry = JSON.parse(line) as LedgerEntry;
      } catch {
        continue; // skip a malformed line rather than failing the whole read
      }
      if (!entry?.leadId || seen.has(entry.leadId)) continue;
      seen.add(entry.leadId);
      rows.push(toRow(entry));
    }
  }
  return rows;
}

/**
 * Count ledger leads per archetype. Seeds every library archetype at 0 so the
 * UI can show empty archetypes too; tolerates archetypes that no longer exist
 * in the library (older stamps) by counting them under their recorded name.
 */
export function tallyByArchetype(rows: readonly LedgerLeadRow[]): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const name of LEAD_ARCHETYPES.keys()) counts[name] = 0;
  for (const r of rows) {
    counts[r.archetype] = (counts[r.archetype] ?? 0) + 1;
  }
  return counts;
}

/**
 * Twilio SMS Integration
 *
 * Sends SMS notifications via the Twilio REST API (no SDK — just fetch).
 *
 * Environment variables:
 *   TWILIO_ACCOUNT_SID  — Twilio Account SID
 *   TWILIO_AUTH_TOKEN   — Twilio Auth Token
 *   TWILIO_FROM_NUMBER  — Twilio phone number to send from (E.164 format)
 *   ADMIN_PHONE         — Admin phone number for lead alerts (optional)
 */

// --- Retry with exponential backoff ---
async function retry<T>(
  fn: () => Promise<T>,
  maxRetries: number = 2,
  delay: number = 1000,
): Promise<T> {
  let lastError: unknown;
  for (let i = 0; i <= maxRetries; i++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
      if (i < maxRetries) {
        await new Promise((r) => setTimeout(r, delay * Math.pow(2, i)));
      }
    }
  }
  throw lastError;
}

/** Coverage labels for SMS messages */
const COVERAGE_LABELS: Record<string, string> = {
  term: "Term Life Insurance",
  whole: "Whole Life Insurance",
  universal: "Universal Life Insurance",
  "final-expense": "Final Expense Insurance",
  annuity: "Annuity",
  "not-sure": "insurance coverage",
};

/**
 * Send an SMS via the Twilio REST API.
 *
 * If TWILIO_ACCOUNT_SID is not set, logs the message to console (dev mode).
 */
async function sendSms(to: string, body: string): Promise<void> {
  const accountSid = process.env.TWILIO_ACCOUNT_SID;
  const authToken = process.env.TWILIO_AUTH_TOKEN;
  const fromNumber = process.env.TWILIO_FROM_NUMBER;

  if (!accountSid) {
    console.log("[SMS][DEV] Would send SMS:");
    console.log(`  To: ${to}`);
    console.log(`  From: ${fromNumber || "(not configured)"}`);
    console.log(`  Body: ${body}`);
    return;
  }

  if (!authToken || !fromNumber) {
    console.warn(
      "[SMS] TWILIO_ACCOUNT_SID is set but TWILIO_AUTH_TOKEN or TWILIO_FROM_NUMBER is missing. Skipping SMS.",
    );
    return;
  }

  const url = `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`;
  const credentials = Buffer.from(`${accountSid}:${authToken}`).toString("base64");

  await retry(async () => {
    const params = new URLSearchParams({
      To: to,
      From: fromNumber,
      Body: body,
    });

    const res = await fetch(url, {
      method: "POST",
      headers: {
        "Content-Type": "application/x-www-form-urlencoded",
        Authorization: `Basic ${credentials}`,
      },
      body: params.toString(),
      signal: AbortSignal.timeout(10000),
    });

    if (!res.ok) {
      const errorBody = await res.text();
      throw new Error(`Twilio API error: ${res.status} ${errorBody}`);
    }
  }, 2, 1000);
}

/**
