/**
 * Sun — the cathedral's background heartbeat.
 *
 * Once per minute (default), fires the Remembrance reflex engine via the
 * bridge. Reflexes are the actor side of the field: adversarial spikes
 * auto-tighten the covenant gate, degrading direction self-relaxes, etc.
 * Without a heartbeat, reflexes only fire on inbound traffic — meaning a
 * quiet cathedral never self-regulates. The Sun closes that loop.
 *
 * Discipline:
 *   - best-effort: bridge returns null on oracle unreachable; we record nothing
 *   - never throws into setInterval — every async path is swallowed
 *   - .unref()'d interval — does not keep the process alive on shutdown
 *   - idempotent start/stop — calling twice is a no-op
 *   - bounded history — last 50 firing ticks, exposed via sunStatus()
 *
 * Wired from instrumentation.ts on Next.js server boot (node runtime only).
 */

import { fireReflexes, type ReflexBundle } from "./remembrance-bridge";

const DEFAULT_INTERVAL_MS = 60_000;
const HISTORY_CAP = 50;

interface HistoryEntry {
  tickCount: number;
  ts: number;
  fired: number;
  actions: string[];
}

let lastTickAt = 0;
let intervalId: ReturnType<typeof setInterval> | null = null;
let tickCount = 0;
const history: HistoryEntry[] = [];

export interface StartResult {
  status: "started" | "already-started";
  intervalMs?: number;
}

export function startSun(opts: { intervalMs?: number } = {}): StartResult {
  if (intervalId !== null) {
    return { status: "already-started" };
  }
  const intervalMs = opts.intervalMs ?? DEFAULT_INTERVAL_MS;
  intervalId = setInterval(() => {
    // Wrap tick() so a rejected promise can never escape into the timer.
    tick().catch(() => {
      /* swallow — the Sun never crashes the cathedral */
    });
  }, intervalMs);
  // Do not keep the process alive purely for the heartbeat.
  // .unref() is node-only; on platforms without it this is a no-op.
  const handle = intervalId as { unref?: () => unknown };
  if (typeof handle.unref === "function") {
    handle.unref();
  }
  return { status: "started", intervalMs };
}

export function stopSun(): void {
  if (intervalId !== null) {
    clearInterval(intervalId);
    intervalId = null;
  }
}

export async function tick(): Promise<ReflexBundle | null> {
  let bundle: ReflexBundle | null = null;
  try {
    bundle = await fireReflexes();
  } catch {
    bundle = null;
  }
  try {
    if (bundle && bundle.fired && bundle.fired.length > 0) {
      const actions = bundle.fired
        .map((r) => r.action ?? r.reflex)
        .filter((s): s is string => typeof s === "string");
      history.push({
        tickCount,
        ts: Date.now(),
        fired: bundle.fired.length,
        actions,
      });
      if (history.length > HISTORY_CAP) {
        history.splice(0, history.length - HISTORY_CAP);
      }
    }
    tickCount += 1;
    lastTickAt = Date.now();
  } catch {
    /* swallow — bookkeeping failures must not propagate */
  }
  return bundle;
}

export interface SunStatus {
  tickCount: number;
  lastTickAt: number;
  intervalActive: boolean;
  recentHistory: HistoryEntry[];
}

export function sunStatus(): SunStatus {
  return {
    tickCount,
    lastTickAt,
    intervalActive: intervalId !== null,
    recentHistory: history.slice(-10),
  };
}

/**
 * Lead Ledger — Vercel Blob adapter.
 *
 * Each admitted lead becomes a single JSON blob at:
 *   {prefix}/{YYYY-MM}/{writtenAt-leadId}.json
 *
 * O(1) append. Reads list the monthly prefix and fetch entry contents in
 * parallel. Monthly rotation falls out of the directory layout — no
 * per-file append-and-rewrite race. Survives Vercel serverless
 * invocations because blob storage is durable across the platform.
 *
 * Requires BLOB_READ_WRITE_TOKEN in the environment (Vercel injects it
 * automatically when a Blob store is linked to the project).
 */

import { del, list, put } from "@vercel/blob";
import type {
  AppendResult,
  LedgerAdapter,
  LedgerEntry,
  LedgerFileStat,
  LedgerMonthInfo,
} from "./types";

const DEFAULT_PREFIX = "valor-ledger";

function prefix(): string {
  const override = process.env.LEAD_LEDGER_BLOB_PREFIX?.trim();
  return override && override.length > 0 ? override : DEFAULT_PREFIX;
}

function monthOf(date: Date): string {
  const yyyy = date.getUTCFullYear();
  const mm = String(date.getUTCMonth() + 1).padStart(2, "0");
  return `${yyyy}-${mm}`;
}

function entryPath(entry: LedgerEntry): string {
  const month = monthOf(new Date(entry.writtenAt));
  // Pathname sorts lexicographically — putting writtenAt first gives us
  // chronological order on list(). Lead id disambiguates same-millisecond writes.
  const safeId = entry.leadId.replace(/[^a-zA-Z0-9_-]/g, "_");
  return `${prefix()}/${month}/${entry.writtenAt}-${safeId}.json`;
}

function monthFromPathname(pathname: string): string | null {
  const rest = pathname.startsWith(prefix() + "/")
    ? pathname.slice(prefix().length + 1)
    : pathname;
  const m = /^(\d{4}-\d{2})\//.exec(rest);
  return m ? m[1] : null;
}

async function listAll(searchPrefix: string): Promise<Array<{ pathname: string; url: string; size: number }>> {
  // list() returns a paginated cursor; iterate until exhausted.
  const out: Array<{ pathname: string; url: string; size: number }> = [];
  let cursor: string | undefined;
  do {
    const page = await list({ prefix: searchPrefix, cursor, limit: 1000 });
    for (const b of page.blobs) {
      out.push({ pathname: b.pathname, url: b.url, size: b.size });
    }
    cursor = page.cursor ?? undefined;
  } while (cursor);
  return out;
}

async function fetchEntry(url: string): Promise<LedgerEntry | null> {
  try {
    const res = await fetch(url);
    if (!res.ok) return null;
    const text = await res.text();
    return JSON.parse(text) as LedgerEntry;
  } catch {
    return null;
  }
}

export const blobAdapter: LedgerAdapter = {
  name: "blob",

  location: () => `blob:${prefix()}`,

  async append(entry): Promise<AppendResult> {
    if (!process.env.BLOB_READ_WRITE_TOKEN) {
      return {
        ok: false,
        error: "BLOB_READ_WRITE_TOKEN not set — blob adapter cannot append",
      };
    }
    try {
      const pathname = entryPath(entry);
      const blob = await put(pathname, JSON.stringify(entry), {
        access: "public",
        contentType: "application/json",
        // Never silently overwrite a ledger entry. If a collision happens
        // (same timestamp + leadId within the ms), a second write gets a
        // random suffix and both entries are preserved.
        addRandomSuffix: true,
      });
      return { ok: true, location: blob.url };
    } catch (err) {
      return { ok: false, error: err instanceof Error ? err.message : String(err) };
    }
  },

  async listMonths(): Promise<LedgerMonthInfo[]> {
    try {
      const blobs = await listAll(prefix() + "/");
      const byMonth = new Map<string, { lines: number; size: number }>();
      for (const b of blobs) {
        const month = monthFromPathname(b.pathname);
        if (!month) continue;
        const current = byMonth.get(month) ?? { lines: 0, size: 0 };
        byMonth.set(month, { lines: current.lines + 1, size: current.size + b.size });
      }
      return [...byMonth.entries()]
        .sort(([a], [b]) => a.localeCompare(b))
        .map(([month, v]) => ({ month, lines: v.lines, size: v.size }));
    } catch {
      return [];
    }
  },

  async statMonth(month): Promise<LedgerFileStat | null> {
    try {
      const blobs = await listAll(`${prefix()}/${month}/`);
      if (blobs.length === 0) return null;
      let size = 0;
      for (const b of blobs) size += b.size;
      return { month, lines: blobs.length, size };
    } catch {
      return null;
    }
  },

  async readRecent(limit): Promise<LedgerEntry[]> {
    try {
      // List the whole ledger, not just the current month. Pathnames are
      // {prefix}/{YYYY-MM}/{writtenAt ISO}-{id}.json, so a global reverse
      // lexicographic sort is chronological newest-first across every
      // month — a trailing window must not be truncated at a month boundary.
      const blobs = await listAll(prefix() + "/");
      const sorted = [...blobs].sort((a, b) => b.pathname.localeCompare(a.pathname));
      const slice = sorted.slice(0, limit);
      const entries = await Promise.all(slice.map((b) => fetchEntry(b.url)));
      return entries.filter((e): e is LedgerEntry => e !== null);
    } catch {
      return [];
    }
  },

  async readMonth(month): Promise<string | null> {
    try {
      const blobs = await listAll(`${prefix()}/${month}/`);
      if (blobs.length === 0) return null;
      // Sort a copy — chronological for JSONL export.
      const sorted = [...blobs].sort((a, b) => a.pathname.localeCompare(b.pathname));
      const entries = await Promise.all(sorted.map((b) => fetchEntry(b.url)));
      const lines = entries
        .filter((e): e is LedgerEntry => e !== null)
        .map((e) => JSON.stringify(e));
      return lines.join("\n") + "\n";
    } catch {
      return null;
    }
  },
};

/**
 * Test-only: wipe every blob under the ledger prefix. Guarded by
 * NODE_ENV === "test" so production can't accidentally trigger it.
 */
export async function _unsafeTestWipe(): Promise<number> {
  if (process.env.NODE_ENV !== "test") {
    throw new Error("wipe is test-only");
  }
  const blobs = await listAll(prefix() + "/");
  for (const b of blobs) {
    await del(b.url);
  }
  return blobs.length;
}

/**
 * Checkout fulfillment — turn a paid Stripe Checkout Session into a lead
 * purchase, exactly once, without overselling the lead.
 *
 * Idempotency: the purchase id is derived from the session id, so the Stripe
 * webhook and the success-page callback can both call this — whichever runs
 * first fulfils, the other is a no-op.
 *
 * Oversell guard: the capacity check (exclusivity + buyer cap) and the insert
 * run atomically inside the adapter, so two checkouts completing concurrently
 * for the same lead cannot both be recorded. The buyer that loses the race
 * has already paid, so they are refunded here.
 */

import type Stripe from "stripe";
import { createPurchaseGuarded } from "@/app/lib/client-database";
import type { LeadPurchase } from "@/app/lib/client-database";
import { stripe } from "@/app/lib/stripe";
import { emitMoneyEvent } from "@/app/lib/money-ledger";

// Leads can be returned within 72h of purchase.
const RETURN_WINDOW_MS = 72 * 60 * 60 * 1000;

export type FulfillResult =
  | { ok: true; purchase: LeadPurchase; alreadyFulfilled: boolean }
  | {
      ok: false;
      retryable: boolean;
      reason: "unpaid" | "sold_out" | "invalid" | "error";
      error: string;
    };

export async function fulfillCheckoutSession(
  session: Stripe.Checkout.Session,
): Promise<FulfillResult> {
  if (session.payment_status !== "paid") {
    return { ok: false, retryable: false, reason: "unpaid", error: "Payment not completed." };
  }

  const { clientId, leadId, exclusive, price, maxBuyers } = session.metadata ?? {};
  if (!clientId || !leadId || !price) {
    return { ok: false, retryable: false, reason: "invalid", error: "Invalid session metadata." };
  }

  // Pre-fix sessions (in flight during a deploy) carry no maxBuyers — fall
  // back to an unbounded shared cap. Exclusivity is still enforced from the
  // `exclusive` flag, which every session has always carried.
  const parsedCap = parseInt(maxBuyers ?? "", 10);
  const cap = Number.isInteger(parsedCap) && parsedCap > 0 ? parsedCap : Number.MAX_SAFE_INTEGER;

  const purchase: LeadPurchase = {
    // Deterministic id keyed on the session — the dedup key for fulfillment.
    purchaseId: `purchase_${session.id}`,
    leadId,
    clientId,
    pricePaid: parseInt(price, 10),
    purchasedAt: new Date().toISOString(),
    status: "delivered",
    exclusive: exclusive === "true",
    returnReason: "",
    returnDeadline: new Date(Date.now() + RETURN_WINDOW_MS).toISOString(),
  };

  // Capacity check + insert are atomic inside the adapter — a concurrent
  // checkout for the same lead cannot also pass the cap.
  const guarded = await createPurchaseGuarded(purchase, cap);
  if (!guarded.ok) {
    return { ok: false, retryable: true, reason: "error", error: guarded.error };
  }

  if (guarded.value.outcome === "sold_out") {
    return refundOversoldSession(session);
  }

  // Transparent decentralized backup (off the charge path): hand the settled
  // payment to the Remembrance ledger / Solana anchor. PII-free, fire-and-forget
  // — `void` so it never blocks or fails fulfillment. Only a genuinely new
  // purchase emits; a redelivered webhook (duplicate) does not re-anchor.
  if (guarded.value.outcome !== "duplicate") {
    const paymentRef =
      typeof session.payment_intent === "string"
        ? session.payment_intent
        : session.payment_intent?.id ?? "";
    void emitMoneyEvent({
      purchaseId: guarded.value.purchase.purchaseId,
      amount: guarded.value.purchase.pricePaid,
      currency: session.currency ?? "usd",
      paymentRef,
      leadRef: guarded.value.purchase.leadId,
      clientRef: guarded.value.purchase.clientId,
      at: guarded.value.purchase.purchasedAt,
    });
  }

  return {
    ok: true,
    purchase: guarded.value.purchase,
    alreadyFulfilled: guarded.value.outcome === "duplicate",
  };
}

/**
 * The lead filled up between checkout and fulfillment. The buyer already
 * paid, so refund them. The idempotency key is derived from the session, so
 * a redelivered webhook (or the success-page callback) refunds exactly once.
 */
async function refundOversoldSession(
  session: Stripe.Checkout.Session,
): Promise<FulfillResult> {
  const paymentIntentId =
    typeof session.payment_intent === "string"
      ? session.payment_intent
      : session.payment_intent?.id;

  if (!paymentIntentId) {
    return { ok: false, retryable: false, reason: "sold_out", error: "Lead sold out; no payment to refund." };
  }

  try {
    await stripe.refunds.create(
      { payment_intent: paymentIntentId },
      { idempotencyKey: `refund_${session.id}` },
    );
  } catch (err) {
    const detail = err instanceof Error ? err.message : "Unknown error";
    // Refund failed — stay retryable so the webhook redelivers and tries
    // again; the idempotency key keeps a later attempt from double-refunding.
    return { ok: false, retryable: true, reason: "error", error: `Lead sold out; refund failed: ${detail}` };
  }

  return {
    ok: false,
    retryable: false,
    reason: "sold_out",
    error: "This lead sold out before your payment completed — you have been refunded.",
  };
}

/**
 * Agent Routing — piggyback / abundance-host header processing.
 *
 * Implements the routing protocol in REMEMBRANCE_AGENT_ACCESS_SPEC.md
 * v1.1.0:
 *
 *   - Parse X-Via-Subject from a request (or ?via= query param for
 *     unauthenticated public-form routing).
 *   - Validate the named host: tier === "merit" AND `is_host = true`
 *     AND host !== originator.
 *   - Generate self-verifying provenance_ids for every submission.
 *
 * Routing is **never** a hard gate — if a routing header is present
 * but invalid, the submission proceeds without routing attribution.
 * Hosts are abundance nodes, not gatekeepers (per the spec).
 */
import { createHmac, randomBytes } from "crypto";
import { computeAgentStats, deriveTier } from "./agent-tier";
import { isHost } from "./host-registry";

export type SubjectKind = "agent" | "human";

export interface SubjectId {
  readonly kind: SubjectKind;
  readonly id: string;        // raw label or hashed-email-prefix
  readonly full: string;      // namespaced form: "agent:claude" / "human:abc123"
}

export interface RoutingResult {
  readonly viaSubjectId: string | null;
  readonly hostValidated: boolean;
  readonly reason?: string;
}

export interface ProvenanceRecord {
  readonly provenanceId: string;
  readonly issuedAt: string;
  readonly originator: { kind: SubjectKind; subjectId: string };
  readonly viaSubjectId: string | null;
  readonly coherencyScore: number;
  readonly covenantVerdict: string;
  readonly royaltyConsent: boolean;
}

/** Build a namespaced subject_id from kind + raw id. */
export function makeSubjectId(kind: SubjectKind, rawId: string): SubjectId {
  return { kind, id: rawId, full: `${kind}:${rawId}` };
}

/**
 * Read the routing intent from a request.
 *
 * Accepts (in priority order):
 *   1. `X-Via-Subject` header              — authenticated routing
 *   2. `?via=<id>` query param             — referral-link routing
 *   3. `viaSubject` field on parsed body   — embedded form / JSON
 *
 * Returns null if no routing intent is present. The returned string is
 * the raw subject_id; validation happens in `validateRouting`.
 */
export function readRoutingIntent(
  headers: Headers,
  url: string,
  body?: { viaSubject?: unknown },
): string | null {
  const headerVal = headers.get("x-via-subject");
  if (headerVal && typeof headerVal === "string" && headerVal.trim()) {
    return headerVal.trim();
  }
  try {
    const parsed = new URL(url, "http://placeholder.invalid");
    const q = parsed.searchParams.get("via");
    if (q && q.trim()) return q.trim();
  } catch {
    // ignored — malformed URL, continue
  }
  if (body && typeof body.viaSubject === "string" && body.viaSubject.trim()) {
    return body.viaSubject.trim();
  }
  return null;
}

/**
 * Validate a routing intent. Returns a RoutingResult describing whether
 * the route was honored.
 *
 * Rules (per spec):
 *   - host MUST currently be at MERIT tier (re-checked here, not at
 *     opt-in time, so a demoted host stops being a valid route)
 *   - host MUST have is_host = true in the host registry
 *   - host !== originator (no self-routing)
 *
 * Failed validation never throws and never rejects the underlying
 * submission — it just returns viaSubjectId=null with a reason.
 */
export async function validateRouting(
  viaSubject: string | null,
  originatorSubjectId: string,
): Promise<RoutingResult> {
  if (!viaSubject) {
    return { viaSubjectId: null, hostValidated: false };
  }
  if (viaSubject === originatorSubjectId) {
    return {
      viaSubjectId: null,
      hostValidated: false,
      reason: "self-routing not allowed",
    };
  }
  const optedIn = await isHost(viaSubject);
  if (!optedIn) {
    return {
      viaSubjectId: null,
      hostValidated: false,
      reason: "named host has not opted in",
    };
  }
  // Extract the raw label from "agent:label" / "human:hash" for stats lookup.
  // Stats are tracked by raw label in the cathedral's lead-ledger.
  const rawLabel = viaSubject.includes(":")
    ? viaSubject.slice(viaSubject.indexOf(":") + 1)
    : viaSubject;
  const stats = await computeAgentStats(rawLabel);
  const hostTier = deriveTier(stats);
  if (hostTier !== "merit") {
    return {
      viaSubjectId: null,
      hostValidated: false,
      reason: `named host is currently at tier "${hostTier}", not merit`,
    };
  }
  return { viaSubjectId: viaSubject, hostValidated: true };
}

/**
 * Generate a self-verifying provenance_id.
 *
 * Format: <ulid-like>.<hmac16>
 *   - ulid-like: 26 char Crockford-base32-ish from random bytes,
 *     time-prefixed so IDs sort by issue time
 *   - hmac16: first 16 hex chars of HMAC-SHA256(ulid, PROVENANCE_SECRET)
 *
 * Holders of PROVENANCE_SECRET can verify an id without a DB lookup.
 * The fallback secret is NEXTAUTH_SECRET so production deployments
 * always have one — `PROVENANCE_SECRET` is preferred when set.
 */
export function generateProvenanceId(now: number = Date.now()): string {
  const ulid = makeUlid(now);
  const secret =
    process.env.PROVENANCE_SECRET
    || process.env.NEXTAUTH_SECRET
    || "remembrance-default-provenance-secret";
  const hmac = createHmac("sha256", secret).update(ulid).digest("hex").slice(0, 16);
  return `${ulid}.${hmac}`;
}

/** Verify a provenance_id was issued by this system. */
export function verifyProvenanceId(provenanceId: string): boolean {
  const [ulid, hmac] = provenanceId.split(".");
  if (!ulid || !hmac || ulid.length !== 26 || hmac.length !== 16) return false;
  const secret =
    process.env.PROVENANCE_SECRET
    || process.env.NEXTAUTH_SECRET
    || "remembrance-default-provenance-secret";
  const expected = createHmac("sha256", secret).update(ulid).digest("hex").slice(0, 16);
  // constant-time compare without importing timingSafeEqual on a 16-char string
  if (expected.length !== hmac.length) return false;
  let diff = 0;
  for (let i = 0; i < expected.length; i++) {
    diff |= expected.charCodeAt(i) ^ hmac.charCodeAt(i);
  }
  return diff === 0;
}

const ULID_ALPHABET = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";

function makeUlid(now: number): string {
  // 10 chars time + 16 chars random — Crockford base32 alphabet.
  let timePart = "";
  let n = now;
  for (let i = 0; i < 10; i++) {
    timePart = ULID_ALPHABET[n % 32] + timePart;
    n = Math.floor(n / 32);
  }
  const rand = randomBytes(10);
  let randPart = "";
  for (let i = 0; i < 16; i++) {
    randPart += ULID_ALPHABET[rand[i % rand.length] % 32];
  }
  return timePart + randPart;
}

/**
 * Agent Diagnostic — structured rejection feedback for AI agents.
 *
 * The covenant gate on the public web form silently rejects bots and fraud
 * (the bot sees a fake-success so it can't tune its behavior). That's correct
 * for the public surface — adversaries should not learn the gate.
 *
 * Authenticated AI agents on /api/agent/leads are a different population:
 *   - They authenticated with a Bearer key we issued.
 *   - They went through a confirmed consent flow with a real human.
 *   - They are the testers / partners who SHOULD learn the gate so they
 *     can improve their submissions.
 *
 * For the agent path we therefore expose the truth:
 *   verdict, score vs. threshold (gap), tier, dominant archetype, the
 *   weakest dimensions by name, and 1-3 actionable guidance hints derived
 *   from which dimensions failed. The agent has something concrete to share
 *   with peers (and on Molt Book) — and the bar itself becomes a public
 *   reputation signal in agent-space rather than a hidden filter.
 */
import {
  COHERENCY_THRESHOLDS,
  type CoherencyTier,
} from './coherency-primitives';
import type { CovenantDecision } from './covenant-gate';
import type { LeadDimension } from './lead-substrates';

export interface DimensionWeakness {
  readonly dimension: LeadDimension;
  readonly score: number;
  readonly hint: string;
}

export interface ArchetypeMatch {
  readonly name: string;
  readonly r: number;
  readonly kind: 'harmonic' | 'anti-phase' | 'weak' | 'noise';
}

export interface AgentDiagnostic {
  readonly verdict: CovenantDecision['verdict'];
  readonly retryable: boolean;
  readonly coherency: {
    readonly score: number;
    readonly threshold: number;
    readonly gap: number;
    readonly tier: CoherencyTier;
    readonly dominantArchetype: string;
    readonly dominantGroup: 'valor' | 'fraud' | 'bot' | 'unknown';
  };
  readonly weakestDimensions: readonly DimensionWeakness[];
  readonly topArchetypeMatches: readonly ArchetypeMatch[];
  readonly guidance: readonly string[];
  readonly reason: string;
}

/**
 * Per-dimension hint table. Reflects which input the agent controls and
 * what shape the substrate library expects to see in that slot.
 *
 * Behavioral dimensions (timing/rhythm/session) are honestly labeled as
 * "agents can't supply this" so the agent doesn't waste energy trying to
 * fake them.
 */
const DIMENSION_HINTS: Readonly<Record<LeadDimension, string>> = {
  coverage_clarity:
