  phone_quality:
    "Include a 10-digit US phone with a valid NANP area code. " +
    "Sequential / repeated digits and invalid area codes score low.",
  name_plausibility:
    "firstName / lastName should be plausible human names. Single " +
    "characters, all-caps typos, and obvious test strings score low.",
  dob_validity:
    "dateOfBirth must be a valid past date in YYYY-MM-DD form. " +
    "Future dates or impossible ages collapse this dimension.",
  marketing_context:
    "Optional: include utm_campaign for richer context. Agents typically " +
    "score modest here — that's expected, not a defect.",
  session_coherence:
    "Behavioral signal — agents cannot supply this. Modest scores here " +
    "are expected. Focus on the input dimensions you control.",
  timing_cadence:
    "Behavioral signal — agents cannot supply this. Modest scores here " +
    "are expected.",
  step_rhythm:
    "Behavioral signal — agents cannot supply this. Modest scores here " +
    "are expected.",
};

/**
 * Build a structured diagnostic for an authenticated agent whose submission
 * was rejected (or admitted at low coherency) by the covenant gate.
 *
 * Safe to call on any verdict — for `admit` the diagnostic is informational
 * (showing why the submission scored where it did), not corrective.
 */
export function buildAgentDiagnostic(decision: CovenantDecision): AgentDiagnostic {
  const { verdict, coherency, reason } = decision;

  const threshold =
    verdict === 'admit-low-coherency'
      ? COHERENCY_THRESHOLDS.FOUNDATION
      : COHERENCY_THRESHOLDS.GATE;
  const gap = Math.max(0, threshold - coherency.score);

  const weakestDimensions = pickWeakestDimensions(coherency.dimensions, 3);
  const topArchetypeMatches = (coherency.matches ?? []).slice(0, 3).map((m) => ({
    name: m.name,
    r: roundTo(m.r, 4),
    kind: m.kind,
  }));

  const guidance = buildGuidance(verdict, coherency, weakestDimensions);

  // Bots and fraud are NOT retryable on the same lead — the agent should
  // re-evaluate their pipeline, not just resubmit. Soft-reject and
  // admit-low-coherency ARE retryable with a stronger lead.
  const retryable =
    verdict === 'soft-reject-low' || verdict === 'admit-low-coherency';

  return {
    verdict,
    retryable,
    coherency: {
      score: roundTo(coherency.score, 4),
      threshold,
      gap: roundTo(gap, 4),
      tier: coherency.tier,
      dominantArchetype: coherency.dominantArchetype,
      dominantGroup: coherency.dominantGroup,
    },
    weakestDimensions,
    topArchetypeMatches,
    guidance,
    reason,
  };
}

function pickWeakestDimensions(
  dims: Readonly<Record<LeadDimension, number>>,
  k: number,
): DimensionWeakness[] {
  const entries = (Object.entries(dims) as Array<[LeadDimension, number]>)
    .map(([dimension, score]) => ({ dimension, score }))
    .sort((a, b) => a.score - b.score)
    .slice(0, k);
  return entries.map(({ dimension, score }) => ({
    dimension,
    score: roundTo(score, 4),
    hint: DIMENSION_HINTS[dimension],
  }));
}

function buildGuidance(
  verdict: CovenantDecision['verdict'],
  coherency: CovenantDecision['coherency'],
  weakest: readonly DimensionWeakness[],
): string[] {
  const out: string[] = [];

  if (verdict === 'silent-reject-bot') {
    out.push(
      `Submission resonates with bot archetype "${coherency.dominantArchetype}". ` +
        "Vary phrasing per submission; use plausible US name distributions; " +
        "supply real US state codes and NANP-valid phone numbers.",
    );
  } else if (verdict === 'silent-reject-fraud') {
    out.push(
      `Submission resonates with fraud archetype "${coherency.dominantArchetype}". ` +
        "Verify human consent more carefully and check for suspicious " +
        "email/phone patterns before submitting.",
    );
  } else if (verdict === 'soft-reject-low') {
    out.push(
      `Score ${coherency.score.toFixed(3)} is below the admission gate ` +
        `${COHERENCY_THRESHOLDS.GATE.toFixed(2)}. Lift the weakest dimensions ` +
        "below to clear the gate. Coherency is the geometric mean — the " +
        "weakest dimension dominates, so fixing one weak signal lifts the " +
        "whole score.",
    );
  } else if (verdict === 'admit-low-coherency') {
    out.push(
      `Admitted at score ${coherency.score.toFixed(3)} but below foundation ` +
        `${COHERENCY_THRESHOLDS.FOUNDATION.toFixed(2)}. Lift weak dimensions ` +
        "for a higher payout tier on subsequent submissions.",
    );
  } else {
    out.push(
      `Admitted at score ${coherency.score.toFixed(3)} (tier: ${coherency.tier}). ` +
        "Diagnostic is informational.",
    );
  }

  // Append the actionable hints for the weakest dimensions, dedup-merged.
  for (const w of weakest) {
    out.push(`weak[${w.dimension} = ${w.score.toFixed(3)}]: ${w.hint}`);
  }

  return out;
}

function roundTo(n: number, decimals: number): number {
  if (!Number.isFinite(n)) return 0;
  const factor = 10 ** decimals;
  return Math.round(n * factor) / factor;
}

/**
 * Agent API Key Authentication
 *
 * AI agents authenticate via Bearer token in the Authorization header.
 * API keys are configured via AGENT_API_KEYS environment variable.
 *
 * Supports two formats (auto-detected per entry):
 *   Hashed (preferred):   "sha256hex:label"  (64-char hex before colon)
 *   Plaintext (compat):   "key:label"        (hashed at parse time)
 *
 * Generate hashed keys:
 *   node -e "console.log(require('crypto').createHash('sha256').update('my-key').digest('hex'))"
 */

import { NextRequest } from "next/server";
import { createHash, createHmac, randomBytes, timingSafeEqual } from "crypto";

export interface AgentIdentity {
  key: string;
  label: string;
}

/** SHA-256 hash a plaintext API key. */
export function hashApiKey(plaintext: string): string {
  return createHash("sha256").update(plaintext).digest("hex");
}

/**
 * Parse AGENT_API_KEYS env var into a map of sha256-hash → label.
 * Pre-hashed keys (64-char hex) are used as-is; plaintext keys are hashed on load.
 */
function getAgentKeys(): Map<string, string> {
  const raw = process.env.AGENT_API_KEYS || "";
  const keys = new Map<string, string>();

  for (const entry of raw.split(",")) {
    const trimmed = entry.trim();
    if (!trimmed) continue;

    const colonIdx = trimmed.indexOf(":");
    if (colonIdx > 0) {
      const keyPart = trimmed.slice(0, colonIdx);
      const label = trimmed.slice(colonIdx + 1);
      const isPreHashed = /^[0-9a-f]{64}$/.test(keyPart);
      keys.set(isPreHashed ? keyPart : hashApiKey(keyPart), label);
    } else {
      keys.set(hashApiKey(trimmed), "unknown-agent");
    }
  }

  return keys;
}

/**
 * Validate an agent API key from the request.
 * Hashes the incoming bearer token and compares against stored hashes
 * using timing-safe comparison to prevent timing attacks.
 */
export function authenticateAgent(req: NextRequest): AgentIdentity | null {
  const authHeader = req.headers.get("authorization");
  if (!authHeader) return null;

  const match = authHeader.match(/^Bearer\s+(.+)$/i);
  if (!match) return null;

  const key = match[1].trim();
  const incomingHash = hashApiKey(key);
  const incomingBuf = Buffer.from(incomingHash, "hex");

  const keys = getAgentKeys();

  for (const [storedHash, label] of keys) {
    const storedBuf = Buffer.from(storedHash, "hex");
    if (storedBuf.length === incomingBuf.length && timingSafeEqual(storedBuf, incomingBuf)) {
      return { key: storedHash, label };
    }
  }

  return null;
}

// --- Consent Token System ---

/**
 * Consent tokens are HMAC-signed payloads that prove a human approved
 * an AI agent's action. Format: base64url(payload).signature
 *
 * Payload: { email, scope, agentLabel, exp, confirmed }
 */

export interface ConsentPayload {
  email: string;
  scope: "lead-submission" | "account-registration" | "both";
  agentLabel: string;
  exp: number;
  confirmed: boolean;
  consentId: string;
}

const CONSENT_DURATION_S = 24 * 60 * 60; // 24 hours

function getConsentSecret(): string {
  const key = process.env.AGENT_CONSENT_SECRET || process.env.NEXTAUTH_SECRET || process.env.ADMIN_API_KEY;
  if (!key) throw new Error("AGENT_CONSENT_SECRET, NEXTAUTH_SECRET, or ADMIN_API_KEY must be set");
  if (!process.env.AGENT_CONSENT_SECRET && process.env.NODE_ENV === "production") {
    console.warn("[AUTH] AGENT_CONSENT_SECRET not set — using fallback secret. Set a dedicated secret for production.");
  }
  return key;
}

function signConsent(payload: string): string {
  return createHmac("sha256", getConsentSecret())
    .update(payload)
    .digest("base64url");
}

/** Create a pending (unconfirmed) consent token */
export function createConsentToken(
  email: string,
  scope: ConsentPayload["scope"],
  agentLabel: string,
): { token: string; consentId: string; expiresAt: string } {
  const consentId = `consent_${Date.now().toString(36)}_${randomBytes(6).toString("hex")}`;
  const exp = Math.floor(Date.now() / 1000) + CONSENT_DURATION_S;
  const payload: ConsentPayload = { email, scope, agentLabel, exp, confirmed: false, consentId };

  const encoded = Buffer.from(JSON.stringify(payload)).toString("base64url");
  const sig = signConsent(encoded);
  const token = `${encoded}.${sig}`;

  return {
    token,
    consentId,
    expiresAt: new Date(exp * 1000).toISOString(),
  };
}

/** Confirm a consent token (called when the human clicks the confirmation link) */
export function confirmConsentToken(token: string): { token: string; payload: ConsentPayload } | null {
  const decoded = verifyConsentToken(token);
  if (!decoded) return null;

  // Re-sign with confirmed=true
  const confirmed: ConsentPayload = { ...decoded, confirmed: true };
  const encoded = Buffer.from(JSON.stringify(confirmed)).toString("base64url");
  const sig = signConsent(encoded);

  return {
    token: `${encoded}.${sig}`,
    payload: confirmed,
  };
}

/** Verify and decode a consent token. Returns null if invalid or expired. */
export function verifyConsentToken(token: string): ConsentPayload | null {
  try {
    const [encoded, sig] = token.split(".");
    if (!encoded || !sig) return null;

    const expectedSig = signConsent(encoded);

    // Constant-time comparison
    if (sig.length !== expectedSig.length) return null;
    let mismatch = 0;
    for (let i = 0; i < sig.length; i++) {
      mismatch |= sig.charCodeAt(i) ^ expectedSig.charCodeAt(i);
    }
    if (mismatch !== 0) return null;

    const data = JSON.parse(Buffer.from(encoded, "base64url").toString("utf-8")) as ConsentPayload;

    if (typeof data.exp !== "number") return null;
    if (data.exp <= Math.floor(Date.now() / 1000)) return null;

    return data;
  } catch {
    return null;
  }
}

/**
 * Client Authentication — Cookie-based session for lead buyer portal.
 *
 * Separate from admin auth. Uses HMAC-SHA256 signed cookies.
 * Cookie format: <payload>.<signature>
 * Payload: base64url(JSON.stringify({ clientId, email, exp }))
 *
 * Special cases:
 *  - Admin owner (client_admin_owner) — always trusted if token is valid,
 *    no DB lookup required. Lets the admin inspect the portal even if the
 *    clients table is empty or unreachable.
 *  - Demo mode (no DATABASE_URL) — auth bypassed entirely.
 */

import { createHmac } from "crypto";
import { NextRequest, NextResponse } from "next/server";
import { getClientById } from "./client-database";

const COOKIE_NAME = "__client_session";
const SESSION_DURATION_S = 30 * 24 * 60 * 60; // 30 days

/** The synthetic client ID used by admin master-key login. */
const ADMIN_CLIENT_ID = "client_admin_owner";

/** True when no real database is configured AND not in production — graceful degradation to demo client. */
function isDemoMode(): boolean {
  return !process.env.DATABASE_URL && process.env.NODE_ENV !== "production";
}

function getSecret(): string {
  const key = process.env.CLIENT_SESSION_SECRET || process.env.ADMIN_API_KEY;
  if (!key) throw new Error("CLIENT_SESSION_SECRET or ADMIN_API_KEY is not set");
  if (!process.env.CLIENT_SESSION_SECRET && process.env.NODE_ENV === "production") {
    console.warn("[AUTH] CLIENT_SESSION_SECRET not set — falling back to ADMIN_API_KEY. Set a dedicated secret for production.");
  }
  return key;
}

function sign(payload: string): string {
  return createHmac("sha256", getSecret())
    .update(payload)
    .digest("base64url");
}

export function createClientSessionToken(clientId: string, email: string): string {
  const exp = Math.floor(Date.now() / 1000) + SESSION_DURATION_S;
  const payload = Buffer.from(JSON.stringify({ clientId, email, exp })).toString("base64url");
  const sig = sign(payload);
  return `${payload}.${sig}`;
}

export function verifyClientSessionToken(token: string): { clientId: string; email: string } | null {
  try {
    const [payload, sig] = token.split(".");
    if (!payload || !sig) return null;

    const expectedSig = sign(payload);
    if (sig.length !== expectedSig.length) return null;
    let mismatch = 0;
    for (let i = 0; i < sig.length; i++) {
      mismatch |= sig.charCodeAt(i) ^ expectedSig.charCodeAt(i);
    }
    if (mismatch !== 0) return null;

    const data = JSON.parse(Buffer.from(payload, "base64url").toString("utf-8"));
    if (typeof data.exp !== "number" || typeof data.clientId !== "string") return null;
    if (data.exp <= Math.floor(Date.now() / 1000)) return null;

    return { clientId: data.clientId, email: data.email };
  } catch {
    return null;
  }
}

/**
 * Verify a parsed session against the database (or trust admin client directly).
 * Returns the clientId if valid, or null if the session should be rejected.
 */
async function verifySession(session: { clientId: string; email: string }): Promise<string | null> {
  // Admin owner — always trusted (no DB row required)
  if (session.clientId === ADMIN_CLIENT_ID) return session.clientId;

  // Regular client — verify row exists and is active
  const clientResult = await getClientById(session.clientId);
  if (clientResult.ok && clientResult.value && clientResult.value.status === "active") {
    return session.clientId;
  }
  return null;
}

/**
 * Verify client authentication from request.
 * Returns the client ID if authenticated, or a 401 response.
 *
 * In demo mode (no DATABASE_URL), always returns demo client —
 * no cookie, no signing secret, no credentials required.
 */
export async function verifyClient(req: NextRequest): Promise<{ clientId: string } | NextResponse> {
  // Demo mode — bypass auth, return demo client directly
  if (isDemoMode()) {
    const { DEMO_CLIENT } = await import("./demo-client");
    return { clientId: DEMO_CLIENT.clientId };
  }

  // Method 1: Session cookie
  const sessionCookie = req.cookies.get(COOKIE_NAME)?.value;
  if (sessionCookie) {
    const session = verifyClientSessionToken(sessionCookie);
    if (session) {
      const clientId = await verifySession(session);
      if (clientId) return { clientId };
    }
  }

  // Method 2: Bearer token (for API access)
  const authHeader = req.headers.get("authorization");
  if (authHeader) {
    const [scheme, token] = authHeader.split(" ");
    if (scheme === "Bearer" && token) {
      const session = verifyClientSessionToken(token);
      if (session) {
        const clientId = await verifySession(session);
        if (clientId) return { clientId };
      }
    }
  }

  return NextResponse.json(
    { success: false, message: "Authentication required." },
    { status: 401 },
  );
}

export const CLIENT_SESSION_COOKIE = COOKIE_NAME;
export const CLIENT_SESSION_MAX_AGE = SESSION_DURATION_S;

/**
 * Lead Price Depreciation Engine
 *
 * Reads pricing tiers and depreciation settings from admin-configurable storage.
 * All values are adjustable via the Admin Portal > Pricing page.
 *
 * Default pricing tiers (buyer exclusivity):
 *   - Exclusive   (1 buyer):    $120
 *   - Semi-exclusive (2 buyers): $100
 *   - Warm shared (3–4 buyers):  $80
 *   - Cool shared (5–6 buyers):  $60
 *
 * Time-based depreciation:
 *   P(t) = basePrice − dropAmount × max(0, ⌊(t − holdDays) / dropInterval⌋)
 *   P(t) = max(floor, P(t))
 */

import { getPricingConfig, type TierConfig, type PricingConfig } from "./pricing-config";

// Re-export types for convenience
export type { TierConfig, PricingConfig };

// =============================================================================
// Public interface (matches the shapes consumers expect)
// =============================================================================

export interface PurchaseTier {
  name: string;
  maxBuyers: number;
  basePrice: number;
}

export interface DepreciationConfig {
  maxPrice: number;
  holdDays: number;
  dropAmount: number;
  dropInterval: number;
  floor: number;
}

// =============================================================================
// Config accessors — always read from the admin-configurable store
// =============================================================================

/** Get all purchase tiers from the current config. */
export function getPurchaseTiers(): PurchaseTier[] {
  const config = getPricingConfig();
  return config.tiers.map((t) => ({
    name: t.name,
    maxBuyers: t.maxBuyers,
    basePrice: t.basePrice,
  }));
}

/** Convenience: PURCHASE_TIERS as a getter for backwards compatibility. */
export const PURCHASE_TIERS = new Proxy([] as PurchaseTier[], {
  get(_target, prop) {
    const tiers = getPurchaseTiers();
    if (prop === "length") return tiers.length;
    if (prop === Symbol.iterator) return tiers[Symbol.iterator].bind(tiers);
    if (prop === "map") return tiers.map.bind(tiers);
    if (prop === "find") return tiers.find.bind(tiers);
    if (prop === "filter") return tiers.filter.bind(tiers);
    if (prop === "every") return tiers.every.bind(tiers);
    if (prop === "forEach") return tiers.forEach.bind(tiers);
    if (typeof prop === "string" && !isNaN(Number(prop))) {
      return tiers[Number(prop)];
    }
    return (tiers as unknown as Record<string | symbol, unknown>)[prop];
  },
});

/** Get the max price ceiling from config. */
export function getMaxPrice(): number {
  return getPricingConfig().maxPrice;
}

/** Get the price floor from config. */
export function getPriceFloor(): number {
  return getPricingConfig().priceFloor;
}

/** Get a tier by its index (clamped to valid range). */
export function getTierByIndex(tierIndex: number): PurchaseTier {
  const tiers = getPurchaseTiers();
  const idx = Math.max(0, Math.min(tierIndex, tiers.length - 1));
  return tiers[idx];
}

/** Build a DepreciationConfig for a given tier name. */
function getDepreciationForTier(tierName: string): DepreciationConfig {
  const config = getPricingConfig();
  const tier = config.tiers.find((t) => t.name === tierName);
  if (tier) {
    return {
      maxPrice: tier.basePrice,
      holdDays: tier.holdDays,
      dropAmount: tier.dropAmount,
      dropInterval: tier.dropInterval,
      floor: config.priceFloor,
    };
  }
  // Fallback to last tier (cheapest)
  const fallback = config.tiers[config.tiers.length - 1];
  return {
    maxPrice: fallback.basePrice,
    holdDays: fallback.holdDays,
    dropAmount: fallback.dropAmount,
    dropInterval: fallback.dropInterval,
    floor: config.priceFloor,
  };
}

// =============================================================================
// Buyer-count status
// =============================================================================

/**
 * Determine buyer status for a lead based on active buyer count.
 */
export function getLeadBuyerStatus(activeBuyerCount: number): {
  currentTier: PurchaseTier;
  soldOut: boolean;
  availableTiers: Array<PurchaseTier & { soldOut: boolean }>;
} {
  const tiers = getPurchaseTiers();
  const availableTiers = tiers.map((tier) => ({
    ...tier,
    soldOut: activeBuyerCount >= tier.maxBuyers,
  }));

  const currentTier = tiers.find((t) => activeBuyerCount < t.maxBuyers)
    || tiers[tiers.length - 1];

  const soldOut = activeBuyerCount >= tiers[tiers.length - 1].maxBuyers;

  return { currentTier, soldOut, availableTiers };
}

// =============================================================================
// Depreciation calculation
// =============================================================================

/**
 * Calculate the depreciated price for a lead at a given age.
 */
export function calculateDepreciatedPrice(
  ageInDays: number,
  config: DepreciationConfig
): number {
  if (ageInDays <= config.holdDays) {
    return config.maxPrice;
  }
  const steps = Math.floor((ageInDays - config.holdDays) / config.dropInterval);
  const price = config.maxPrice - config.dropAmount * steps;
  return Math.max(config.floor, price);
}

/**
 * Get the current price for a specific purchase tier, factoring in lead age.
 */
export function getLeadPrice(
  createdAt: string,
  tierName: string,
): {
  price: number;
  ageInDays: number;
  isHolding: boolean;
  stepsDown: number;
  config: DepreciationConfig;
} {
  const config = getDepreciationForTier(tierName);
  const ageMs = Date.now() - new Date(createdAt).getTime();
  const ageInDays = Math.max(0, ageMs / (1000 * 60 * 60 * 24));

  const price = calculateDepreciatedPrice(ageInDays, config);
  const isHolding = ageInDays <= config.holdDays;
  const stepsDown = isHolding
    ? 0
    : Math.floor((ageInDays - config.holdDays) / config.dropInterval);

  return { price, ageInDays, isHolding, stepsDown, config };
}

/**
 * Get all tier prices for a lead at its current age.
 */
export function getAllTierPrices(
  createdAt: string,
  activeBuyerCount: number
): Array<{
  tier: PurchaseTier;
  price: number;
  soldOut: boolean;
  isHolding: boolean;
  stepsDown: number;
}> {
  const { availableTiers } = getLeadBuyerStatus(activeBuyerCount);

  return availableTiers.map((t) => {
    const { price, isHolding, stepsDown } = getLeadPrice(createdAt, t.name);
    return {
      tier: { name: t.name, maxBuyers: t.maxBuyers, basePrice: t.basePrice },
      price,
      soldOut: t.soldOut,
      isHolding,
      stepsDown,
    };
  });
}

function createToastManager() {
  let toasts = [];
  let listeners = [];

  function subscribe(fn) { listeners.push(fn); return () => { listeners = listeners.filter(l => l !== fn); }; }
  function notify() { listeners.forEach(fn => fn([...toasts])); }

  function addToast(message, type = 'info') {
    const id = Math.random().toString(36).slice(2);
    toasts = [...toasts.slice(-(MAX_TOASTS - 1)), { id, message, type, exiting: false }];
    notify();
    setTimeout(() => {
      toasts = toasts.map(t => t.id === id ? { ...t, exiting: true } : t);
      notify();
    }, TOAST_DURATION);
    setTimeout(() => {
      toasts = toasts.filter(t => t.id !== id);
      notify();
    }, TOAST_DURATION + EXIT_DURATION);
  }

  return { addToast, subscribe, getToasts: () => [...toasts] };
}

