'use strict';

/**
 * Tests for the connective-tissue modules that close the remaining
 * audit roadmap fractures:
 *
 *   F — src/reflector/bridge.js              (envelope-powered Reflector)
 *   G — library.findByRuleId / findByTag     (secondary indexes)
 *   H — src/audit/prior-promoter.js          (substrate → prior loop)
 *   J — src/core/history.js                  (unified timeline)
 *
 * I (hook expansion) is exercised by the existing hooks.test.js suite
 * via the installHooks / prePushScript code paths. We don't re-drive
 * real git hooks here.
 */

const { describe, it, before, after, beforeEach } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const os = require('os');
const path = require('path');

// ─── F: Reflector bridge ────────────────────────────────────────────────────

describe('reflector bridge', () => {
  const bridge = require('../src/reflector/bridge');

  it('reflectorAnalyze returns a full envelope', () => {
    const env = bridge.reflectorAnalyze('function f(a) { return a.sort(); }', 'x.js');
    assert.ok(env.audit);
    assert.ok(env.audit.findings.length > 0);
    assert.equal(env.language, 'javascript');
  });

  it('reflectorScore matches the legacy dimension shape', () => {
    const r = bridge.reflectorScore('const x = 1;', 'x.js');
    assert.equal(typeof r.score, 'number');
    assert.ok(r.dimensions);
    assert.ok(r.findings);
    assert.ok(Array.isArray(r.findings.audit));
    assert.ok(Array.isArray(r.findings.covenant));
  });

  it('reflectorScanDirectory returns one envelope per matching file', () => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'refl-scan-'));
    try {
      fs.writeFileSync(path.join(dir, 'a.js'), 'function a() { return 1; }');
      fs.writeFileSync(path.join(dir, 'b.js'), 'function b() { return 2; }');
      fs.writeFileSync(path.join(dir, 'notes.md'), '# README');
      const envs = bridge.reflectorScanDirectory(dir);
      assert.equal(envs.length, 2); // md file skipped by extension filter
    } finally {
      fs.rmSync(dir, { recursive: true, force: true });
    }
  });

  it('reflectorReport aggregates envelope signals into the legacy shape', () => {
    const envs = [
      bridge.reflectorAnalyze('const x = 1;', 'a.js'),
      bridge.reflectorAnalyze('const y = 2;', 'b.js'),
    ];
    const report = bridge.reflectorReport(envs);
    assert.equal(report.files.length, 2);
    assert.ok(report.aggregate);
    assert.equal(typeof report.aggregate.avgCoherence, 'number');
  });

  it('reflectorHeal wraps the unified pipeline', async () => {
    const r = await bridge.reflectorHeal('function f(a) { return a.sort(); }', { filePath: 'x.js' });
    assert.equal(r.success, true);
    assert.equal(r.level, 'confident');
  });
});

// ─── G: Pattern library indexes ────────────────────────────────────────────

describe('pattern library secondary indexes', () => {
  const { PatternLibrary } = require('../src/patterns/library');
  let dir, lib;

  beforeEach(() => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), 'lib-idx-'));
    lib = new PatternLibrary(dir);
  });
  after(() => {
    if (dir && fs.existsSync(dir)) fs.rmSync(dir, { recursive: true, force: true });
  });

  it('findByRuleId reads the rule: tag convention', () => {
    lib.register({
      name: 'safe-sort',
      code: 'function f(a) { return [...a].sort(); }',
      language: 'javascript',
      tags: ['immutable', 'rule:state-mutation/sort'],
    });
    const matches = lib.findByRuleId('state-mutation/sort');
    assert.equal(matches.length, 1);
    assert.equal(matches[0].name, 'safe-sort');
  });

  it('findByTag is case-insensitive', () => {
    lib.register({
      name: 'guarded',
      code: 'function f(a,b) { return b ? a/b : 0; }',
      language: 'javascript',
      tags: ['Safe-Math'],
    });
    assert.equal(lib.findByTag('safe-math').length, 1);
    assert.equal(lib.findByTag('SAFE-MATH').length, 1);
  });

  it('listTags returns counts sorted descending', () => {
    lib.register({ name: 'a', code: 'const a=1;', language: 'javascript', tags: ['x', 'y'] });
    lib.register({ name: 'b', code: 'const b=2;', language: 'javascript', tags: ['x'] });
    const tags = lib.listTags();
    assert.ok(tags[0].count >= tags[tags.length - 1].count);
    const xEntry = tags.find(t => t.tag === 'x');
    assert.equal(xEntry.count, 2);
  });

  it('invalidates indexes on register so new tags are visible immediately', () => {
    lib.register({ name: 'a', code: 'const a=1;', language: 'javascript', tags: ['first'] });
    assert.equal(lib.findByTag('first').length, 1);
    assert.equal(lib.findByTag('second').length, 0);
    lib.register({ name: 'b', code: 'const b=2;', language: 'javascript', tags: ['second'] });
    assert.equal(lib.findByTag('second').length, 1);
  });
});

// ─── H: Substrate → prior promoter ─────────────────────────────────────────

describe('bayesian prior promoter', () => {
  const { promoteFromSubstrate } = require('../src/audit/prior-promoter');

  it('ignores patterns below the amplitude threshold', () => {
    const oracle = {
      debug: {
        getAll: () => [
          { name: 'weak', amplitude: 0.3, badCode: 'x + 1' },
        ],
      },
    };
    const r = promoteFromSubstrate(oracle, { dryRun: true, amplitudeThreshold: 0.7 });
    assert.equal(r.promoted, 0);
  });

  it('promotes high-amplitude patterns and caps via maxPromote', () => {
    const oracle = {
      debug: {
        getAll: () => [
          { name: 'a', amplitude: 0.95, badCode: 'function a() { return null.x; }' },
          { name: 'b', amplitude: 0.85, badCode: 'function b() { return null.y; }' },
          { name: 'c', amplitude: 0.75, badCode: 'function c() { return null.z; }' },
        ],
      },
    };
    const r = promoteFromSubstrate(oracle, { dryRun: true, maxPromote: 2, amplitudeThreshold: 0.7 });
    assert.equal(r.promoted, 2);
    assert.equal(r.entries.length, 2);
    // Highest-amplitude first
    assert.equal(r.entries[0].name, 'a');
  });

  it('gracefully handles absent debug oracle', () => {
    const r = promoteFromSubstrate({}, { dryRun: true });
    assert.equal(r.considered, 0);
  });

  it('skips patterns with too-short sample code', () => {
    const oracle = {
      debug: {
        getAll: () => [
          { name: 'tiny', amplitude: 0.9, badCode: 'x' },
        ],
      },
    };
    const r = promoteFromSubstrate(oracle, { dryRun: true });
    assert.equal(r.promoted, 0);
    assert.equal(r.skipped, 1);
  });
});

// ─── J: Unified history ────────────────────────────────────────────────────

describe('unified history', () => {
  const { wireHistory, readHistory, summarizeHistory } = require('../src/core/history');
  const { resetEventBus, getEventBus } = require('../src/core/events');
  let tmp;

  beforeEach(() => {
    resetEventBus();
    tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'oracle-hist-'));
  });
  after(() => {
    if (tmp && fs.existsSync(tmp)) fs.rmSync(tmp, { recursive: true, force: true });
  });

  it('captures events emitted on the bus after wireHistory', () => {
    wireHistory(tmp);
    const bus = getEventBus();
    bus.emitSync('audit.finding', { ruleId: 'type/div', file: 'a.js' });
    bus.emitSync('heal.succeeded', { level: 'confident' });

    const all = readHistory(tmp);
    assert.ok(all.length >= 2);
    const types = all.map(e => e.type);
    assert.ok(types.includes('audit.finding'));
    assert.ok(types.includes('heal.succeeded'));
  });

  it('filters by type', () => {
    wireHistory(tmp);
    const bus = getEventBus();
    bus.emitSync('audit.finding', { ruleId: 'a' });
    bus.emitSync('heal.succeeded', { level: 'serf' });
    bus.emitSync('feedback.fix', { ruleId: 'b' });

    const onlyHeal = readHistory(tmp, { type: 'heal.succeeded' });
    assert.equal(onlyHeal.length, 1);
    assert.equal(onlyHeal[0].type, 'heal.succeeded');
  });

  it('filters by type prefix', () => {
    wireHistory(tmp);
    const bus = getEventBus();
    bus.emitSync('heal.attempt', { level: 'confident' });
    bus.emitSync('heal.succeeded', { level: 'confident' });
    bus.emitSync('audit.finding', { ruleId: 'x' });

    const healEvents = readHistory(tmp, { typePrefix: 'heal.' });
    assert.equal(healEvents.length, 2);
    for (const e of healEvents) assert.ok(e.type.startsWith('heal.'));
  });

  it('summarizes events by type', () => {
    wireHistory(tmp);
    const bus = getEventBus();
    bus.emitSync('audit.finding', { ruleId: 'x' });
    bus.emitSync('audit.finding', { ruleId: 'y' });
    bus.emitSync('heal.succeeded', { level: 'confident' });

    const s = summarizeHistory(tmp, { since: '2000-01-01' });
    assert.equal(s.byType['audit.finding'], 2);
    assert.equal(s.byType['heal.succeeded'], 1);
  });

  it('is idempotent — wiring twice does not duplicate entries', () => {
    wireHistory(tmp);
    wireHistory(tmp);
    const bus = getEventBus();
    bus.emitSync('audit.finding', { ruleId: 'single' });
    const all = readHistory(tmp);
    const singles = all.filter(e => e.payload && e.payload.ruleId === 'single');
    assert.equal(singles.length, 1);
  });
});

patterns.code:
/**
 * Lead outcomes — the close-rate feedback loop, recorded through retro-causality.
 *
 * When a purchased lead resolves (the agent closed a policy, or didn't), we
 * record that as the lead's *future*. Each outcome is stored in the field's
 * legacy record store as one record that is simultaneously:
 *   1. the analytics row (close-rate by coherency), and
 *   2. a retro-causal resolved-ledger carrier — meta.ledger (observed_start →
 *      observed_end) + meta.resolved — which is exactly what the recall path's
 *      computeRetrocausalAlignment consumes. Feeding it these ledgers is what
 *      makes the (previously inert) "future pulls present" recall come alive.
 *
 * Requires REMEMBRANCE_FIELD_URL (the field is the store). Best-effort: a write
 * returns an error rather than throwing when the field is unreachable.
 */

import {
  storeRecord,
  listRecords,
  recordResolvedOutcome,
  recordBenefit,
  recordCost,
  type ResolvedOutcome,
} from "./valor/remembrance-bridge";

const OUTCOME_TAG = "lead-outcome";

export type LeadOutcomeKind = "won" | "lost";

export interface LeadOutcomeInput {
  leadId: string;
  leadCreatedAt: string;
  coherency: number; // 0–1
  outcome: LeadOutcomeKind;
  premiumCents?: number; // policy premium when won (optional)
  clientId?: string;
}

const outcomeRecordId = (leadId: string): string => "outcome:" + leadId;

/** Coherency band label used to bucket outcomes for the close-rate report. */
export function coherencyBucket(coherency: number): string {
  const c = Math.max(0, Math.min(1, coherency));
  if (c >= 0.95) return "0.95+ transcendence";
  if (c >= 0.85) return "0.85–0.95 synergy";
  if (c >= 0.70) return "0.70–0.85 foundation";
  if (c >= 0.60) return "0.60–0.70 gate";
  return "<0.60 below-gate";
}

const BUCKET_ORDER = [
  "0.95+ transcendence",
  "0.85–0.95 synergy",
  "0.70–0.85 foundation",
  "0.60–0.70 gate",
  "<0.60 below-gate",
];

/** Record a resolved lead outcome (upsert-by-lead, so re-marking corrects). */
export async function recordLeadOutcome(input: LeadOutcomeInput): Promise<{ ok: boolean; error?: string }> {
  const resolvedAt = new Date().toISOString();
  const resolution: ResolvedOutcome = {
    outcome: input.outcome,
    resolvedCoherence: Math.max(0, Math.min(1, input.coherency)),
    resolvedAt,
  };

  const stored = await storeRecord({
    id: outcomeRecordId(input.leadId),
    name: outcomeRecordId(input.leadId),
    content: JSON.stringify({
      leadId: input.leadId,
      coherency: resolution.resolvedCoherence,
      outcome: input.outcome,
      premiumCents: input.premiumCents ?? null,
      clientId: input.clientId ?? null,
      resolvedAt,
    }),
    tags: [OUTCOME_TAG, input.outcome, coherencyBucket(resolution.resolvedCoherence)],
    meta: {
      resolved: resolution,
      ledger: { observed_start: input.leadCreatedAt, observed_end: resolvedAt, cadence: "variable" },
    },
  });
  if (!stored || !stored.ok) {
    return { ok: false, error: "Field store unavailable — set REMEMBRANCE_FIELD_URL and ensure the field is reachable." };
  }

  // Best-effort: stamp the lead's OWN substrate record with the same resolution,
  // so when leads live on the substrate a won lead becomes a resolved anchor the
  // retro-causal recall pulls future similar leads toward.
  await recordResolvedOutcome("lead:" + input.leadId, resolution, input.leadCreatedAt).catch(() => ({ ok: false }));

  // Wire the outcome into the Living Remembrance Engine — the external truth
  // that closes the loop. A won lead is a coherency-positive event (the grade,
  // validated by a real close); a lost one is an entropy cost. Mirrors the
  // lead-ledger admit/reject contributions; fire-and-forget.
  if (input.outcome === "won") {
    void recordBenefit(resolution.resolvedCoherence, "valor:lead-outcome:won", 1).catch(() => {});
  } else {
    void recordCost(1, "valor:lead-outcome", "lost").catch(() => {});
  }

  return { ok: true };
}

export interface CoherencyOutcomeBucket {
  bucket: string;
  won: number;
  lost: number;
  total: number;
  closeRate: number; // won / total, 0–1
  avgPremiumCents: number | null;
}

/** Aggregate recorded outcomes into close-rate by coherency band — the proof. */
export async function getCloseRateByCoherency(): Promise<{
  buckets: CoherencyOutcomeBucket[];
  totalWon: number;
  totalLost: number;
}> {
  const { records } = await listRecords({ tags: [OUTCOME_TAG], limit: 500 });
  const byBucket = new Map<string, { won: number; lost: number; premiumSum: number; premiumN: number }>();
  let totalWon = 0;
  let totalLost = 0;

  for (const r of records) {
    let data: { coherency?: number; outcome?: string; premiumCents?: number | null };
    try { data = JSON.parse(r.content); } catch { continue; }
    const bucket = coherencyBucket(typeof data.coherency === "number" ? data.coherency : 0);
    const slot = byBucket.get(bucket) ?? { won: 0, lost: 0, premiumSum: 0, premiumN: 0 };
    if (data.outcome === "won") {
      slot.won++;
      totalWon++;
      if (typeof data.premiumCents === "number") { slot.premiumSum += data.premiumCents; slot.premiumN++; }
    } else if (data.outcome === "lost") {
      slot.lost++;
      totalLost++;
    }
    byBucket.set(bucket, slot);
  }

  const buckets: CoherencyOutcomeBucket[] = BUCKET_ORDER
    .filter((b) => byBucket.has(b))
    .map((b) => {
      const s = byBucket.get(b)!;
      const total = s.won + s.lost;
      return {
        bucket: b,
        won: s.won,
        lost: s.lost,
        total,
        closeRate: total > 0 ? s.won / total : 0,
        avgPremiumCents: s.premiumN > 0 ? Math.round(s.premiumSum / s.premiumN) : null,
      };
    });

  return { buckets, totalWon, totalLost };
}

/**
 * Lead Distribution Engine
 *
 * Matches incoming leads to eligible client buyers based on:
 *   - Client filters (state, coverage, veteran, min score)
 *   - Cap enforcement (daily + monthly limits)
 *   - Distribution mode (exclusive, shared, round-robin)
 *
 * Called after a lead is persisted, scored, and broadcast.
 */

import {
  getFilteredClients,
  getClientFilters,
  getClientDailyPurchaseCount,
  getClientMonthlyPurchaseCount,
  createPurchase,
  generatePurchaseId,
} from "./client-database";
import type { ClientRecord, LeadPurchase } from "./client-database";
import type { LeadRecord } from "./database";
import type { LeadScore } from "./lead-scoring";
import { PURCHASE_TIERS } from "./lead-depreciation";

export interface DistributionResult {
  leadId: string;
  distributed: boolean;
  purchases: Array<{ clientId: string; purchaseId: string; exclusive: boolean }>;
  skipped: Array<{ clientId: string; reason: string }>;
}

// Round-robin index tracked in-memory (resets on restart — acceptable for distribution fairness)
let roundRobinIndex = 0;

/**
 * Distribute a lead to matching clients.
 *
 * This is non-blocking — called fire-and-forget after lead creation.
 */
export async function distributeLead(
  lead: LeadRecord,
  score: LeadScore
): Promise<DistributionResult> {
  const result: DistributionResult = {
    leadId: lead.leadId,
    distributed: false,
    purchases: [],
    skipped: [],
  };

  // Get all active clients
  const clientsResult = await getFilteredClients({ status: "active", limit: 200 });
  if (!clientsResult.ok || clientsResult.value.clients.length === 0) {
    return result;
  }

  const allClients = clientsResult.value.clients;

  // Filter clients by match criteria
  const eligible: Array<{ client: ClientRecord; exclusive: boolean }> = [];

  for (const client of allClients) {
    const matchResult = await matchClientToLead(client, lead, score);
    if (matchResult.match) {
      eligible.push({ client, exclusive: matchResult.exclusive });
    } else {
      result.skipped.push({ clientId: client.clientId, reason: matchResult.reason });
    }
  }

  if (eligible.length === 0) return result;

  // Check for exclusive buyers first — they get priority
  const exclusiveBuyers = eligible.filter((e) => e.exclusive);
  if (exclusiveBuyers.length > 0) {
    // Round-robin among exclusive buyers
    const buyer = exclusiveBuyers[roundRobinIndex % exclusiveBuyers.length];
    roundRobinIndex++;

    const purchaseResult = await executePurchase(buyer.client, lead, true);
    if (purchaseResult) {
      result.purchases.push(purchaseResult);
      result.distributed = true;
    }
    return result;
  }

  // Shared distribution — send to all eligible (up to 3 buyers per lead)
  const MAX_SHARED_BUYERS = 3;
  const sharedBuyers = eligible.slice(0, MAX_SHARED_BUYERS);

  for (const { client } of sharedBuyers) {
    const purchaseResult = await executePurchase(client, lead, false);
    if (purchaseResult) {
      result.purchases.push(purchaseResult);
      result.distributed = true;
    }
  }

  return result;
}

async function matchClientToLead(
  client: ClientRecord,
  lead: LeadRecord,
  score: LeadScore
): Promise<{ match: boolean; exclusive: boolean; reason: string }> {
  // Check minimum score
  if (score.total < client.minScore) {
    return { match: false, exclusive: false, reason: `Score ${score.total} below minimum ${client.minScore}` };
  }

  // Check state licenses
  const licenses: string[] = JSON.parse(client.stateLicenses || "[]");
  if (licenses.length > 0 && !licenses.includes(lead.state)) {
    return { match: false, exclusive: false, reason: `Not licensed in ${lead.state}` };
  }

  // Check coverage types
  const coverageTypes: string[] = JSON.parse(client.coverageTypes || "[]");
  if (coverageTypes.length > 0 && !coverageTypes.includes(lead.coverageInterest)) {
    return { match: false, exclusive: false, reason: `Coverage ${lead.coverageInterest} not wanted` };
  }

  // Check daily cap
  const dailyResult = await getClientDailyPurchaseCount(client.clientId);
  if (dailyResult.ok && dailyResult.value >= client.dailyCap) {
    return { match: false, exclusive: false, reason: "Daily cap reached" };
  }

  // Check monthly cap
  const monthlyResult = await getClientMonthlyPurchaseCount(client.clientId);
  if (monthlyResult.ok && monthlyResult.value >= client.monthlyCap) {
    return { match: false, exclusive: false, reason: "Monthly cap reached" };
  }

  // Check client-specific filters
  const filtersResult = await getClientFilters(client.clientId);
  let exclusive = false;

  if (filtersResult.ok && filtersResult.value) {
    const filters = filtersResult.value;

    // State filter
    const filterStates: string[] = JSON.parse(filters.states || "[]");
    if (filterStates.length > 0 && !filterStates.includes(lead.state)) {
      return { match: false, exclusive: false, reason: `State ${lead.state} not in filter` };
    }

    // Coverage filter
    const filterCoverage: string[] = JSON.parse(filters.coverageTypes || "[]");
    if (filterCoverage.length > 0 && !filterCoverage.includes(lead.coverageInterest)) {
      return { match: false, exclusive: false, reason: `Coverage not in filter` };
    }

    // Veteran-only filter
    if (filters.veteranOnly && lead.veteranStatus !== "veteran") {
      return { match: false, exclusive: false, reason: "Veteran-only filter" };
    }

    // Min score filter (may be more restrictive than client-level)
    if (score.total < filters.minScore) {
      return { match: false, exclusive: false, reason: `Score below filter minimum ${filters.minScore}` };
    }

    // Lead age filter
    const ageHours = (Date.now() - new Date(lead.createdAt).getTime()) / (1000 * 60 * 60);
    if (ageHours > filters.maxLeadAge) {
      return { match: false, exclusive: false, reason: "Lead too old" };
    }

    exclusive = filters.distributionMode === "exclusive";
  }

  return { match: true, exclusive, reason: "" };
}

async function executePurchase(
  client: ClientRecord,
  lead: LeadRecord,
  exclusive: boolean
): Promise<{ clientId: string; purchaseId: string; exclusive: boolean } | null> {
  // Use buyer-count tier pricing: Exclusive = $120, Cool Shared = $60
  const tier = exclusive ? PURCHASE_TIERS[0] : PURCHASE_TIERS[PURCHASE_TIERS.length - 1];
  const price = tier.basePrice;

  // Create return deadline (72 hours from now)
  const returnDeadline = new Date(Date.now() + 72 * 60 * 60 * 1000).toISOString();

  const purchase: LeadPurchase = {
    purchaseId: generatePurchaseId(),
    leadId: lead.leadId,
    clientId: client.clientId,
    pricePaid: price,
    purchasedAt: new Date().toISOString(),
    status: "delivered",
    exclusive,
    returnReason: "",
    returnDeadline,
  };

  const result = await createPurchase(purchase);
  if (!result.ok) return null;

  return { clientId: client.clientId, purchaseId: purchase.purchaseId, exclusive };
}

/**
 * Conversion and Analytics Tracking
 *
 * Privacy-first analytics:
 *  - Checks cookie consent before firing any tracking events
 *  - Supports configurable conversion pixels via env vars
 *  - Tracks: page views, form step progress, conversions
 *  - Extensible: add Google Ads, Facebook Pixel, etc. via gtag/fbq globals
 *
 * No third-party scripts are loaded by default — this provides
 * the event dispatch layer. External pixels are fired only when
 * their global (gtag, fbq) is present on the window.
 */

/** Check if user has accepted analytics cookies (stored in localStorage by cookie-consent component) */
function hasAnalyticsConsent(): boolean {
  if (typeof window === "undefined") return false;
  try {
    const stored = localStorage.getItem("dc_cookie_consent");
    if (!stored) return false;
    const parsed = JSON.parse(stored);
    return parsed.choice === "accepted";
  } catch {
    return false;
  }
}

/* eslint-disable @typescript-eslint/no-explicit-any */
/** Safe access to window.gtag (Google Ads / GA4) */
function gtag(...args: unknown[]): void {
  if (typeof window !== "undefined") {
    const w = window as any;
    if (typeof w.gtag === "function") w.gtag(...args);
  }
}

/** Safe access to window.fbq (Meta/Facebook Pixel) */
function fbq(...args: unknown[]): void {
  if (typeof window !== "undefined") {
    const w = window as any;
    if (typeof w.fbq === "function") w.fbq(...args);
  }
}
/* eslint-enable @typescript-eslint/no-explicit-any */

export interface ConversionEvent {
  event: string;
  category?: string;
  label?: string;
  value?: number;
  metadata?: Record<string, string | number | boolean>;
}

/**
 * Track a custom analytics event.
 * Respects cookie consent — events are silently dropped if consent is not given.
 */
export function trackEvent(event: ConversionEvent): void {
  if (!hasAnalyticsConsent()) return;

  // Google Analytics / Google Ads
  gtag("event", event.event, {
    event_category: event.category,
    event_label: event.label,
    value: event.value,
    ...event.metadata,
  });

  // Facebook Pixel
  fbq("trackCustom", event.event, {
    category: event.category,
    label: event.label,
    value: event.value,
    ...event.metadata,
  });
}

/**
 * Track a lead form conversion.
 * Fires standard conversion events on all configured pixels.
 */
export function trackConversion(leadId: string, coverageType: string, state: string): void {
  if (!hasAnalyticsConsent()) return;

  // Google Ads conversion
  gtag("event", "conversion", {
    send_to: process.env.NEXT_PUBLIC_GOOGLE_ADS_CONVERSION_ID || "",
    event_category: "lead",
    event_label: coverageType,
    value: 1,
  });

  // Facebook Pixel Lead event
  fbq("track", "Lead", {
    content_name: coverageType,
    content_category: "life_insurance",
    status: "submitted",
  });

  // Generic event for any other analytics
  trackEvent({
    event: "lead_submitted",
    category: "conversion",
    label: coverageType,
    value: 1,
    metadata: { leadId, state },
  });
}

/**
 * Track form step progression.
 * Useful for funnel analysis — see where users drop off.
 */
export function trackFormStep(step: number, stepName: string): void {
  trackEvent({
    event: "form_step",
    category: "engagement",
    label: stepName,
    value: step,
  });
}

/**
 * Track page view (for SPA navigation).
 */
export function trackPageView(path: string, title?: string): void {
  if (!hasAnalyticsConsent()) return;

  gtag("event", "page_view", {
    page_path: path,
    page_title: title,
  });

  fbq("track", "PageView");
}

