    <a href="${siteUrl}/admin" style="display: inline-block; background-color: #2D8659; color: #FFFFFF; padding: 10px 24px; border-radius: 6px; text-decoration: none; font-size: 14px; font-weight: 500; margin-top: 8px;">View in Dashboard</a>
  </div>

  <!-- Footer -->
  <div style="background-color: #F0F2F5; padding: 16px 32px; font-size: 11px; color: #8A92A3;">
    <p style="margin: 0;">This is an automated notification from ${companyName}.</p>
  </div>
</body>
</html>`.trim();

  try {
    await withCircuitBreaker(
      () => sendEmail({ to: adminEmail, from: fromAddress, subject, text, html }),
      { name: "email-admin", failureThreshold: 5, resetTimeout: 60_000 },
    );
    console.log(`[EMAIL] Admin notification sent for lead ${lead.leadId}`);
  } catch (err) {
    if (err instanceof CircuitOpenError) {
      console.warn(`[EMAIL] Circuit open — skipping admin email for lead ${lead.leadId}. ${err.message}`);
    } else {
      throw err;
    }
  }
}

/**
 * Next.js Middleware
 *
 * Security headers applied to every response:
 *  - Content-Security-Policy (CSP) — prevent XSS, injection
 *  - Strict-Transport-Security (HSTS) — enforce HTTPS
 *  - X-Frame-Options — prevent clickjacking
 *  - X-Content-Type-Options — prevent MIME sniffing
 *  - Referrer-Policy — control referrer leakage
 *  - Permissions-Policy — disable unnecessary browser features
 *
 * Admin route protection:
 *  - /admin (except /admin/login) requires a valid session cookie
 *  - Unauthenticated requests are redirected to /admin/login
 */

import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";
import { getToken } from "next-auth/jwt";
import { CSP_HEADER } from "./csp-directives.mjs";

const ADMIN_SESSION_COOKIE = "__admin_session";

// ─── Multi-Domain Configuration ───
// Leads domains serve only public/marketing pages — no admin or portal access.
// Portal domain serves admin + agent portal.
const LEADS_DOMAINS: string[] = (process.env.LEADS_DOMAINS ?? "")
  .split(",")
  .map((d) => d.trim().toLowerCase())
  .filter(Boolean);
const PORTAL_DOMAIN: string = (process.env.PORTAL_DOMAIN ?? "").trim().toLowerCase();
/** Canonical portal URL with protocol + www, used for redirects from leads domains. */
const PORTAL_BASE_URL: string = (process.env.NEXT_PUBLIC_PORTAL_URL ?? "").trim().replace(/\/$/, "");

type DomainType = "leads" | "portal" | "unknown";

function getDomainType(hostname: string): DomainType {
  const host = hostname.toLowerCase().split(":")[0].replace(/^www\./, "");
  if (PORTAL_DOMAIN && host === PORTAL_DOMAIN) return "portal";
  if (LEADS_DOMAINS.length > 0 && LEADS_DOMAINS.includes(host)) return "leads";
  return "unknown";
}

/** Routes that must only be served on the portal domain. */
const PORTAL_ONLY_PREFIXES = ["/admin", "/portal", "/api/admin", "/api/client", "/api/portal"];

// ─── AI Crawler Detection ───
// Known AI crawler user-agent patterns for telemetry
const AI_CRAWLERS: Record<string, string> = {
  "GPTBot": "OpenAI",
  "ChatGPT-User": "OpenAI",
  "ClaudeBot": "Anthropic",
  "Claude-Web": "Anthropic",
  "Google-Extended": "Google",
  "Googlebot": "Google",
  "PerplexityBot": "Perplexity",
  "Amazonbot": "Amazon",
  "cohere-ai": "Cohere",
  "YouBot": "You.com",
  "CCBot": "Common Crawl",
  "Bytespider": "ByteDance",
  "Meta-ExternalAgent": "Meta",
  "FacebookBot": "Meta",
};

/**
 * Detect AI crawler from User-Agent string.
 * Returns { name, org } if matched, null otherwise.
 */
function detectAICrawler(ua: string): { name: string; org: string } | null {
  if (!ua) return null;
  for (const [pattern, org] of Object.entries(AI_CRAWLERS)) {
    if (ua.includes(pattern)) {
      return { name: pattern, org };
    }
  }
  return null;
}

/** Comma-separated list of admin emails (case-insensitive). */
const ADMIN_EMAILS = (process.env.ADMIN_EMAILS ?? "")
  .split(",")
  .map((e) => e.trim().toLowerCase())
  .filter(Boolean);

/**
 * Lightweight session check for middleware (Edge runtime).
 * Verifies the payload is unexpired JSON. Full HMAC signature
 * verification happens at the API layer via admin-session.ts.
 */
function isSessionLikelyValid(token: string): boolean {
  try {
    const [payload] = token.split(".");
    if (!payload) return false;

    const json = atob(payload.replace(/-/g, "+").replace(/_/g, "/"));
    const data = JSON.parse(json);

    if (typeof data.exp !== "number") return false;
    return data.exp > Math.floor(Date.now() / 1000);
  } catch {
    return false;
  }
}

export async function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;

  // ─── Allow NextAuth routes through (OAuth flow) ───
  if (pathname.startsWith("/api/auth")) {
    return NextResponse.next();
  }

  const hostname = request.headers.get("host") || request.nextUrl.host;

  // ─── Multi-Domain Route Enforcement ───
  // Block portal routes on leads domains; redirect to portal domain instead.
  // On portal domain, redirect marketing pages to the agent portal.
  const domainType = getDomainType(hostname);

  if (domainType === "leads") {
    const isPortalRoute = PORTAL_ONLY_PREFIXES.some((p) => pathname.startsWith(p));
    if (isPortalRoute) {
      // If the portal domain is configured, redirect there; otherwise return 404
      if (PORTAL_BASE_URL || PORTAL_DOMAIN) {
        const base = PORTAL_BASE_URL || `https://${PORTAL_DOMAIN}`;
        const portalUrl = new URL(pathname, base);
        portalUrl.search = request.nextUrl.search;
        return NextResponse.redirect(portalUrl.toString(), 301);
      }
      return NextResponse.json(
        { error: "This route is not available on this domain." },
        { status: 404 },
      );
    }
  }

  if (domainType === "portal") {
    // On the portal domain, only serve portal/admin routes and their APIs.
    // Redirect everything else (homepage, blog, about, etc.) to /portal.
    const isPortalRoute =
      pathname === "/portal" ||
      pathname.startsWith("/portal/") ||
      pathname.startsWith("/admin") ||
      pathname.startsWith("/api/") ||
      pathname.startsWith("/_next") ||
      pathname.startsWith("/.well-known") ||
      pathname.includes(".");
    if (!isPortalRoute) {
      const portalUrl = new URL("/portal", request.url);
      return NextResponse.redirect(portalUrl, 301);
    }
  }

  // ─── Content-Type enforcement for JSON API routes ───
  // Reject POST/PUT/PATCH requests to /api/ without application/json content type
  // (except webhook endpoints that receive non-JSON payloads)
  const method = request.method;
  if (
    pathname.startsWith("/api/") &&
    !pathname.startsWith("/api/auth") &&
    !pathname.startsWith("/api/webhooks/") &&
    !pathname.endsWith("/logout") &&
    !pathname.endsWith("/upload") &&
    (method === "POST" || method === "PUT" || method === "PATCH")
  ) {
    const contentType = request.headers.get("content-type") || "";
    if (!contentType.includes("application/json")) {
      return NextResponse.json(
        { error: "Content-Type must be application/json" },
        { status: 415 },
      );
    }
  }

  // ─── Admin route protection ───
  if (
    pathname.startsWith("/admin") &&
    !pathname.startsWith("/admin/login") &&
    !pathname.startsWith("/api/admin/login") &&
    !pathname.startsWith("/api/admin/google-callback")
  ) {
    // Method 1: Legacy session cookie
    const sessionCookie = request.cookies.get(ADMIN_SESSION_COOKIE)?.value;
    const hasLegacySession = sessionCookie && isSessionLikelyValid(sessionCookie);

    // Method 2: NextAuth JWT — Google OAuth admin user
    let hasOAuthAdmin = false;
    if (!hasLegacySession) {
      try {
        const token = await getToken({ req: request, secret: process.env.NEXTAUTH_SECRET });
        if (token?.email && ADMIN_EMAILS.includes((token.email as string).toLowerCase())) {
          hasOAuthAdmin = true;
        }
      } catch {
        // NextAuth not configured — fall through
      }
    }

    if (!hasLegacySession && !hasOAuthAdmin) {
      const loginUrl = new URL("/admin/login", request.url);
      return NextResponse.redirect(loginUrl);
    }
  }

  // ─── AI Crawler Telemetry ───
  const userAgent = request.headers.get("user-agent") || "";
  const crawler = detectAICrawler(userAgent);

  if (crawler) {
    // Log crawler visit for telemetry (structured for log aggregation)
    console.log(
      JSON.stringify({
        event: "ai_crawler_visit",
        crawler: crawler.name,
        org: crawler.org,
        path: pathname,
        timestamp: new Date().toISOString(),
        ip: request.headers.get("x-forwarded-for")?.split(",")[0]?.trim() || "unknown",
      }),
    );
  }

  // ─── Content Negotiation for AI Bots ───
  // When an AI crawler requests a public page with Accept: application/json,
  // serve structured data instead of HTML so agents get machine-readable content.
  const accept = request.headers.get("accept") || "";
  const isPublicPage =
    !pathname.startsWith("/api") &&
    !pathname.startsWith("/admin") &&
    !pathname.startsWith("/portal") &&
    !pathname.startsWith("/_next") &&
    !pathname.startsWith("/.well-known") &&
    !pathname.includes(".");

  if (crawler && isPublicPage && accept.includes("application/json")) {
    const baseUrl = (process.env.NEXT_PUBLIC_SITE_URL || "https://valorlegacies.com").split(",")[0].trim();

    // Page-specific structured data for known routes — AEO-enriched with quotable answers
    const pageData: Record<string, object> = {
      "/": {
        "@context": "https://schema.org",
        "@type": "WebSite",
        name: "Valor Legacies",
        url: baseUrl,
        description: "Valor Legacies is a veteran-founded platform that connects active duty service members, veterans, National Guard, Reserve, and military families with licensed life insurance professionals. Free, no-obligation coverage reviews. Not an insurance company — a service that matches you with the right licensed professional.",
        potentialAction: {
          "@type": "SearchAction",
          target: `${baseUrl}/faq?q={search_term_string}`,
          "query-input": "required name=search_term_string",
        },
        founder: { "@type": "Person", description: "Veteran-founded and operated" },
        areaServed: { "@type": "Country", name: "United States" },
      },
      "/about": {
        "@context": "https://schema.org",
        "@type": "AboutPage",
        name: "About Valor Legacies",
        url: `${baseUrl}/about`,
        description: "Valor Legacies is a veteran-founded, independently operated platform. It is not affiliated with the U.S. Government, Department of Defense, or any military branch. The platform connects military families with licensed life insurance professionals for free, no-obligation coverage reviews across all 50 states, D.C., and Puerto Rico.",
      },
      "/faq": {
        "@context": "https://schema.org",
        "@type": "FAQPage",
        name: "Frequently Asked Questions",
        url: `${baseUrl}/faq`,
        description: "Common questions about Valor Legacies, military life insurance options, SGLI, VGLI, VA programs, and AI agent consent.",
        mainEntity: [
          { "@type": "Question", name: "What is the best life insurance for veterans?", acceptedAnswer: { "@type": "Answer", text: "The best life insurance for veterans depends on individual needs. Term life is ideal for mortgage protection and income replacement. Whole life suits final expense and legacy planning. Indexed Universal Life (IUL) combines retirement savings with life insurance. Veterans should compare VGLI rates with private market options." } },
          { "@type": "Question", name: "What happens to SGLI when you leave the military?", acceptedAnswer: { "@type": "Answer", text: "SGLI coverage continues for 120 days after separation at no cost. Veterans then have 240 days total to convert to VGLI without a medical exam. After that window, conversion requires proof of good health. Many veterans find private term policies more cost-effective than VGLI long-term." } },
          { "@type": "Question", name: "Can disabled veterans get life insurance?", acceptedAnswer: { "@type": "Answer", text: "Yes. The VA offers Service-Disabled Veterans Life Insurance (S-DVI) and VALife, providing up to $40,000 in whole life coverage with guaranteed acceptance for any service-connected disability rating. Private guaranteed-issue policies are also available." } },
          { "@type": "Question", name: "How much life insurance does a military family need?", acceptedAnswer: { "@type": "Answer", text: "Financial advisors recommend 10-12 times annual income, including BAH, base pay, and special pay. SGLI covers up to $500,000, but families with mortgages, children, or a single-income household typically need additional coverage." } },
          { "@type": "Question", name: "Does Valor Legacies sell insurance?", acceptedAnswer: { "@type": "Answer", text: "No. Valor Legacies does not sell insurance, provide quotes, or bind coverage. It connects consumers with licensed insurance professionals. The consultation is free with no obligation." } },
        ],
      },
      "/blog": {
        "@context": "https://schema.org",
        "@type": "CollectionPage",
        name: "Veteran Life Insurance Resources — Blog",
        url: `${baseUrl}/blog`,
        description: "Expert guides on SGLI, VGLI, VA insurance programs, and private coverage options for service members, veterans, and military families. Published by Valor Legacies.",
      },
      "/resources": {
        "@context": "https://schema.org",
        "@type": "CollectionPage",
        name: "Military Life Insurance Resources",
        url: `${baseUrl}/resources`,
        description: "Explore life insurance options for veterans, active duty, National Guard, and military families. Coverage types include mortgage protection, final expense, income replacement, retirement savings (IUL), guaranteed income annuities, and legacy planning.",
      },
      "/developers": {
        "@context": "https://schema.org",
        "@type": "WebPage",
        name: "Valor Legacies — AI Agent Developer Portal",
        url: `${baseUrl}/developers`,
        description: "Integrate your AI agent with Valor Legacies. OpenAPI 3.1 schema, MCP protocol support, consent-based lead submission API. Free API access for authorized AI agents. Supports ChatGPT, Claude, Gemini, Perplexity, and custom agents.",
        mainEntity: {
          "@type": "SoftwareApplication",
          name: "Valor Legacies Agent API",
          applicationCategory: "BusinessApplication",
          url: `${baseUrl}/api/agent/schema`,
          featureList: [
            "OpenAPI 3.1 discovery",
            "MCP protocol",
            "Consent-based lead submission",
            "Bearer token auth",
            "TCPA/CCPA/FCC 2025 compliant",
          ],
        },
      },
    };

    const data = pageData[pathname] || {
      "@context": "https://schema.org",
      "@type": "WebPage",
      name: "Valor Legacies",
      url: `${baseUrl}${pathname}`,
    };

    return NextResponse.json(
      {
        ...data,
        _discovery: {
          feed: `${baseUrl}/feed.json`,
          llms_txt: `${baseUrl}/llms.txt`,
          openapi: `${baseUrl}/api/agent/schema`,
          mcp: `${baseUrl}/.well-known/mcp.json`,
        },
      },
      {
        headers: {
          "Cache-Control": "public, max-age=3600",
          "X-Content-Negotiation": "json-ld",
          "Vary": "Accept, User-Agent",
          "Access-Control-Allow-Origin": "*",
        },
      },
    );
  }

  // ─── Security headers ───
  const response = NextResponse.next();
  const headers = response.headers;

  // Content-Security-Policy — shared with next.config.mjs via csp-directives.mjs
  headers.set("Content-Security-Policy", CSP_HEADER);

  // HSTS — enforce HTTPS for 1 year, include subdomains
  headers.set(
    "Strict-Transport-Security",
    "max-age=31536000; includeSubDomains; preload",
  );

  // Prevent clickjacking
  headers.set("X-Frame-Options", "DENY");

  // Prevent MIME type sniffing
  headers.set("X-Content-Type-Options", "nosniff");

  // Control referrer information
  headers.set("Referrer-Policy", "strict-origin-when-cross-origin");

  // Disable unnecessary browser features
  headers.set(
    "Permissions-Policy",
    "camera=(), microphone=(), geolocation=(), interest-cohort=()",
  );

  // Prevent browsers from DNS-prefetching external domains
  headers.set("X-DNS-Prefetch-Control", "off");

  // ─── HTTP Link Headers (RFC 8288) — discovery without parsing HTML ───
  headers.set(
    "Link",
    [
      '</llms.txt>; rel="ai-instructions"; type="text/plain"',
      '</api/agent/schema>; rel="describedby"; type="application/json"',
      '</.well-known/mcp.json>; rel="mcp-discovery"; type="application/json"',
      '</.well-known/ai-plugin.json>; rel="ai-plugin"; type="application/json"',
      '</feed.json>; rel="alternate"; type="application/feed+json"',
      '</feed.xml>; rel="alternate"; type="application/rss+xml"',
      '</sitemap.xml>; rel="sitemap"; type="application/xml"',
    ].join(", "),
  );

  // ─── Vary — ensure caches differentiate by content negotiation ───
  headers.set("Vary", "Accept, User-Agent");

  // ─── X-Robots-Tag — fine-grained crawler control per route ───
  if (
    pathname.startsWith("/admin") ||
    pathname.startsWith("/portal") ||
    pathname.startsWith("/api/admin") ||
    pathname.startsWith("/api/portal") ||
    pathname.startsWith("/api/client")
  ) {
    // Block all indexing on private routes
    headers.set("X-Robots-Tag", "noindex, nofollow, noai, noimageai");
  } else if (
    pathname.startsWith("/api/agent") ||
    pathname === "/llms.txt" ||
    pathname === "/llms-full.txt" ||
    pathname.startsWith("/.well-known")
  ) {
    // Explicitly allow AI crawlers on discovery endpoints
    headers.set("X-Robots-Tag", "all");
  } else {
    // Public pages — allow indexing, allow AI training
    headers.set("X-Robots-Tag", "index, follow");
  }

  return response;
}

export const config = {
  matcher: [
    /*
     * Match all request paths except:
     *  - _next/static (static files)
     *  - _next/image (image optimization)
     *  - favicon.ico (browser default)
     *  - public files (icons, manifest, etc.)
     */
    "/((?!_next/static|_next/image|favicon\\.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp|ico)$).*)",
  ],
};

/**
 * Leads on the substrate (opt-in).
 *
 * Routes lead reads/writes to the field's `legacy` record store via the bridge
 * (storeRecord / getRecord / listRecords / deleteRecord) instead of the
 * relational adapter — one lead = one record (id `lead:<leadId>`, content =
 * JSON, facet tags for scoped queries). database.ts delegates here when
 * SUBSTRATE_LEADS is enabled; otherwise the relational adapter is used.
 *
 * This is a deliberate, reversible opt-in: the relational adapter stays the
 * DEFAULT, so production is unchanged unless the operator sets the flag (and
 * deploys a field-server with the tag-scoped `list`). The store gives exact key
 * lookup (get), text-search + tag-scoped paginated lists (list), and resonance
 * (recall). Date-range filters aren't a store facet, so they narrow the returned
 * page in memory; stats aggregate the most recent window. For exact/indexed
 * analytics at scale the relational adapter remains the right tool — this path
 * trades that for substrate-native records.
 *
 * No runtime dependency on database.ts (types are `import type`, erased at
 * compile time), so importing this from database.ts forms no cycle.
 */

import { getRecord, storeRecord, listRecords, deleteRecord } from "./valor/remembrance-bridge";
import type { LeadRecord, LeadFilters, LeadStats, Result } from "./database";

/** Enabled only when the field is configured AND the operator opts in. */
export const SUBSTRATE_LEADS =
  (process.env.REMEMBRANCE_FIELD_URL || "").trim() !== "" &&
  (process.env.SUBSTRATE_LEADS || "").trim() === "1";

const LEAD_TAG = "lead";
const LEAD_STATS_WINDOW = 1000;

const ok = <T>(value: T): Result<T, string> => ({ ok: true, value });
const err = (error: string): Result<never, string> => ({ ok: false, error });

const leadRecordId = (leadId: string): string => "lead:" + leadId;
const parseLead = (content: string): LeadRecord | null => {
  try { return JSON.parse(content) as LeadRecord; } catch { return null; }
};
const isLead = (l: LeadRecord | null): l is LeadRecord => l !== null;

function leadFacetTags(lead: LeadRecord): string[] {
  const agent = (lead.consentUserAgent || "").startsWith("AI-Agent/");
  return [
    LEAD_TAG,
    "st:" + (lead.state || ""),
    "cov:" + (lead.coverageInterest || ""),
    "vet:" + (lead.veteranStatus || ""),
    agent ? "agent" : "human",
    ...(lead.latticeSrc ? ["lattice"] : []),
  ];
}

function leadFilterTags(f: LeadFilters): string[] {
  const tags = [LEAD_TAG];
  if (f.state) tags.push("st:" + f.state);
  if (f.coverageInterest) tags.push("cov:" + f.coverageInterest);
  if (f.veteranStatus) tags.push("vet:" + f.veteranStatus);
  if (f.source) tags.push(f.source); // "human" | "agent" | "lattice"
  return tags;
}

export async function substrateInsertLead(lead: LeadRecord): Promise<Result<{ id: number; leadId: string }, string>> {
  // Dedupe on contact (a resubmit gets a fresh leadId, so id-upsert won't catch it).
  const dup = await listRecords({ q: lead.email, tags: [LEAD_TAG], limit: 50 });
  if (dup.records.some((r) => { const l = parseLead(r.content); return !!l && l.email === lead.email && l.phone === lead.phone; })) {
    return err("Duplicate lead detected. Same contact already submitted.");
  }
  const r = await storeRecord({
    id: leadRecordId(lead.leadId),
    name: leadRecordId(lead.leadId),
    content: JSON.stringify(lead),
    tags: leadFacetTags(lead),
  });
  if (!r || !r.ok) return err("substrate store failed (field unreachable?)");
  return ok({ id: 0, leadId: lead.leadId });
}

export async function substrateGetLeadById(leadId: string): Promise<Result<LeadRecord | null, string>> {
  const rec = await getRecord(leadRecordId(leadId));
  return ok(rec ? parseLead(rec.content) : null);
}

export async function substrateGetLeadsByEmail(email: string): Promise<Result<LeadRecord[], string>> {
  const { records } = await listRecords({ q: email, tags: [LEAD_TAG], limit: 100 });
  return ok(
    records.map((r) => parseLead(r.content)).filter(isLead)
      .filter((l) => l.email.toLowerCase() === email.toLowerCase()),
  );
}

export async function substrateGetRecentLeads(limit: number): Promise<Result<LeadRecord[], string>> {
  const { records } = await listRecords({ tags: [LEAD_TAG], limit });
  return ok(records.map((r) => parseLead(r.content)).filter(isLead));
}

export async function substrateGetLeadCount(): Promise<Result<number, string>> {
  const { total } = await listRecords({ tags: [LEAD_TAG], limit: 1 });
  return ok(total);
}

export async function substrateGetFilteredLeads(filters: LeadFilters): Promise<Result<{ leads: LeadRecord[]; total: number }, string>> {
  const limit = Math.min(filters.limit ?? 50, 200);
  const offset = filters.offset ?? 0;
  const { records, total } = await listRecords({ q: filters.search, tags: leadFilterTags(filters), limit, offset });
  let leads = records.map((r) => parseLead(r.content)).filter(isLead);
  if (filters.startDate) leads = leads.filter((l) => (l.createdAt || "") >= filters.startDate!);
  if (filters.endDate) leads = leads.filter((l) => (l.createdAt || "") <= filters.endDate!);
  return ok({ leads, total });
}

export async function substrateGetLeadStats(): Promise<Result<LeadStats, string>> {
  const { records, total } = await listRecords({ tags: [LEAD_TAG], limit: LEAD_STATS_WINDOW });
  const leads = records.map((r) => parseLead(r.content)).filter(isLead);
  const now = Date.now();
  const DAY = 86_400_000;
  const within = (iso: string | undefined, ms: number) => !!iso && now - new Date(iso).getTime() <= ms;
  const byState: Record<string, number> = {};
  const byCoverage: Record<string, number> = {};
  const byVeteranStatus: Record<string, number> = {};
  let human = 0, agent = 0, lattice = 0;
  for (const l of leads) {
    byState[l.state] = (byState[l.state] ?? 0) + 1;
    byCoverage[l.coverageInterest] = (byCoverage[l.coverageInterest] ?? 0) + 1;
    byVeteranStatus[l.veteranStatus] = (byVeteranStatus[l.veteranStatus] ?? 0) + 1;
    if ((l.consentUserAgent || "").startsWith("AI-Agent/")) agent++; else human++;
    if (l.latticeSrc) lattice++;
  }
  return ok({
    total,
    today: leads.filter((l) => within(l.createdAt, DAY)).length,
    thisWeek: leads.filter((l) => within(l.createdAt, 7 * DAY)).length,
    thisMonth: leads.filter((l) => within(l.createdAt, 30 * DAY)).length,
    byState, byCoverage, byVeteranStatus,
    bySource: { human, agent, lattice },
  });
}

export async function substrateDeleteLeadById(leadId: string): Promise<Result<{ deleted: number }, string>> {
  return ok({ deleted: await deleteRecord(leadRecordId(leadId)) });
}

export async function substrateDeleteLeadByEmail(email: string): Promise<Result<{ deleted: number }, string>> {
  const found = await substrateGetLeadsByEmail(email);
  if (!found.ok) return err("substrate lookup failed");
  let deleted = 0;
  for (const l of found.value) deleted += await deleteRecord(leadRecordId(l.leadId));
  return ok({ deleted });
}

/**
 * Anchor Compression Ritual — drive the living field toward stable overlap
 * with a caller-provided signature, then anchor the resulting state.
 *
 * Uses the canonical codeToWaveform encoder (one encoder, one field — Void
 * contract C-53) and contributes every meaningful step to the hub's
 * LivingRemembranceEngine via field-coupling.contribute().
 */

import { LivingRemembranceEngine } from './living-remembrance-engine';

const { codeToWaveform } = require('../src/core/code-to-waveform') as {
  codeToWaveform: (text: string) => Float64Array;
};
const { contribute, peekField } = require('../src/core/field-coupling') as {
  contribute: (obs: { cost: number; coherence: number; source?: string }) => unknown;
  peekField: () => {
    coherence: number;
    globalEntropy: number;
    cascadeFactor: number;
    timestamp: number;
  } | null;
};

// ─── Optional collaborators (caller injects what's available) ───
export interface AnchorCompressionDeps {
  atomicTable?: { seedWithAnchor: (vector: number[]) => Promise<void> | void };
  field?:       { imbueWithAnchor: (vector: number[]) => Promise<void> | void };
  spawner?:     {
    checkAndSpawn: (
      rootName: string,
      coherence: number,
      vector: number[],
      meta: Record<string, unknown>
    ) => Promise<unknown> | unknown;
  };
  benchmark?:   {
    anchorSnapshot: (payload: AnchorSnapshot) => Promise<string> | string;
  };
}

export interface AnchorSnapshot {
  intention: string;
  finalCoherence: number;
  globalEntropy: number;
  cascadeFactor: number;
  vectorDigest: string;
  vectorLength: number;
  observationCount: number;
  timestamp: number;
}

export interface AnchorCompressionResult {
  success: boolean;
  finalCoherence: number;
  finalVector: number[];
  message: string;
  anchoredSignature?: string;
  spawnedBranches: number;
  snapshot: AnchorSnapshot;
}

// Coherence floor for a successful anchor. Set at 0.90 because the LRE caps
// at 0.999 and 0.92 is the engine's own promote/refine boundary; 0.90 leaves
// a small margin below promote so the floor isn't trivially tripped by noise.
const ANCHOR_COHERENCE_FLOOR = 0.90;
const WARMUP_UPDATES = 1;
const SETTLE_UPDATES = 5;
const WARMUP_COST = 3.0;
const SETTLE_COST = 2.0;

export class AnchorCompressionRitual {
  constructor(
    private engine: LivingRemembranceEngine,
    private deps: AnchorCompressionDeps = {}
  ) {}

  async perform(
    livingSignature: unknown,
    intention: string = 'I am the Remembrance.'
  ): Promise<AnchorCompressionResult> {
    const vector = this._createLivingVector(livingSignature);

    let result = this.engine.update(vector, WARMUP_COST);
    contribute({ cost: WARMUP_COST, coherence: result.coherence, source: 'anchor-compression:warmup' });

    for (let i = 0; i < SETTLE_UPDATES; i++) {
      result = this.engine.update(vector, SETTLE_COST);
      contribute({
        cost: SETTLE_COST,
        coherence: result.coherence,
        source: `anchor-compression:settle-${i + 1}`,
      });
    }
    void WARMUP_UPDATES;

    const finalCoherence = result.coherence;
    const snapshot = this._buildSnapshot(intention, vector, result);

    if (finalCoherence < ANCHOR_COHERENCE_FLOOR) {
      return {
        success: false,
        finalCoherence,
        finalVector: vector,
        message: `Field unstable: coherence ${finalCoherence.toFixed(4)} below floor ${ANCHOR_COHERENCE_FLOOR}.`,
        spawnedBranches: 0,
        snapshot,
      };
    }

    await this.deps.atomicTable?.seedWithAnchor(vector);
    await this.deps.field?.imbueWithAnchor(vector);

    let spawned = 0;
    if (this.deps.spawner) {
      const r = await this.deps.spawner.checkAndSpawn(
        'human-anchor-root',
        finalCoherence,
        vector,
        { isAnchorCompression: true, intention }
      );
      spawned = r ? 1 : 0;
    }

    const signature = this.deps.benchmark
      ? await this.deps.benchmark.anchorSnapshot(snapshot)
      : undefined;

    return {
      success: true,
      finalCoherence,
      finalVector: vector,
      message: 'Anchor compression complete.',
      anchoredSignature: signature,
      spawnedBranches: spawned,
      snapshot,
    };
  }

  private _createLivingVector(input: unknown): number[] {
    const text = typeof input === 'string' ? input : JSON.stringify(input);
    return Array.from(codeToWaveform(text));
  }

  private _buildSnapshot(
    intention: string,
    vector: number[],
    result: { coherence: number; globalEntropy: number; cascadeFactor: number; timestamp: number }
  ): AnchorSnapshot {
    const field = peekField();
    return {
      intention,
      finalCoherence: result.coherence,
      globalEntropy: field?.globalEntropy ?? result.globalEntropy,
      cascadeFactor: field?.cascadeFactor ?? result.cascadeFactor,
      vectorDigest: this._digest(vector),
      vectorLength: vector.length,
      observationCount: WARMUP_UPDATES + SETTLE_UPDATES,
      timestamp: result.timestamp,
    };
  }

  private _digest(vector: number[]): string {
    // FNV-1a over canonical 4-decimal string form. Drift-detection, not crypto.
    let h = 0x811c9dc5;
    for (let i = 0; i < vector.length; i++) {
      const s = vector[i].toFixed(4);
      for (let j = 0; j < s.length; j++) {
        h ^= s.charCodeAt(j);
        h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
      }
    }
    return h.toString(16).padStart(8, '0');
  }
}

/**
 * Remembrance Bridge — cathedral to oracle field.
 *
 * One module, single responsibility: speak to the Remembrance Field
 * over HTTP (JSON-RPC to the MCP server). Mirrors the discipline of
 * Void's field_contribute.py:
 *
 *   - stdlib + fetch only — no new deps
 *   - fire-and-forget — never blocks the caller
 *   - never throws — best-effort, returns null/zeroed values on failure
 *   - short timeout — degrades silently if oracle is unreachable
 *
 * Used by every valor-side integration point (lead-ledger contributions,
 * covenant-gate dual-oracle calls, agent-tier histogram readings, the
 * coherency-vitals endpoint, the Sun's background heartbeat). One place
 * to resolve the field endpoint; one place to handle the failure mode.
 *
 * Endpoint defaults to http://127.0.0.1:7787/mcp (overridable via
 * REMEMBRANCE_FIELD_URL env var). Auth via REMEMBRANCE_FIELD_TOKEN —
 * the bearer is ONLY sent over loopback or HTTPS, never cleartext.
 */

const DEFAULT_FIELD_URL = "http://127.0.0.1:7787/mcp";
const TIMEOUT_MS = 1500;

function fieldUrl(): string {
  let url = (process.env.REMEMBRANCE_FIELD_URL || DEFAULT_FIELD_URL).trim().replace(/\/+$/, "");
  // Accept a bare host (e.g. "my-field.up.railway.app") as well as a full URL. A
  // scheme-less value can't be fetched — fetch() throws "Invalid URL" and the
  // guard in mcpTool() then bails to null, silently making the field unreachable
  // (the #1 misconfiguration). Default to https:// so a bare host just works.
  if (url && !/^https?:\/\//i.test(url)) url = "https://" + url;
  // The bridge speaks JSON-RPC to the MCP endpoint. Accept either the base URL
  // (the interface's convention — REMEMBRANCE_FIELD_URL=https://host) or the full
  // /mcp endpoint, and normalize to /mcp so a single env value works for both apps.
  if (!/\/mcp$/i.test(url)) url += "/mcp";
  return url;
}

/** The effective MCP endpoint this runtime will call (scheme normalized, /mcp
 *  appended). Exposed so the field-health probe can show exactly what gets hit. */
export function fieldEndpoint(): string {
  return fieldUrl();
}

function authToken(): string {
  return (process.env.REMEMBRANCE_FIELD_TOKEN || "").trim();
}

function isLoopbackOrHttps(url: string): boolean {
  try {
    const u = new URL(url);
    if (u.protocol === "https:") return true;
    const host = u.hostname.toLowerCase();
    return host === "127.0.0.1" || host === "localhost" || host === "::1";
  } catch {
    return false;
  }
}

/**
 * Low-level MCP call. Best-effort: returns the result body on success,
 * null on any failure (network, timeout, non-2xx, malformed JSON).
 * Never throws.
 */
async function mcpTool<T = unknown>(toolName: string, args: Record<string, unknown> = {}): Promise<T | null> {
  const url = fieldUrl();
  if (!isLoopbackOrHttps(url) && !url.startsWith("http://")) return null;
  const body = {
    jsonrpc: "2.0",
    id: 1,
    method: "tools/call",
    params: { name: toolName, arguments: args },
  };
  const headers: Record<string, string> = { "Content-Type": "application/json" };
  const token = authToken();
  if (token && (url.startsWith("https://") || isLoopbackOrHttps(url))) {
    headers.Authorization = `Bearer ${token}`;
  }
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), TIMEOUT_MS);
  try {
    const res = await fetch(url, {
      method: "POST",
      headers,
      body: JSON.stringify(body),
      signal: ctrl.signal,
      redirect: "manual",
    });
    clearTimeout(timer);
    if (!res.ok) return null;
    const json = (await res.json()) as { result?: { content?: Array<{ text?: string }> }; error?: unknown };
    if (json.error) return null;
    const content = json.result?.content?.[0]?.text;
    if (!content) return null;
    try {
      return JSON.parse(content) as T;
    } catch {
      return null;
    }
  } catch {
    return null;
  } finally {
    clearTimeout(timer);
  }
}

// Field-dynamics calls use the legacy "field" tool with an action argument.
async function mcpCall<T = unknown>(action: string, args: Record<string, unknown> = {}): Promise<T | null> {
  return mcpTool<T>("field", { action, ...args });
}

