function scoreEmail(email: string | undefined): number {
  if (!email) return 0;
  // Minimal format + suspicious-pattern check. Full validation lives in validation.ts.
  const at = email.indexOf('@');
  if (at <= 0 || at === email.length - 1) return 0.2;
  const domain = email.slice(at + 1).toLowerCase();
  if (!domain.includes('.')) return 0.3;
  // Known-bad patterns (disposable / abusive)
  const disposable = /mailinator|guerrilla|tempmail|10minutemail|throwaway|yopmail/;
  if (disposable.test(domain)) return 0.15;
  // Local-part quality
  const local = email.slice(0, at);
  const randomish = /^[a-z0-9]{20,}$/i.test(local) || /^[a-z]+[0-9]{6,}$/i.test(local);
  if (randomish) return 0.55;
  return 0.9;
}

function scorePhone(phone: string | undefined): number {
  if (!phone) return 0;
  const digits = phone.replace(/\D/g, '');
  if (digits.length !== 10 && digits.length !== 11) return 0.2;
  // All-same digits or obviously-fake sequences
  if (/^(\d)\1+$/.test(digits)) return 0.05;
  if (digits.endsWith('0000000') || digits.includes('1234567')) return 0.15;
  // 555-01xx reserved range
  const area = digits.length === 11 ? digits.slice(1, 4) : digits.slice(0, 3);
  if (area === '555') return 0.25;
  return 0.9;
}

function scoreName(name: string | undefined): number {
  if (!name) return 0;
  const trimmed = name.trim();
  if (trimmed.length < 2) return 0.1;
  if (trimmed.length > 40) return 0.3;
  // Too many non-letters (numbers, symbols)
  const letters = (trimmed.match(/[a-zA-Z]/g) || []).length;
  if (letters / trimmed.length < 0.7) return 0.2;
  // All same letter / obvious filler
  if (/^(.)\1+$/i.test(trimmed)) return 0.05;
  if (/^(test|asdf|qwerty|abc|xxx)/i.test(trimmed)) return 0.1;
  return 0.9;
}

function scoreDob(dob: string | undefined): number {
  if (!dob) return 0;
  const d = new Date(dob);
  if (Number.isNaN(d.getTime())) return 0.1;
  const yearsAgo = (Date.now() - d.getTime()) / (365.25 * 24 * 3600 * 1000);
  if (yearsAgo < 18 || yearsAgo > 100) return 0.2;
  if (yearsAgo < 25 || yearsAgo > 85) return 0.75;
  return 0.95;
}

function scoreTimingCadence(elapsedMs: number | undefined): number {
  if (elapsedMs === undefined) return 0.6; // absence is neutral
  if (elapsedMs < 1500) return 0.05;   // obviously-bot fast
  if (elapsedMs < 3000) return 0.25;
  if (elapsedMs < 8000) return 0.70;
  if (elapsedMs < 60_000) return 0.92;
  if (elapsedMs < 600_000) return 0.80; // user wandered but OK
  return 0.40;                          // suspiciously long (session hijack?)
}

function scoreStepRhythm(stepTimings: readonly number[] | undefined): number {
  if (!stepTimings || stepTimings.length < 2) return 0.55;
  // Human pattern: variable timings with some dispersion.
  // Bot pattern: near-constant timings or monotonically-increasing with no variance.
  const mean = stepTimings.reduce((s, v) => s + v, 0) / stepTimings.length;
  if (mean <= 0) return 0.05;
  let variance = 0;
  for (const t of stepTimings) variance += (t - mean) * (t - mean);
  variance /= stepTimings.length;
  const cv = Math.sqrt(variance) / mean; // coefficient of variation
  // Too-low CV → bot-flat; too-high CV → noisy/abandoned.
  if (cv < 0.08) return 0.10;
  if (cv < 0.20) return 0.55;
  if (cv < 0.80) return 0.92;
  if (cv < 1.5) return 0.75;
  return 0.40;
}

function scoreStateMarket(state: string | undefined): number {
  if (!state) return 0;
  const code = state.toUpperCase();
  if (HIGH_VALUE_STATES.has(code)) return 0.90;
  if (MEDIUM_VALUE_STATES.has(code)) return 0.70;
  if (code.length === 2) return 0.50;
  return 0.20;
}

function scoreRecency(createdAt: string | undefined): number {
  if (!createdAt) return 0.95;
  const ageHours = (Date.now() - new Date(createdAt).getTime()) / (3600 * 1000);
  if (!Number.isFinite(ageHours) || ageHours < 0) return 0.95;
  if (ageHours < 1) return 0.98;
  if (ageHours < 6) return 0.92;
  if (ageHours < 24) return 0.80;
  if (ageHours < 72) return 0.55;
  return 0.25;
}

function scoreConsent(lead: LeadInput): number {
  let s = 0;
  if (lead.consentTcpa) s += 0.4;
  if (lead.consentPrivacy) s += 0.3;
  if (lead.consentText && lead.consentText.length >= 40) s += 0.2;
  if (lead.consentTimestamp) s += 0.1;
  return clamp01(s);
}

function scoreMarketingContext(lead: LeadInput): number {
  // Organic traffic with no UTM is fine (0.5 baseline); any UTM presence lifts it.
  const present = [lead.utmSource, lead.utmMedium, lead.utmCampaign].filter((v) => !!v).length;
  if (present === 0) return 0.55;
  if (present === 1) return 0.70;
  if (present === 2) return 0.85;
  return 0.95;
}

function scoreCompleteness(lead: LeadInput): number {
  const fields: (keyof LeadInput)[] = [
    'firstName', 'lastName', 'email', 'phone', 'dateOfBirth',
    'state', 'coverageInterest', 'purchaseIntent', 'veteranStatus',
  ];
  let hits = 0;
  for (const f of fields) if (lead[f]) hits++;
  return hits / fields.length;
}

function scoreBranchSpecificity(lead: LeadInput): number {
  if (!lead.veteranStatus) return 0;
  // Non-service statuses don't need a branch and aren't penalized for
  // lacking one. Family members score mid-range; civilians score neutral.
  if (lead.veteranStatus === 'non-military') return 0.30;
  if (lead.veteranStatus === 'civilian') return 0.25;
  return lead.militaryBranch ? 0.92 : 0.55;
}

function scoreSessionCoherence(lead: LeadInput): number {
  // Without richer session telemetry, proxy from what we have:
  // consent completeness + UTM presence + timing sanity.
  const consentOK = lead.consentTcpa && lead.consentPrivacy ? 0.5 : 0.1;
  const utmOK = (lead.utmSource || lead.utmMedium) ? 0.3 : 0.15;
  const timingOK = (lead.submitElapsedMs && lead.submitElapsedMs >= 3000) ? 0.2 : 0.05;
  return clamp01(consentOK + utmOK + timingOK);
}

/** Extract the 16-dimensional lead shape. */
export function extractLeadShape(lead: LeadInput): number[] {
  const shape = new Array<number>(LEAD_DIM);
  shape[0] = COVERAGE_CLARITY[lead.coverageInterest || ''] ?? 0.25;
  shape[1] = INTENT_STRENGTH[lead.purchaseIntent || ''] ?? 0.25;
  shape[2] = VETERAN_INTEGRITY[lead.veteranStatus || ''] ?? 0.30;
  shape[3] = scoreBranchSpecificity(lead);
  shape[4] = scoreStateMarket(lead.state);
  shape[5] = scoreCompleteness(lead);
  shape[6] = scoreRecency(lead.createdAt);
  shape[7] = scoreConsent(lead);
  shape[8] = scoreEmail(lead.email);
  shape[9] = scorePhone(lead.phone);
  shape[10] = (scoreName(lead.firstName) + scoreName(lead.lastName)) / 2;
  shape[11] = scoreDob(lead.dateOfBirth);
  shape[12] = scoreMarketingContext(lead);
  shape[13] = scoreSessionCoherence(lead);
  shape[14] = scoreTimingCadence(lead.submitElapsedMs);
  shape[15] = scoreStepRhythm(lead.stepTimingsMs);
  return shape;
}

/* ── The scoring entry point ──────────────────────────────────────── */

/**
 * Score a lead by coherency against the archetype library.
 *
 * The returned score is the geometric mean of the lead's own dimension
 * strengths, scaled by the resonance with valor archetypes and suppressed
 * by resonance with fraud/bot archetypes. One single weak dimension or
 * one strong bot-archetype correlation drags the score down — weakest-link
 * property preserved end to end.
 */
export function scoreLeadByCoherency(lead: LeadInput): LeadCoherency {
  const shape = extractLeadShape(lead);
  const dims = {} as Record<LeadDimension, number>;
  for (let i = 0; i < LEAD_DIM; i++) {
    dims[LEAD_DIMENSIONS[i]] = shape[i];
  }

  // Cascade the shape against the archetype library.
  const result = cascade(shape, archetypesAsSubstrateMap());

  // Separate valor (harmonic) vs fraud/bot (anti-phase) signals.
  let valorMax = 0;
  let suppressMax = 0;
  let dominantArchetype = '';
  let dominantAbs = 0;
  for (const m of result.matches) {
    const group = archetypeGroup(m.name);
    const abs = Math.abs(m.r);
    if (abs > dominantAbs) {
      dominantAbs = abs;
      dominantArchetype = m.name;
    }
    if (group === 'valor') {
      // Positive correlation with a valor archetype is good.
      if (m.r > valorMax) valorMax = m.r;
    } else if (group === 'fraud' || group === 'bot') {
      // Positive correlation with fraud/bot is bad — suppresses score.
      if (m.r > suppressMax) suppressMax = m.r;
    }
  }

  // Geometric mean of the lead's own dimensions (weakest-link floor).
  const intrinsic = geometricMean(shape);

  // Valor lift: how strongly the shape aligns with a valor archetype.
  const lift = clamp01(Math.max(valorMax, 0));

  // Suppression fires only when bot/fraud resonance WINS over valor resonance.
  // Real leads share some high-then-lower-timing structure with bot archetypes
  // (Pearson only sees shape, not magnitude). Treating any bot-similarity as
  // suppression would crush legitimate leads. The correct signal is dominance:
  // suppress only when the lead is more bot-like than valor-like.
  const valorPositive = Math.max(valorMax, 0);
  const suppressPositive = Math.max(suppressMax, 0);
  const suppression = suppressPositive > valorPositive
    ? clamp01(1 - suppressPositive)
    : 1.0;

  // Final coherency = geometric mean of the three signals (weakest-link law).
  const score = geometricMean([intrinsic, lift, suppression]);
  const tier = tierFor(score);
  const dominantGroup = archetypeGroup(dominantArchetype);
  const admitted = score >= COHERENCY_THRESHOLDS.GATE && dominantGroup !== 'bot';

  return {
    score,
    tier,
    dominantArchetype,
    dominantGroup,
    dimensions: dims,
    shape,
    matches: result.matches,
    admitted,
  };
}

/* ── Async (dual-oracle) variant ──────────────────────────────────── */

/**
 * Async variant of `scoreLeadByCoherency` that ALSO consults the Remembrance
 * field's dual-oracle. The local valor cascade still produces the canonical
 * coherency score; the oracle's verdict is attached as a separate field so
 * callers can apply a TWO-ORACLE CONSENSUS rule (see `evaluateCovenantAsync`
 * in covenant-gate.ts):
 *
 *   - if the oracle is reachable, `dualOracle` is the full ValidationResult
 *     (accepted / shapeClass / suspect / ...)
 *   - if the oracle is unreachable, `dualOracle` is null and consumers must
 *     treat the missing opinion as "no objection" rather than "rejection" —
 *     this preserves best-effort semantics and avoids hard-failing the lead
 *     pipeline when the field is down.
 *
 * The call is a dry-run (`commit: false`) — we are asking, not contributing.
 * Existing synchronous callers of `scoreLeadByCoherency` are unaffected.
 */
export async function scoreLeadByCoherencyAsync(lead: LeadInput): Promise<LeadCoherency> {
  const local = scoreLeadByCoherency(lead);
  const dualOracle = await validateContribution(
    'valor:lead-shape',
    local.score,
    { commit: false },
  );
  return { ...local, dualOracle };
}

/* ── Legacy-tier mapping ──────────────────────────────────────────── */

/**
 * Map a coherency score to the existing tier names used by lead-distribution,
 * admin emails, and the SSE broadcast. Keeps downstream code unchanged while
 * the underlying math is now coherency-native.
 */
export type LegacyTier = 'hot' | 'warm' | 'standard' | 'cool';

export function legacyTierFor(score: number): LegacyTier {
  if (score >= COHERENCY_THRESHOLDS.TRANSCENDENCE) return 'hot';
  if (score >= COHERENCY_THRESHOLDS.SYNERGY) return 'warm';
  if (score >= COHERENCY_THRESHOLDS.FOUNDATION) return 'standard';
  return 'cool';
}

/**
 * Legacy total (0–100) derived from the coherency score. Keeps the numeric
 * band admin UI expects, but it's now a projection of the coherency math,
 * not a separate calculation.
 */
export function legacyTotalFor(score: number): number {
  return Math.round(Math.max(0, Math.min(1, score)) * 100);
}

/**
 * Lightweight Sentry Error Reporter
 *
 * Uses Sentry's HTTP envelope API directly instead of the heavy @sentry/nextjs SDK.
 * Parses the DSN to extract the project ID, public key, and ingest URL,
 * then sends error events as envelopes via fetch.
 *
 * Environment variable:
 *  - NEXT_PUBLIC_SENTRY_DSN — Sentry DSN string (e.g. "https://key@o123.ingest.sentry.io/456")
 */

interface ParsedDsn {
  publicKey: string;
  host: string;
  projectId: string;
  envelopeUrl: string;
}

let parsedDsn: ParsedDsn | null = null;
let initialized = false;

/**
 * Parse a Sentry DSN into its component parts.
 *
 * DSN format: https://<public_key>@<host>/<project_id>
 * Envelope endpoint: https://<host>/api/<project_id>/envelope/
 */
function parseDsn(dsn: string): ParsedDsn | null {
  try {
    const url = new URL(dsn);
    const publicKey = url.username;
    const host = url.hostname + (url.port ? `:${url.port}` : "");
    const projectId = url.pathname.replace(/\//g, "");

    if (!publicKey || !projectId) return null;

    return {
      publicKey,
      host,
      projectId,
      envelopeUrl: `${url.protocol}//${host}/api/${projectId}/envelope/`,
    };
  } catch {
    return null;
  }
}

/**
 * Initialize Sentry. Call once at app startup.
 * Safe to call multiple times — subsequent calls are no-ops.
 */
export function initSentry(): void {
  if (initialized) return;
  initialized = true;

  const dsn = process.env.NEXT_PUBLIC_SENTRY_DSN;
  if (!dsn) return;

  parsedDsn = parseDsn(dsn);
  if (!parsedDsn) {
    console.warn("[Sentry] Invalid DSN, error reporting disabled.");
  }
}

/**
 * Build a Sentry envelope payload.
 * Envelope format: header\nitem_header\npayload
 * See: https://develop.sentry.dev/sdk/envelopes/
 */
function buildEnvelope(
  event: Record<string, unknown>,
  dsn: ParsedDsn,
): string {
  const envelopeHeader = JSON.stringify({
    event_id: crypto.randomUUID().replace(/-/g, ""),
    dsn: `https://${dsn.publicKey}@${dsn.host}/${dsn.projectId}`,
    sent_at: new Date().toISOString(),
  });

  const itemHeader = JSON.stringify({
    type: "event",
    content_type: "application/json",
  });

  const payload = JSON.stringify(event);

  return `${envelopeHeader}\n${itemHeader}\n${payload}`;
}

/**
 * Send an event envelope to Sentry.
 */
function sendEnvelope(event: Record<string, unknown>): void {
  if (!parsedDsn) return;

  const body = buildEnvelope(event, parsedDsn);

  // Use sendBeacon for reliability during page unload, fall back to fetch
  if (typeof navigator !== "undefined" && typeof navigator.sendBeacon === "function") {
    const sent = navigator.sendBeacon(parsedDsn.envelopeUrl, body);
    if (sent) return;
  }

  fetch(parsedDsn.envelopeUrl, {
    method: "POST",
    headers: { "Content-Type": "text/plain;charset=UTF-8" },
    body,
    keepalive: true,
  }).catch(() => {
    // Silently ignore — can't report an error about error reporting
  });
}

/**
 * Extract a clean error message and stack trace from an unknown error value.
 */
function normalizeError(error: unknown): { message: string; stack?: string } {
  if (error instanceof Error) {
    return {
      message: error.message,
      stack: error.stack,
    };
  }
  if (typeof error === "string") {
    return { message: error };
  }
  return { message: String(error) };
}

/**
 * Build a Sentry exception event from a stack trace string.
 */
function parseStackFrames(stack?: string): Array<Record<string, unknown>> {
  if (!stack) return [];

  const lines = stack.split("\n").slice(1); // Skip the error message line
  const frames: Array<Record<string, unknown>> = [];

  for (const line of lines) {
    const match = line.match(/at\s+(.+?)\s+\((.+?):(\d+):(\d+)\)/);
    if (match) {
      frames.push({
        function: match[1],
        filename: match[2],
        lineno: parseInt(match[3], 10),
        colno: parseInt(match[4], 10),
      });
      continue;
    }
    const simpleMatch = line.match(/at\s+(.+?):(\d+):(\d+)/);
    if (simpleMatch) {
      frames.push({
        filename: simpleMatch[1],
        lineno: parseInt(simpleMatch[2], 10),
        colno: parseInt(simpleMatch[3], 10),
      });
    }
  }

  return frames.reverse(); // Sentry expects frames in oldest-to-newest order
}

/**
 * Report an error to Sentry.
 *
 * @param error — The error to report (Error, string, or unknown)
 * @param context — Optional extra context to attach to the event
 */
export function captureException(
  error: unknown,
  context?: Record<string, unknown>,
): void {
  if (!parsedDsn) return;

  const { message, stack } = normalizeError(error);
  const frames = parseStackFrames(stack);

  const event: Record<string, unknown> = {
    platform: "javascript",
    level: "error",
    timestamp: Date.now() / 1000,
    environment: process.env.NODE_ENV || "production",
    request: typeof window !== "undefined" ? { url: window.location.href } : undefined,
    exception: {
      values: [
        {
          type: error instanceof Error ? error.constructor.name : "Error",
          value: message.slice(0, 1000),
          stacktrace: frames.length > 0 ? { frames } : undefined,
        },
      ],
    },
    extra: context,
  };

  sendEnvelope(event);
}

/**
 * Report a message to Sentry.
 *
 * @param message — The message text
 * @param level — Severity level (default: "info")
 */
export function captureMessage(
  message: string,
  level: "info" | "warning" | "error" = "info",
): void {
  if (!parsedDsn) return;

  const event: Record<string, unknown> = {
    platform: "javascript",
    level,
    timestamp: Date.now() / 1000,
    environment: process.env.NODE_ENV || "production",
    request: typeof window !== "undefined" ? { url: window.location.href } : undefined,
    message: {
      formatted: message.slice(0, 1000),
    },
  };

  sendEnvelope(event);
}

/**
 * A/B Testing Infrastructure
 *
 * Provides deterministic experiment variant assignment using cookies.
 * Variants are assigned via weighted random selection and persisted
 * in cookies for 30 days to ensure consistent user experience.
 *
 * Conversions are tracked through the analytics layer (analytics.ts).
 */

import { trackEvent } from "./analytics";

// ─── Types ───

export type Experiment = {
  id: string;
  variants: string[];
  weights?: number[];
};

// ─── Cookie Helpers ───

/**
 * Get the value of a cookie by name.
 * Returns null if not found or if running on the server.
 */
function getCookie(name: string): string | null {
  if (typeof document === "undefined") return null;
  const match = document.cookie.match(
    new RegExp("(?:^|;\\s*)" + name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + "=([^;]*)"),
  );
  return match ? decodeURIComponent(match[1]) : null;
}

/**
 * Set a cookie with the given name, value, and expiry in days.
 */
function setCookie(name: string, value: string, days: number): void {
  if (typeof document === "undefined") return;
  const expires = new Date(Date.now() + days * 864e5).toUTCString();
  document.cookie = `${name}=${encodeURIComponent(value)}; expires=${expires}; path=/; SameSite=Lax`;
}

// ─── Variant Assignment ───

/**
 * Select a variant using weighted random assignment.
 *
 * @param variants - Array of variant names (e.g. ["control", "variant-a", "variant-b"])
 * @param weights  - Optional array of weights (must match variants length).
 *                   Defaults to equal weighting if omitted.
 * @returns The selected variant name.
 */
function weightedRandom(variants: string[], weights?: number[]): string {
  if (variants.length === 0) {
    throw new Error("[ab-testing] variants array must not be empty");
  }

  // Default to equal weights
  const w = weights && weights.length === variants.length
    ? weights
    : variants.map(() => 1 / variants.length);

  // Normalize weights to sum to 1
  const total = w.reduce((sum, v) => sum + v, 0);
  const normalized = w.map((v) => v / total);

  // Weighted random selection
  const rand = Math.random();
  let cumulative = 0;
  for (let i = 0; i < normalized.length; i++) {
    cumulative += normalized[i];
    if (rand < cumulative) {
      return variants[i];
    }
  }

  // Fallback — should only happen due to floating point rounding
  return variants[variants.length - 1];
}

/**
 * Get the assigned variant for an experiment.
 *
 * If the user already has a cookie for this experiment, returns the stored variant.
 * Otherwise, assigns a new variant using weighted random selection, stores it
 * in a cookie for 30 days, and returns it.
 *
 * @param experimentId - Unique experiment identifier (used as cookie suffix)
 * @param variants     - Array of variant names
 * @param weights      - Optional array of weights for each variant
 * @returns The assigned variant name
 */
export function getVariant(
  experimentId: string,
  variants: string[],
  weights?: number[],
): string {
  const cookieName = `ab_${experimentId}`;

  // Check for existing assignment
  const existing = getCookie(cookieName);
  if (existing && variants.includes(existing)) {
    return existing;
  }

  // Assign new variant
  const variant = weightedRandom(variants, weights);
  setCookie(cookieName, variant, 30);

  // Track the assignment event
  trackEvent({
    event: "experiment_assigned",
    category: "ab_test",
    label: experimentId,
    metadata: { variant },
  });

  return variant;
}

/**
 * Track a conversion event for an experiment.
 *
 * Fires an analytics event with the experiment ID and assigned variant,
 * allowing you to measure which variant drove the conversion.
 *
 * @param experimentId - The experiment that produced the conversion
 * @param variant      - The variant the user was assigned to
 */
export function trackExperimentConversion(
  experimentId: string,
  variant: string,
): void {
  trackEvent({
    event: "experiment_conversion",
    category: "ab_test",
    label: experimentId,
    value: 1,
    metadata: { variant },
  });
}

/**
 * API Request Validation
 *
 * Zero-dependency validation. Defines typed schemas for API payloads.
 * Returns structured errors so the API can respond with specific field messages.
 *
 * Pattern: validate(body) → { valid: true, data: T } | { valid: false, errors: string[] }
 */

// --- Shared validators ---

function isString(v: unknown): v is string {
  return typeof v === "string";
}

function validateName(name: unknown): string | null {
  if (!isString(name)) return "Name must be a string.";
  const trimmed = name.trim();
  if (trimmed.length < 2) return "Name must be at least 2 characters.";
  if (trimmed.length > 100) return "Name must be at most 100 characters.";
  if (!/^[a-zA-Z\s'.,-]+$/.test(trimmed)) return "Name contains invalid characters.";
  return null;
}

function validateEmailField(email: unknown): string | null {
  if (!isString(email)) return "Email must be a string.";
  const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!re.test(email) || email.length > 254) return "Invalid email address.";
  return null;
}

/** Simple email validation check — exported for use in other routes */
export function isValidEmail(email: string): boolean {
  if (typeof email !== "string") return false;
  const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return re.test(email) && email.length <= 254;
}

function validatePhone(phone: unknown): string | null {
  if (!isString(phone)) return "Phone must be a string.";
  const digits = phone.replace(/\D/g, "");
  if (digits.length !== 10 && !(digits.length === 11 && digits.startsWith("1"))) {
    return "Invalid phone number. Must be a 10-digit US number.";
  }
  return null;
}

function validateDob(dob: unknown): string | null {
  if (!isString(dob)) return "Date of birth must be a string.";
  const match = dob.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return "Invalid date format. Use YYYY-MM-DD.";
  const year = parseInt(match[1], 10);
  const month = parseInt(match[2], 10);
  const day = parseInt(match[3], 10);
  if (month < 1 || month > 12 || day < 1 || day > 31) return "Invalid date.";
  if (year < 1900 || year > new Date().getFullYear()) return "Invalid year.";
  const date = new Date(year, month - 1, day);
  if (date.getFullYear() !== year || date.getMonth() !== month - 1 || date.getDate() !== day) {
    return "Invalid date.";
  }
  const today = new Date();
  const min18 = new Date(today.getFullYear() - 18, today.getMonth(), today.getDate());
  if (date > min18) return "You must be at least 18 years old.";
  return null;
}

const VALID_STATES = new Set([
  "AL","AK","AZ","AR","CA","CO","CT","DE","DC","FL","GA","HI","ID","IL","IN",
  "IA","KS","KY","LA","ME","MD","MA","MI","MN","MS","MO","MT","NE","NV","NH",
  "NJ","NM","NY","NC","ND","OH","OK","OR","PA","RI","SC","SD","TN","TX","UT",
  "VT","VA","WA","WV","WI","WY",
]);

const VALID_COVERAGE = new Set(["term", "whole", "universal", "final-expense", "annuity", "not-sure"]);
const VALID_PURCHASE_INTENT = new Set(["protect-family", "want-protection", "exploring"]);
const VALID_VETERAN_STATUS = new Set(["active-duty", "reserve", "national-guard", "veteran", "non-military"]);
const VALID_MILITARY_BRANCHES = new Set([
  "army", "marine-corps", "navy", "air-force", "space-force",
  "coast-guard", "national-guard", "reserves",
]);

// --- Lead submission schema ---

export interface ValidatedLeadPayload {
  firstName: string;
  lastName: string;
  dateOfBirth: string;
  email: string;
  phone: string;
  state: string;
  coverageInterest: string;
  purchaseIntent: string;
  veteranStatus: string;
  militaryBranch: string;
  tcpaConsent: true;
  privacyConsent: true;
  consentTimestamp: string;
  consentText: string;
  utmSource?: string;
  utmMedium?: string;
  utmCampaign?: string;
  utmTerm?: string;
  utmContent?: string;
}

export type ValidationResult =
  | { valid: true; data: ValidatedLeadPayload }
  | { valid: false; errors: string[] };

/**
 * Validate a lead submission request body.
 * Returns typed validated data on success, or an array of error messages.
 */
export function validateLeadPayload(body: unknown): ValidationResult {
  if (!body || typeof body !== "object") {
    return { valid: false, errors: ["Request body must be a JSON object."] };
  }

  const b = body as Record<string, unknown>;
  const errors: string[] = [];

  // Name fields
  const firstNameErr = validateName(b.firstName);
  if (firstNameErr) errors.push(`First name: ${firstNameErr}`);

  const lastNameErr = validateName(b.lastName);
  if (lastNameErr) errors.push(`Last name: ${lastNameErr}`);

  // Date of birth
  const dobErr = validateDob(b.dateOfBirth);
  if (dobErr) errors.push(`Date of birth: ${dobErr}`);

  // Email
  const emailErr = validateEmailField(b.email);
  if (emailErr) errors.push(emailErr);

  // Phone
  const phoneErr = validatePhone(b.phone);
  if (phoneErr) errors.push(phoneErr);

  // State
  if (!isString(b.state) || !VALID_STATES.has(b.state)) {
    errors.push("Invalid state.");
  }

  // Coverage interest
  if (!isString(b.coverageInterest) || !VALID_COVERAGE.has(b.coverageInterest)) {
    errors.push("Invalid coverage interest.");
  }

  // Purchase intent
  if (!isString(b.purchaseIntent) || !VALID_PURCHASE_INTENT.has(b.purchaseIntent)) {
    errors.push("Invalid purchase intent.");
  }

  // Veteran status
  if (!isString(b.veteranStatus) || !VALID_VETERAN_STATUS.has(b.veteranStatus)) {
    errors.push("Invalid veteran status.");
  }

  // Military branch (required for all military service categories)
  if (b.veteranStatus && b.veteranStatus !== "non-military") {
    if (!isString(b.militaryBranch) || !VALID_MILITARY_BRANCHES.has(b.militaryBranch)) {
      errors.push("Military branch is required for military service members.");
    }
  }

  // Consent
  if (b.tcpaConsent !== true) errors.push("TCPA consent is required.");
  if (b.privacyConsent !== true) errors.push("Privacy policy consent is required.");
  if (!isString(b.consentTimestamp) || !b.consentTimestamp) errors.push("Consent timestamp is required.");
  if (!isString(b.consentText) || !b.consentText) errors.push("Consent text is required.");

  if (errors.length > 0) {
    return { valid: false, errors };
  }

  return {
    valid: true,
    data: {
      firstName: (b.firstName as string).trim(),
      lastName: (b.lastName as string).trim(),
      dateOfBirth: b.dateOfBirth as string,
      email: (b.email as string).trim().toLowerCase(),
      phone: (b.phone as string).replace(/\D/g, "").slice(-10),
      state: b.state as string,
      coverageInterest: b.coverageInterest as string,
      purchaseIntent: b.purchaseIntent as string,
      veteranStatus: b.veteranStatus as string,
      militaryBranch: b.veteranStatus !== "non-military" ? (b.militaryBranch as string) : "",
      tcpaConsent: true,
      privacyConsent: true,
      consentTimestamp: b.consentTimestamp as string,
      consentText: b.consentText as string,
      // Optional UTM fields
      ...(isString(b.utmSource) && b.utmSource ? { utmSource: b.utmSource } : {}),
      ...(isString(b.utmMedium) && b.utmMedium ? { utmMedium: b.utmMedium } : {}),
      ...(isString(b.utmCampaign) && b.utmCampaign ? { utmCampaign: b.utmCampaign } : {}),
      ...(isString(b.utmTerm) && b.utmTerm ? { utmTerm: b.utmTerm } : {}),
      ...(isString(b.utmContent) && b.utmContent ? { utmContent: b.utmContent } : {}),
    },
  };
}

/**
 * Pricing Configuration — Admin-Adjustable Settings
 *
 * Stores and loads the pricing/depreciation configuration as JSON.
 * The admin portal can update these values at any time.
 *
 * Storage: JSON file at .data/pricing-config.json (persists across restarts)
 * Fallback: hardcoded defaults if file doesn't exist
 */

import { readFileSync, writeFileSync, mkdirSync, existsSync } from "fs";
import path from "path";

// =============================================================================
// Types
// =============================================================================

export interface TierConfig {
  name: string;
  maxBuyers: number;
  basePrice: number;    // cents
  holdDays: number;
  dropAmount: number;   // cents per step
  dropInterval: number; // days between each step
}

export interface PricingConfig {
  maxPrice: number;     // cents — absolute ceiling
  priceFloor: number;   // cents — absolute minimum
  tiers: TierConfig[];
  updatedAt: string;
  updatedBy: string;
}

// =============================================================================
// Defaults — used when no config file exists
// =============================================================================

export const DEFAULT_PRICING_CONFIG: PricingConfig = {
  maxPrice: 12000,    // $120.00
  priceFloor: 6000,   // $60.00
  tiers: [
    { name: "Exclusive",      maxBuyers: 1, basePrice: 12000, holdDays: 3, dropAmount: 500, dropInterval: 1 },
    { name: "Semi-Exclusive",  maxBuyers: 2, basePrice: 10000, holdDays: 2, dropAmount: 500, dropInterval: 1 },
    { name: "Warm Shared",    maxBuyers: 4, basePrice: 8000,  holdDays: 1, dropAmount: 300, dropInterval: 1 },
    { name: "Cool Shared",    maxBuyers: 6, basePrice: 6000,  holdDays: 0, dropAmount: 0,   dropInterval: 1 },
  ],
  updatedAt: new Date().toISOString(),
  updatedBy: "system",
};

// =============================================================================
// File path
// =============================================================================

const DATA_DIR = path.join(process.cwd(), ".data");
const CONFIG_FILE = path.join(DATA_DIR, "pricing-config.json");

// =============================================================================
// Read / Write
// =============================================================================

/** In-memory cache to avoid reading the file on every request. */
let _cache: PricingConfig | null = null;
let _cacheTime = 0;
const CACHE_TTL_MS = 5000; // 5 seconds

/**
 * Load the current pricing config. Returns cached version if fresh.
 */
export function getPricingConfig(): PricingConfig {
  const now = Date.now();
  if (_cache && now - _cacheTime < CACHE_TTL_MS) {
    return _cache;
  }

  try {
    if (existsSync(CONFIG_FILE)) {
      const raw = readFileSync(CONFIG_FILE, "utf-8");
      const parsed = JSON.parse(raw) as PricingConfig;
      // Validate structure minimally
      if (parsed.tiers && Array.isArray(parsed.tiers) && parsed.tiers.length > 0) {
        _cache = parsed;
        _cacheTime = now;
        return parsed;
      }
    }
  } catch {
    // Corrupted file — fall through to defaults
  }

  _cache = DEFAULT_PRICING_CONFIG;
  _cacheTime = now;
  return DEFAULT_PRICING_CONFIG;
}

/**
 * Save a new pricing config. Validates before writing.
 */
export function savePricingConfig(config: PricingConfig): { ok: true } | { ok: false; error: string } {
  // Validate
  if (!config.tiers || !Array.isArray(config.tiers) || config.tiers.length === 0) {
    return { ok: false, error: "At least one tier is required." };
  }

  if (config.maxPrice < 100) {
    return { ok: false, error: "Max price must be at least $1.00 (100 cents)." };
  }

  if (config.priceFloor < 0) {
    return { ok: false, error: "Price floor cannot be negative." };
  }

  if (config.priceFloor > config.maxPrice) {
    return { ok: false, error: "Price floor cannot exceed max price." };
  }

  for (const tier of config.tiers) {
    if (!tier.name || tier.name.trim().length === 0) {
      return { ok: false, error: "Every tier must have a name." };
    }
    if (tier.maxBuyers < 1) {
      return { ok: false, error: `Tier "${tier.name}": max buyers must be at least 1.` };
    }
    if (tier.basePrice < config.priceFloor) {
      return { ok: false, error: `Tier "${tier.name}": base price cannot be below the floor ($${(config.priceFloor / 100).toFixed(2)}).` };
    }
    if (tier.basePrice > config.maxPrice) {
      return { ok: false, error: `Tier "${tier.name}": base price cannot exceed max price ($${(config.maxPrice / 100).toFixed(2)}).` };
    }
    if (tier.dropAmount < 0) {
      return { ok: false, error: `Tier "${tier.name}": drop amount cannot be negative.` };
    }
    if (tier.dropInterval < 1) {
      return { ok: false, error: `Tier "${tier.name}": drop interval must be at least 1 day.` };
    }
  }

  try {
    if (!existsSync(DATA_DIR)) {
      mkdirSync(DATA_DIR, { recursive: true });
    }
    writeFileSync(CONFIG_FILE, JSON.stringify(config, null, 2), "utf-8");
    // Invalidate cache
    _cache = config;
    _cacheTime = Date.now();
    return { ok: true };
  } catch (err) {
    return { ok: false, error: `Failed to write config: ${err instanceof Error ? err.message : "unknown error"}` };
  }
}

/**
 * useLeadForm — React hook for multi-step lead capture form.
 *
 * Encapsulates: multi-step state, per-step validation, throttled submission, error handling.
 */
import { useState, useEffect, FormEvent, useCallback, useRef } from "react";
import { trackFormStep, trackConversion } from "@/app/lib/analytics";

// Email validation
function validateEmail(email: string): boolean {
  if (typeof email !== "string") return false;
  const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return re.test(email) && email.length <= 254;
}

function validatePhone(phone: string): boolean {
  if (typeof phone !== "string") return false;
  const digits = phone.replace(/\D/g, "");
  return digits.length === 10 || (digits.length === 11 && digits.startsWith("1"));
}

function validateName(name: string): boolean {
  if (typeof name !== "string") return false;
  const trimmed = name.trim();
  return trimmed.length >= 2 && trimmed.length <= 100 && /^[a-zA-Z\s'.,-]+$/.test(trimmed);
}

// Date of birth with 18+ age gate
function validateDob(dob: string): boolean {
  if (typeof dob !== "string") return false;
  const match = dob.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return false;
  const year = parseInt(match[1], 10);
  const month = parseInt(match[2], 10);
  const day = parseInt(match[3], 10);
  if (month < 1 || month > 12 || day < 1 || day > 31) return false;
  if (year < 1900 || year > new Date().getFullYear()) return false;
  const date = new Date(year, month - 1, day);
  if (date.getFullYear() !== year || date.getMonth() !== month - 1 || date.getDate() !== day) return false;
  const today = new Date();
  const min18 = new Date(today.getFullYear() - 18, today.getMonth(), today.getDate());
  return date <= min18;
}

// Sanitize: trim + strip angle brackets
const sanitizeInput = (s: string) => s.trim().replace(/[<>]/g, "");

export const TCPA_CONSENT_TEXT =
  "By checking this box, I agree that Valor Legacies may contact me at the phone number I provided above, including by autodialed or prerecorded calls and text messages, for marketing purposes. I understand this consent is not required to obtain any product or service. Message and data rates may apply. I have read and agree to the Privacy Policy and Terms of Service.";

export interface LeadFormData {
  firstName: string;
  lastName: string;
  dateOfBirth: string;
  email: string;
  phone: string;
  state: string;
  coverageInterest: string;
  purchaseIntent: string;
  veteranStatus: string;
  militaryBranch: string;
  tcpaConsent: boolean;
  privacyConsent: boolean;
  // Honeypot field — must remain empty for humans
  _hp_website: string;
}

export interface LeadFormErrors {
  firstName?: string;
  lastName?: string;
  dateOfBirth?: string;
  email?: string;
  phone?: string;
  state?: string;
  coverageInterest?: string;
  purchaseIntent?: string;
  veteranStatus?: string;
  militaryBranch?: string;
  tcpaConsent?: string;
  privacyConsent?: string;
}

export const TOTAL_STEPS = 3;

/** Human-readable labels for each form field (used in missing-fields summary). */
export const FIELD_LABELS: Record<keyof LeadFormErrors, string> = {
  firstName: "First Name",
  lastName: "Last Name",
  dateOfBirth: "Date of Birth",
  email: "Email Address",
  phone: "Phone Number",
  state: "State",
  coverageInterest: "Coverage Interest",
  purchaseIntent: "How Serious Are You",
  veteranStatus: "Military Status",
  militaryBranch: "Branch of Service",
  tcpaConsent: "TCPA Consent",
  privacyConsent: "Privacy Policy Consent",
};

/** Which step each field belongs to, so we can navigate to the right step on error. */
export const FIELD_STEP: Record<keyof LeadFormErrors, number> = {
  firstName: 0, lastName: 0, dateOfBirth: 0, state: 0,
  coverageInterest: 0, purchaseIntent: 0, veteranStatus: 0, militaryBranch: 0,
  email: 1, phone: 1,
  tcpaConsent: 2, privacyConsent: 2,
};

export interface UseLeadFormReturn {
  form: LeadFormData;
  errors: LeadFormErrors;
  loading: boolean;
  submitted: boolean;
  confirmationMessage: string;
  leadId: string;
  serverError: string;
  step: number;
  totalSteps: number;
  submitAttempted: boolean;
  missingFields: { field: keyof LeadFormErrors; label: string; error: string }[];
  updateField: (field: keyof LeadFormData, value: string | boolean) => void;
  handleSubmit: (e: FormEvent) => void;
  nextStep: () => boolean;
  prevStep: () => void;
  goToStep: (step: number) => void;
}

/**
 * Step 0: Identity   — firstName, lastName, dateOfBirth, state, coverageInterest
 * Step 1: Contact    — email, phone
 * Step 2: Consent    — tcpaConsent, privacyConsent → submit
 */
function validateStep(step: number, form: LeadFormData): LeadFormErrors {
  const errs: LeadFormErrors = {};

  if (step === 0) {
    if (!validateName(sanitizeInput(form.firstName))) errs.firstName = "Please enter a valid first name.";
    if (!validateName(sanitizeInput(form.lastName))) errs.lastName = "Please enter a valid last name.";
    if (!form.dateOfBirth) {
      errs.dateOfBirth = "Please enter your date of birth.";
    } else if (!validateDob(form.dateOfBirth)) {
      errs.dateOfBirth = "You must be at least 18 years old to submit this form.";
    }
    if (!form.state) errs.state = "Please select your state.";
    if (!form.coverageInterest) errs.coverageInterest = "Please select a coverage interest.";
    if (!form.purchaseIntent) errs.purchaseIntent = "Please select your level of interest.";
    if (!form.veteranStatus) errs.veteranStatus = "Please select your military status.";
    if (form.veteranStatus && form.veteranStatus !== "non-military" && !form.militaryBranch) {
      errs.militaryBranch = "Please select your branch of service.";
    }
  }

  if (step === 1) {
    if (!validateEmail(sanitizeInput(form.email))) errs.email = "Please enter a valid email address.";
    if (!validatePhone(form.phone)) errs.phone = "Please enter a valid 10-digit US phone number.";
  }

  if (step === 2) {
    if (!form.tcpaConsent) errs.tcpaConsent = "Consent is required to be contacted.";
    if (!form.privacyConsent) errs.privacyConsent = "You must agree to the Privacy Policy and Terms.";
  }

  return errs;
}

/** Validate all 3 steps at once. Returns combined errors. */
function validateAllSteps(form: LeadFormData): LeadFormErrors {
  return {
    ...validateStep(0, form),
    ...validateStep(1, form),
    ...validateStep(2, form),
  };
}

// Form state persistence via localStorage
const STORAGE_KEY = "lead-form-draft";
const STORAGE_STEP_KEY = "lead-form-step";

function loadSavedForm(): { form: LeadFormData; step: number } | null {
  if (typeof window === "undefined") return null;
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    const stepRaw = localStorage.getItem(STORAGE_STEP_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as LeadFormData;
    // Never restore consent fields — user must re-check each session
    parsed.tcpaConsent = false;
    parsed.privacyConsent = false;
    return { form: parsed, step: stepRaw ? Math.min(parseInt(stepRaw, 10) || 0, TOTAL_STEPS - 1) : 0 };
  } catch {
    return null;
  }
}

function saveFormDraft(form: LeadFormData, step: number): void {
  if (typeof window === "undefined") return;
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(form));
    localStorage.setItem(STORAGE_STEP_KEY, String(step));
  } catch {
    // Storage full or unavailable — silently ignore
  }
}

function clearFormDraft(): void {
  if (typeof window === "undefined") return;
  try {
    localStorage.removeItem(STORAGE_KEY);
    localStorage.removeItem(STORAGE_STEP_KEY);
  } catch {
    // Silently ignore
  }
}

const INITIAL_FORM: LeadFormData = {
  firstName: "", lastName: "", dateOfBirth: "", email: "", phone: "",
  state: "", coverageInterest: "", purchaseIntent: "", veteranStatus: "", militaryBranch: "",
  tcpaConsent: false, privacyConsent: false, _hp_website: "",
};

export function useLeadForm(utmParams?: Record<string, string | null>): UseLeadFormReturn {
  const saved = useRef(loadSavedForm());
  const [form, setForm] = useState<LeadFormData>(saved.current?.form ?? INITIAL_FORM);
  const [errors, setErrors] = useState<LeadFormErrors>({});
  const [loading, setLoading] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const [confirmationMessage, setConfirmationMessage] = useState("");
  const [leadId, setLeadId] = useState("");
  const [serverError, setServerError] = useState("");
  const [step, setStep] = useState(saved.current?.step ?? 0);
  const [submitAttempted, setSubmitAttempted] = useState(false);

  // Track page load time for timing-based bot detection
  const pageLoadTime = useRef(Date.now());

  // --- Form state persistence: save draft on every change ---
  useEffect(() => {
    if (!submitted) {
      saveFormDraft(form, step);
    }
  }, [form, step, submitted]);

  // Throttle: prevent double-submissions (ref-based for stability)
  const lastSubmitRef = useRef(0);
  const THROTTLE_MS = 3000;

  const updateField = useCallback((field: keyof LeadFormData, value: string | boolean) => {
    setForm((prev) => {
      const next = { ...prev, [field]: value };
      // Clear military branch when status changes (user must re-select for new status)
      if (field === "veteranStatus") {
        next.militaryBranch = "";
      }
      return next;
    });
    setErrors((prev) => {
      const next = { ...prev };
      if (next[field as keyof LeadFormErrors]) {
        delete next[field as keyof LeadFormErrors];
      }
      // Clear military branch error when veteran status changes
      if (field === "veteranStatus" && next.militaryBranch) {
        delete next.militaryBranch;
      }
      return next;
    });
    setServerError("");
  }, []);

  // Validate current step and advance if valid. Returns true if step was valid.
  const nextStep = useCallback((): boolean => {
    const errs = validateStep(step, form);
    setErrors(errs);
    if (Object.keys(errs).length > 0) return false;
    const nextStepNum = Math.min(step + 1, TOTAL_STEPS - 1);
    setStep(nextStepNum);
    // Track step progression for funnel analysis
    const stepNames = ["Identity", "Contact", "Consent"];
    trackFormStep(nextStepNum, stepNames[nextStepNum] || `Step ${nextStepNum + 1}`);
    return true;
  }, [step, form]);

  const prevStep = useCallback(() => {
    setErrors({});
    setServerError("");
    setStep((prev) => Math.max(prev - 1, 0));
  }, []);

  const goToStep = useCallback((target: number) => {
    if (target >= 0 && target < TOTAL_STEPS && target !== step) {
      setStep(target);
    }
  }, [step]);

  async function submitLead(data: LeadFormData) {
    setLoading(true);
    setServerError("");
    try {
      // Fetch CSRF token before submission
      const csrfRes = await fetch("/api/csrf");
      const csrfData = csrfRes.ok ? await csrfRes.json() : { token: "" };

      const res = await fetch("/api/leads", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "X-CSRF-Token": csrfData.token,
        },
        body: JSON.stringify({
          firstName: sanitizeInput(data.firstName),
          lastName: sanitizeInput(data.lastName),
          dateOfBirth: data.dateOfBirth,
          email: sanitizeInput(data.email),
          phone: data.phone.replace(/\D/g, ""),
          state: data.state,
          coverageInterest: data.coverageInterest,
          purchaseIntent: data.purchaseIntent,
          veteranStatus: data.veteranStatus,
          militaryBranch: data.veteranStatus && data.veteranStatus !== "non-military" ? data.militaryBranch : "",
          tcpaConsent: data.tcpaConsent,
          privacyConsent: data.privacyConsent,
          consentTimestamp: new Date().toISOString(),
          consentText: TCPA_CONSENT_TEXT,
          // Honeypot + timing check
          _hp_website: data._hp_website,
          _hp_ts: pageLoadTime.current,
          // UTM tracking — persisted from session
          ...(utmParams ? filterNullValues(utmParams) : {}),
        }),
      });
      if (!res.ok) {
        const body = await res.json().catch(() => null);
        throw new Error(body?.message || `Request failed (${res.status})`);
      }
      const result = await res.json();
      setSubmitted(true);
      setLeadId(result.leadId || "");
      clearFormDraft(); // Clear saved draft on successful submission
      setConfirmationMessage(result.confirmationMessage || "Your request has been received. A licensed professional will be in touch soon.");
      // Fire conversion event
      trackConversion(result.leadId || "", data.coverageInterest, data.state);
    } catch (err) {
      setServerError(err instanceof Error ? err.message : "Something went wrong. Please try again.");
    } finally {
      setLoading(false);
    }
  }

  function handleSubmit(e: FormEvent) {
    e.preventDefault();
    setSubmitAttempted(true);

    // Validate ALL steps — not just the current one
    const errs = validateAllSteps(form);
    setErrors(errs);

    if (Object.keys(errs).length > 0) {
      // Find the earliest step that has an error and navigate there
      const errorFields = Object.keys(errs) as (keyof LeadFormErrors)[];
      const steps = errorFields.map((f) => FIELD_STEP[f]);
      const earliestStep = Math.min(...steps);
      if (earliestStep !== step) {
        setStep(earliestStep);
      }
      // Scroll to the first invalid field after React renders
      requestAnimationFrame(() => {
        const firstErrorField = errorFields
          .sort((a, b) => FIELD_STEP[a] - FIELD_STEP[b])[0];
        const el = document.getElementById(String(firstErrorField));
        if (el) {
          el.scrollIntoView({ behavior: "smooth", block: "center" });
          el.focus();
        }
      });
      return;
    }

    // Throttle guard
    const now = Date.now();
    if (now - lastSubmitRef.current < THROTTLE_MS) return;
    lastSubmitRef.current = now;

    submitLead(form);
  }

  // Build the missing-fields list from current errors (for UI summary)
  const missingFields = (Object.keys(errors) as (keyof LeadFormErrors)[])
    .filter((f) => errors[f])
    .sort((a, b) => FIELD_STEP[a] - FIELD_STEP[b])
    .map((f) => ({ field: f, label: FIELD_LABELS[f], error: errors[f]! }));

  return {
    form, errors, loading, submitted, confirmationMessage, leadId, serverError,
    step, totalSteps: TOTAL_STEPS, submitAttempted, missingFields,
    updateField, handleSubmit, nextStep, prevStep, goToStep,
  };
}

/** Strip null values from UTM params for API submission */
function filterNullValues(obj: Record<string, string | null>): Record<string, string> {
  const result: Record<string, string> = {};
  for (const [key, value] of Object.entries(obj)) {
    if (value !== null) result[key] = value;
  }
  return result;
}

/**
 * CRM Integration Layer
 *
 * Unified interface to push leads to HubSpot or Salesforce.
 * Uses circuit breaker for fault tolerance and retry for transient failures.
 *
 * Environment variables:
 *   CRM_PROVIDER      — "hubspot", "salesforce", or empty (no-op)
 *   CRM_API_KEY       — API key / Bearer token for the CRM
 *   CRM_INSTANCE_URL  — Salesforce instance URL (e.g., https://myorg.my.salesforce.com)
 */

import { withCircuitBreaker, CircuitOpenError } from "./circuit-breaker";

// --- Retry with exponential backoff ---
async function retry<T>(
  fn: () => Promise<T>,
  maxRetries: number = 2,
  delay: number = 1000,
): Promise<T> {
  let lastError: unknown;
  for (let i = 0; i <= maxRetries; i++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
      if (i < maxRetries) {
        await new Promise((r) => setTimeout(r, delay * Math.pow(2, i)));
      }
    }
  }
  throw lastError;
}

/** Coverage labels for CRM field mapping */
const COVERAGE_LABELS: Record<string, string> = {
  term: "Term Life",
  whole: "Whole Life",
  universal: "Universal Life",
  "final-expense": "Final Expense",
  annuity: "Annuity",
  "not-sure": "Needs Guidance",
};

export interface CrmLead {
  leadId: string;
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
  state: string;
  coverageInterest: string;
  veteranStatus: string;
  utmSource?: string | null;
  utmMedium?: string | null;
  utmCampaign?: string | null;
}

/**
 * Push a lead to the configured CRM provider.
 *
 * If CRM_PROVIDER is not set, this is a no-op.
 * Uses circuit breaker to prevent cascading failures if the CRM is down.
 */
export async function pushLeadToCrm(lead: CrmLead): Promise<void> {
  const provider = process.env.CRM_PROVIDER?.toLowerCase();

  if (!provider) {
    return; // No CRM configured — silent no-op
  }

  switch (provider) {
    case "hubspot":
      await pushToHubSpot(lead);
      break;
    case "salesforce":
      await pushToSalesforce(lead);
      break;
    default:
      console.warn(`[CRM] Unknown CRM_PROVIDER: "${provider}". Supported: hubspot, salesforce.`);
  }
}

/**
 * Push a lead to HubSpot CRM via the Contacts API v3.
 */
async function pushToHubSpot(lead: CrmLead): Promise<void> {
  const apiKey = process.env.CRM_API_KEY;
  if (!apiKey) {
    console.warn("[CRM][HubSpot] CRM_API_KEY is not set. Skipping CRM push.");
    return;
  }

  const coverageLabel = COVERAGE_LABELS[lead.coverageInterest] || lead.coverageInterest;

  const payload = {
    properties: {
      firstname: lead.firstName,
      lastname: lead.lastName,
      email: lead.email,
      phone: lead.phone,
      state: lead.state,
      hs_lead_status: "NEW",
      military_branch: lead.veteranStatus,
      coverage_interest: coverageLabel,
      ...(lead.utmSource ? { utm_source: lead.utmSource } : {}),
      ...(lead.utmMedium ? { utm_medium: lead.utmMedium } : {}),
      ...(lead.utmCampaign ? { utm_campaign: lead.utmCampaign } : {}),
    },
  };

  try {
    await withCircuitBreaker(
      () =>
        retry(async () => {
          const res = await fetch("https://api.hubapi.com/crm/v3/objects/contacts", {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${apiKey}`,
            },
            body: JSON.stringify(payload),
            signal: AbortSignal.timeout(15000),
          });

          if (!res.ok) {
            const errorBody = await res.text();
            // 409 = contact already exists — not a failure
            if (res.status === 409) {
              console.log(`[CRM][HubSpot] Contact already exists for ${lead.email} — skipping.`);
              return;
            }
            throw new Error(`HubSpot API error: ${res.status} ${errorBody}`);
          }

          console.log(`[CRM][HubSpot] Contact created for lead ${lead.leadId}`);
        }, 2, 1000),
      { name: "crm-hubspot", failureThreshold: 5, resetTimeout: 120_000 },
    );
  } catch (err) {
    if (err instanceof CircuitOpenError) {
      console.warn(`[CRM][HubSpot] Circuit open — skipping push for lead ${lead.leadId}. ${err.message}`);
    } else {
      throw err;
    }
  }
}

/**
 * Push a lead to Salesforce CRM via the REST API.
 */
async function pushToSalesforce(lead: CrmLead): Promise<void> {
  const apiKey = process.env.CRM_API_KEY;
  const instanceUrl = process.env.CRM_INSTANCE_URL;

  if (!apiKey) {
    console.warn("[CRM][Salesforce] CRM_API_KEY is not set. Skipping CRM push.");
    return;
  }
  if (!instanceUrl) {
    console.warn("[CRM][Salesforce] CRM_INSTANCE_URL is not set. Skipping CRM push.");
    return;
  }

  const coverageLabel = COVERAGE_LABELS[lead.coverageInterest] || lead.coverageInterest;

  const payload: Record<string, string> = {
    FirstName: lead.firstName,
    LastName: lead.lastName,
    Email: lead.email,
    Phone: lead.phone,
    State: lead.state,
    Status: "Open - Not Contacted",
    LeadSource: "Web",
    Description: `Coverage Interest: ${coverageLabel}. Veteran Status: ${lead.veteranStatus}. Ref: ${lead.leadId}`,
  };

  if (lead.utmSource) payload.UTM_Source__c = lead.utmSource;
  if (lead.utmMedium) payload.UTM_Medium__c = lead.utmMedium;
  if (lead.utmCampaign) payload.UTM_Campaign__c = lead.utmCampaign;

  const url = `${instanceUrl.replace(/\/$/, "")}/services/data/v58.0/sobjects/Lead/`;

  try {
    await withCircuitBreaker(
      () =>
        retry(async () => {
          const res = await fetch(url, {
            method: "POST",
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${apiKey}`,
            },
            body: JSON.stringify(payload),
            signal: AbortSignal.timeout(15000),
          });

          if (!res.ok) {
            const errorBody = await res.text();
            throw new Error(`Salesforce API error: ${res.status} ${errorBody}`);
          }

          console.log(`[CRM][Salesforce] Lead created for ${lead.leadId}`);
        }, 2, 1000),
      { name: "crm-salesforce", failureThreshold: 5, resetTimeout: 120_000 },
    );
  } catch (err) {
    if (err instanceof CircuitOpenError) {
      console.warn(`[CRM][Salesforce] Circuit open — skipping push for lead ${lead.leadId}. ${err.message}`);
    } else {
      throw err;
    }
  }
}

